///@brief talk parameter
typedef struct __NET_SPEAK_PARAM
{
	DWORD           dwSize;                     // struct size 
	int             nMode;                      // 0:talk back(default), 1: propaganda,from propaganda ro talk back,need afresh to configure
												// 2:unidirectional monitoring, if want to set other mode, need afresh to configure
												// 3:IPSpeaker broadcasting message, DEPRECATED: This value is no longer used,
	int             nSpeakerChannel;            // reproducer channel
    BOOL            bEnableWait;                // Wait for device to responding or not when enable bidirectional talk. Default setup is no.TRUE:wait ;FALSE:no
	int				nTalkDeviceMode; 			// Intercom device type 0: Default, 1: IP speaker // DEPRECATED: This field is no longer used,
	int 			nIPSpeakerChannelCount; 	// Number of IP speaker broadcasting channels // DEPRECATED: This field is no longer used,
	int*			nIPSpeakerChannel;          // IP speaker broadcasting channels // DEPRECATED: This field is no longer used,
	int				bEnableRender;				 //  0: Default, 1: Supported for local recording and intercom in non-Windows scenarios.
	int 			nCount;						// device num
	char			szDeviceIDs[MAX_LINK_DEVICE_NUM][DH_MAX_STRING_LEN];	// device id list
} NET_SPEAK_PARAM;

