///@brief Time section                                                                
typedef struct tagDH_TSECT
{
	int             bEnable;                        // When it indicates the recording time period, the bit means four enable, from low to high respectively it means motion detection recording, alarm recording, ordinary recording, motion detection and alarm occur at the same time to record.
	// When it means the arming and disarming time period, it means enabling
	// When it means the push time period, it means enabled: 1 means enabled, 0 means unable
	int             iBeginHour;
	int             iBeginMin;
	int             iBeginSec;
	int             iEndHour;
	int             iEndMin;
	int             iEndSec;
} DH_TSECT, *LPDH_TSECT, NET_TSECT;

///@brief Time Schedule
typedef struct tagNET_CFG_TIME_SCHEDULE
{
	BOOL                    bEnableHoliday;                                                 // Whether to support the holiday configuration, the default is not supported, unless the configuration is returned to TRUE, do not enable the holiday configuration
	DH_TSECT                stuTimeSection[DH_N_SCHEDULE_TSECT][DH_N_REC_TSECT];            // The first 7 elements of the first dimension correspond to 7 days of a week, and the 8th element corresponds to holidays, with a maximum of 6 time periods per day
} NET_CFG_TIME_SCHEDULE;

