///@brief information data, for sending only
typedef struct tagNET_ACCESSCTLCARD_FINGERPRINT_PACKET
{
    DWORD   dwSize;
    int     nLength;        // length of a infomation packet, unit: byte
    int     nCount;         // packet number 
    char*   pPacketData;    // all information packet in a single buffer, allocated and filled by user, nLength*nCount bytes
}NET_ACCESSCTLCARD_FINGERPRINT_PACKET;

///@brief information data, for sending and receiving
typedef struct tagNET_ACCESSCTLCARD_FINGERPRINT_PACKET_EX
{
    int     nLength;        // length of a infomation packet, unit: byte
    int     nCount;         // packet number 
    char*   pPacketData;    // all information packet in a single buffer, allocated by user,the space application is over nLength * nCount
    int     nPacketLen;     // pPacketData buffer length, set by user
    int     nRealPacketLen; // The actual information size returned to the user, equal to nLength*nCount
    int     nDuressIndex;   // duress index of information group, range: 1~nCount
	char	szReserved[4];				/// byte alignment
	char	szFingerPrintName[3][32];	/// Fingerprint name array, with the same number of items as the number of fingerprint packages nCount
    BYTE    byReverseed[920]; //Reserved size 
}NET_ACCESSCTLCARD_FINGERPRINT_PACKET_EX;

