///@brief Access control card swiping record set information
typedef struct tagNET_RECORDSET_ACCESS_CTL_CARDREC
{
    DWORD           dwSize;
    int             nRecNo;                                 // Record Number,Read-Only
    char            szCardNo[DH_MAX_CARDNO_LEN];            // Card Number
    char            szPwd[DH_MAX_CARDPWD_LEN];              // Password
    NET_TIME        stuTime;                                // Swing Card Time
    BOOL            bStatus;                                // Swing Card Result,True is Success,False is Fail
    NET_ACCESS_DOOROPEN_METHOD    emMethod;                 // Open Door Method
    int             nDoor;                                  // Door Number,That is CFG_CMD_ACCESS_EVENT Configure Array Subscript 
    char            szUserID[DH_MAX_USERID_LEN];            // user ID
    int             nReaderID;                              // card reader ID (abandoned)
    char            szSnapFtpUrl[MAX_PATH];                 // unlock snap upload ftp url
    char            szReaderID[DH_COMMON_STRING_32];        // card reader ID
    NET_ACCESSCTLCARD_TYPE      emCardType;                         // Card Type
    int                         nErrorCode;                         // Reason of unlock failure, only because it is valid when bStatus is FALSE
                                                                    // 0x00 no error
                                                                    // 0x10 unauthorized
                                                                    // 0x11 card lost or cancelled
                                                                    // 0x12 no door right
                                                                    // 0x13 unlock mode error
                                                                    // 0x14 valid period error
                                                                    // 0x15 anti sneak into mode
                                                                    // 0x16 forced alarm not unlocked
                                                                    // 0x17 door NC status
                                                                    // 0x18 AB lock status
                                                                    // 0x19 patrol card
                                                                    // 0x1A device is under intrusion alarm status
                                                                    // 0x20 period error
                                                                    // 0x21 unlock period error in holiday period
																	// 0x23 Card is overdue
                                                                    // 0x30 first card right check required
                                                                    // 0x40 card correct, input password error
                                                                    // 0x41 card correct, input password timed out
                                                                    // 0x42 card correct, input information error
                                                                    // 0x43 card correct, input information timed out
                                                                    // 0x44 information correct, input password error
                                                                    // 0x45 information correct, input password timed out
                                                                    // 0x50 group unlock sequence error
                                                                    // 0x51 test required for group unlock
                                                                    // 0x60 test passed, control unauthorized
                                                                    // 0x61 card correct, input target error
                                                                    // 0x62 card correct, input target timed out
                                                                    // 0x63 repeat enter
                                                                    // 0x64 unauthorized, requiring back-end platform identification
                                                                    // 0x65 High body temperature
																	// 0x66	no mask
																	// 0x67 get health code fail
																	// 0x68 No Entry because of yellow code
																	// 0x69 No Entry because of red code
																	// 0x6a health code is invalid
																	// 0x6b entry because of green code
																	// 0x6c Green code, nucleic acid is abnormal
																	// 0x6d Green code, not vaccinated
																	// 0x6f Green code, antigen antigen
																	// 0x70 get health code info
																	// 0xB6 Lock not connected

    char           szRecordURL[MAX_COMMON_STRING_128];              // record url
    int            nNumbers;                                        // snap picture numbers
    NET_ATTENDANCESTATE         emAttendanceState;                  // attendance state 
    NET_ENUM_DIRECTION_ACCESS_CTL   emDirection;                    // open door direction
	char						szClassNumber[MAX_CLASS_NUMBER_LEN];	// Class number
	char						szPhoneNumber[MAX_PHONENUMBER_LEN];		// Phone number
	char						szCardName[DH_MAX_CARDNAME_LEN];		// Card name
    char                        szSN[DH_COMMON_STRING_32];              // wireless device serial number

	BOOL						bCitizenIDResult;							// Compare result
	char						szCitizenIDName[30];						// Name
	BYTE						nRedScarfResult;							// Red scarf recognition result 0: unknown 1: not worn 2: worn; 255: Algorithm recognition not enabled
	BYTE						byReserved1[1];								// Align
	EM_CITIZENIDCARD_SEX_TYPE			emCitizenIDSex;						// Sex
	EM_CITIZENIDCARD_EC_TYPE		emCitizenIDEC;				// EC Type
	NET_TIME					stuCitizenIDBirth;						// Birth date
	char						szCitizenIDAddress[108];					// Address
	char						szCitizenIDAuthority[48];					// Authority
	NET_TIME					stuCitizenIDStart;						// Start time
	NET_TIME					stuCitizenIDEnd;							// End time
	BOOL						bIsEndless;									// Is end time unlimited
	char						szSnapFaceURL[DH_COMMON_STRING_128];		// target picture URL
	char						szCitizenPictureURL[DH_COMMON_STRING_128];	// card picture URL
	char						szCitizenIDNo[20];							// card card number
    NET_ACCESSCTLCARD_SEX       emSex;                                      // sex
    char                        szRole[MAX_COMMON_STRING_32];               // role
    char                        szProjectNo[MAX_COMMON_STRING_32];          // project No.
    char                        szProjectName[MAX_COMMON_STRING_64];        // project name
    char                        szBuilderName[MAX_COMMON_STRING_64];        // builder name
    char                        szBuilderID[MAX_COMMON_STRING_32];          // builder ID
    char                        szBuilderType[MAX_COMMON_STRING_32];        // builder type
    char                        szBuilderTypeID[MAX_COMMON_STRING_8];       // builder type ID
    char                        szPictureID[MAX_COMMON_STRING_64];          // picture ID
    char                        szContractID[MAX_COMMON_STRING_16];         // contract ID in original contract system
    char                        szWorkerTypeID[MAX_COMMON_STRING_8];        // worker type ID
    char                        szWorkerTypeName[MAX_COMMON_STRING_32];     // worker type name
    BOOL                        bPersonStatus;                              // person status, TRUE:enable, FALSE:forbidden
	EM_HAT_STYLE				emHatStyle;									// hat style
	EM_UNIFIED_COLOR_TYPE		emHatColor;									// hat color
	NET_MAN_TEMPERATURE_INFO	stuManTemperatureInfo;						// human temperature info
	int							nCompanionInfo;								// stuCompanionInfo's count
	NET_COMPANION_INFO			stuCompanionInfo[12];						// companion info:name and card valid
	EM_MASK_STATE_TYPE			emMask;										// mask ( EM_MASK_STATE_UNKNOWN,EM_MASK_STATE_NOMASK,EM_MASK_STATE_WEAR is valid )
	UINT						nFaceIndex;									// target index
	int							nScore;										// target quality score
	int							nLiftNo;									// Elevator number
    char                        szQRCode[512];                              // QRCode
	EM_FACE_CHECK				emFaceCheck;								// when swiping the card to open the door, the access control background checks whether the target is the same person
	EM_QRCODE_IS_EXPIRED		emQRCodeIsExpired;							// Whether the QR code has expired. Default value 0s
	EM_QRCODE_STATE				emQRCodeState;								// QR code status 
	NET_TIME        			stuQRCodeValidTo;							// QR code deadline
	EM_LIFT_CALLER_TYPE			emLiftCallerType;							// Ladder control trigger
	UINT						nBlockId;									// The serial number of the reported event data increases from 1
	char						szSection[64];								// Department name
	char						szWorkClass[256];							// Work class
	EM_TEST_ITEMS				emTestItems;								// Test items
	NET_TEST_RESULT				stuTestResult;								// ESD resistance test result
	BOOL						bUseCardNameEx;								// Whether to use the card name extension
	char						szCardNameEx[128];							// Card name extension
	int							nHSJCResult;								// Nucleic acid test report result, -1: Unknow 0: abnormal, 1: normal, 2: not tested, 3: expired
	int                       	nVaccinateFlag;                        		//Have you been vaccinated against the new crown vaccine, 0: No, 1: Yes
	char                    	szVaccineName[128];              			//New crown vaccine name
	int                       	nDateCount;                           		//Valid number of historical vaccination dates
	char                    	szVaccinateDate[8][32];           			//Historical vaccination date(yyyy-MM-dd). If you cannot provide the time, fill in "0000-00-00", which means that you have been vaccinated
	EM_TRAVEL_CODE_COLOR        emTravelCodeColor;                          //Travel Code Color
	int                         nCityCount;                                 //Number of cities passed in the last 14 days
	char                        szPassingCity[16][128];                     //The names of the cities that have passed in the last 14 days. In chronological order, the earliest passing city is placed first
	char						szTrafficPlate[32];							//TrafficPlate
	char						szRecordLocalUrl[128];						// Record Url
	char						szHSJCReportDate[32];						// Date of nucleic acid test report (format: yyyy-MM-dd)
	int							nHSJCExpiresIn;								// Validity period of nucleic acid test report (unit: day)
	char						szAntigenReportDate[32];					// Antigen test report date (format: yyyy-MM-dd)
	int							nAntigenStatus;								// Antigen Test Report Result: -1: Unknown 0: abnormal 1: normal 2: Not Tested 3: Expired
	int							nAntigenExpiresIn;							// Validity period of antigen test report (unit: day)
	char						szCheckOutType[32];							// Check Out Type
	char						szCheckOutCause[512];						// Check out Reason
	UINT                        nCreateTimeRealUTC;                         // Swipe time, real UTC time
    char                        szReserved[20];                             // reserved
	char						szLocationName[256];						// Location Name
	char						szLocationAddress[256];						// Location Address
	char						szLocationType[256];						// Location Type						
	int nPassResult; /// Pass result, whether the person is accompanied or not: 0-unknown, 1-person enters, 2-person exits, 3-person fails to pass.
	int nCustomerPWDType; /// Password type reported by the device in different password modes: 0: unknown, 1: wake-up password mode, 2: accompanying password mode, 3: coercion password mode
	char						szUserIDEx[128];				        	// UserID Extend, support 32-bit valid values
	char						szRoomNumber[32];							// Room Number
	TP_U64						nAKID;										/// Bluetooth card number
	char						szBTCardNo[32];								/// Bluetooth card number
}NET_RECORDSET_ACCESS_CTL_CARDREC;

