///@brief Consumption Record
typedef struct tagNET_RECORD_ACCESS_CTL_CONSUMPTION_INFO
{
	DWORD						dwSize;							// struct size
	UINT                       	nRecNo;                         // Record No
	UINT                       	nBlockId;                       // serial number, start 1
	NET_TIME                   	stuCreateTime;                  // Time of occurrence(UTC time)	 
	char						szCardNo[16];					// Card No	
	char						szCardName[128];				// Card Name
	NET_ACCESSCTLCARD_TYPE 		emCardType;				 		// Card Type
	char						szUserID[12];					// User ID
	NET_ENUM_DIRECTION_ACCESS_CTL   emType;						// Type
	EM_CONSUMPTION_STATUS		emStatus;						// Status
	NET_ACCESS_DOOROPEN_METHOD	emMethod;						// Method
	UINT						nDoor;							// Door No
	char						szReaderID[32];					// Reader ID
	UINT                        nErrorCode;                     // Reason of unlock failure, only because it is valid when emStatus is fail
                                                                // 0x00 no error
                                                                // 0x10 unauthorized
                                                                // 0x11 card lost or cancelled
                                                                // 0x12 no door right
                                                                // 0x13 unlock mode error
                                                                // 0x14 valid period error
                                                                // 0x15 anti sneak into mode
                                                                // 0x16 forced alarm not unlocked
                                                                // 0x17 door NC status
                                                                // 0x18 AB lock status
                                                                // 0x19 patrol card
                                                                // 0x1A device is under intrusion alarm status
                                                                // 0x20 period error
                                                                // 0x21 unlock period error in holiday period
                                                                // 0x30 first card right check required
                                                                // 0x40 card correct, input password error
                                                                // 0x41 card correct, input password timed out
                                                                // 0x42 card correct, input information error
                                                                // 0x43 card correct, input information timed out
                                                                // 0x44 information correct, input password error
                                                                // 0x45 information correct, input password timed out
                                                                // 0x50 group unlock sequence error
                                                                // 0x51 test required for group unlock
                                                                // 0x60 test passed, control unauthorized
                                                                // 0x61 card correct, input target error
                                                                // 0x62 card correct, input target timed out
                                                                // 0x63 repeat enter
                                                                // 0x64 unauthorized, requiring back-end platform identification
                                                                // 0x65 High body temperature
																// 0x66	no mask
																// 0x67 get health code fail
																// 0x68 No Entry because of yellow code
																// 0x69 No Entry because of red code
																// 0x6a health code is invalid
																// 0x6b entry because of green code
																// 0x70 get health code info
	
	UINT                        nSimilarity;                    // Similarity
	char						szSnapFaceURL[128];				// Snap target Path
	EM_CONSUMPTION_RECORD_TYPE	emRecordType;					// Record Type
	UINT                        nConsumptionAmount;             // Consumption Amount,unit is cent
	UINT                        nRechargeAmount;                // Recharge Amount,unit is cent
	char						szTransactionSerialNumber[128];	// transactional number
}NET_RECORD_ACCESS_CTL_CONSUMPTION_INFO;

