///@brief access control event
typedef struct tagALARM_ACCESS_CTL_EVENT_INFO 
{
    DWORD                       dwSize;
    int                         nDoor;                              // Door Channel Number
    char                        szDoorName[DH_MAX_DOORNAME_LEN];    // Entrance Guard Name
    NET_TIME                    stuTime;                            // Alarm Event Triggered Time
    NET_ACCESS_CTL_EVENT_TYPE   emEventType;                        // Entrance Guard Event Type
    BOOL                        bStatus;                            // Swing Card Result,True is Success,False is Fail
    NET_ACCESSCTLCARD_TYPE      emCardType;                         // Card Type
    NET_ACCESS_DOOROPEN_METHOD  emOpenMethod;                       // Open The Door Method
    char                        szCardNo[DH_MAX_CARDNO_LEN];        // Card Number
    char                        szPwd[DH_MAX_CARDPWD_LEN];          // Password
    char                        szReaderID[DH_COMMON_STRING_32];    // Reader ID
    char                        szUserID[DH_COMMON_STRING_64];      // unlock user
    char                        szSnapURL[DH_COMMON_STRING_256];    // snapshot picture storage address
    int                         nErrorCode;                         // Open door operate code, use with bStatus
                                                                    // 0x00 no error
                                                                    // 0x10 unauthorized
                                                                    // 0x11 card lost or cancelled
                                                                    // 0x12 no door right
                                                                    // 0x13 unlock mode error
                                                                    // 0x14 valid period error
                                                                    // 0x15 anti sneak into mode
                                                                    // 0x16 forced alarm not unlocked
                                                                    // 0x17 door NC status
                                                                    // 0x18 AB lock status
                                                                    // 0x19 patrol card
                                                                    // 0x1A device is under intrusion alarm status
                                                                    // 0x20 period error
                                                                    // 0x21 unlock period error in holiday period
																	// 0x23 Card is overdue
                                                                    // 0x30 first card right check required
                                                                    // 0x40 card correct, input password error
                                                                    // 0x41 card correct, input password timed out
                                                                    // 0x42 card correct, input information error
                                                                    // 0x43 card correct, input information timed out
                                                                    // 0x44 information correct, input password error
                                                                    // 0x45 information correct, input password timed out
                                                                    // 0x50 group unlock sequence error
                                                                    // 0x51 test required for group unlock
																	// 0x53 backend needs to perform a comparison for authentication.
                                                                    // 0x60 test passed, control unauthorized
                                                                    // 0x61 card correct, target error
                                                                    // 0x62 card correct,target timeout
                                                                    // 0x63 repeat enter
                                                                    // 0x64 unauthorized, requiring back-end platform identification
                                                                    // 0x65 high body temperature
																	// 0x66	no mask
																	// 0x67 get health code fail
																	// 0x68 No Entry because of yellow code
																	// 0x69 No Entry because of red code
																	// 0x6a health code is invalid
																	// 0x6b entry because of green code
																	// 0x6e Green code, travel code not green code
																	// 0x6f Green code, antigen antigen
																	// 0x70 get health code info
																	// 0x71 verify card Id (platform issues the verification result of the corresponding card Id)
																	// 0xA8 not wear safety helmet 
																	// 0xB1 insufficient authorization information, to be supplemented
																	// 0xB2 centralized interlock
																	// 0xB6 Lock not connected
    int                         nPunchingRecNo;                     // punching record number 
	int							nNumbers;							// pic Numbers	
    NET_ACCESSCTLCARD_STATE     emStatus;		                    // Card Status
    char                        szSN[32];                           // wireless deivce serial number
    NET_ATTENDANCESTATE         emAttendanceState;                  // attend state
    char                        szQRCode[512];                      // QRcode
    char                        szCallLiftFloor[16];				// Floor of Call Lift
	EM_CARD_STATE				emCardState;                        // Collect as card or not
	char						szCitizenIDNo[20];					// card ID
	char				        szCompanionCards[MAX_COMPANION_CARD_NUM][DH_MAX_CARDINFO_LEN];    // The companion cards list
	int				            nCompanionCardCount;				// The number of companion cards 
	EM_HAT_STYLE				emHatStyle;							// hat style
	EM_UNIFIED_COLOR_TYPE		emHatColor;							// hat color
	EM_LIFT_CALLER_TYPE			emLiftCallerType;					// lift caller type
	BOOL						bManTemperature;					// Whether the information of human body temperature is valid
	NET_MAN_TEMPERATURE_INFO	stuManTemperatureInfo;				// Information of human body temperature, It is valid whne bManTemperature is TURE
	char						szCitizenName[256];					// card name
	EM_MASK_STATE_TYPE			emMask;								// mask ( EM_MASK_STATE_UNKNOWN,EM_MASK_STATE_NOMASK,EM_MASK_STATE_WEAR is valid )
	char						szCardName[DH_MAX_CARDNAME_LEN];	// card name
	UINT						nFaceIndex;							// target index
	EM_USER_TYPE                emUserType;							// user type( from EM_USER_TYPE_ORDINARY to EM_USER_TYPE_DISABLED is valid )
	BOOL						bRealUTC;							// whether RealUTC is valid. when bRealUTC is TRUE, use RealUTC, otherwise use stuTime
	NET_TIME_EX         		RealUTC;                            // event occur time
	char						szCompanyName[200];					// Company Address
	int							nScore;							    // target Quality
	int							nLiftNo;							// Elevator number
	EM_QRCODE_IS_EXPIRED		emQRCodeIsExpired;					// Whether the QR code has expired. Default value 0;
	EM_QRCODE_STATE				emQRCodeState;						// QR code status
	NET_TIME        			stuQRCodeValidTo;                   // QR code deadline
	char						szDynPWD[32];						// The platform verifies permissions by password. Used for dynamic password verification. The dynamic password is generated by the mobile APP, and the device is only transparently transmitted to the platform
	UINT						nBlockId;							// The serial number of the reported event data increases from 1
	char						szSection[64];						// Department name
	char						szWorkClass[256];					// Work class
	EM_TEST_ITEMS				emTestItems;						// Test items
	NET_TEST_RESULT				stuTestResult;						// ESD resistance test result
	char                        szDeviceID[128];                    // Access control equipment number
	char                        szUserUniqueID[128];                // User unique ID
	BOOL						bUseCardNameEx;						// Whether to use the card name extension
	char						szCardNameEx[128];					// Card name extension
	char						szTempPassword[64];					// tmp passwd
	char						szNote[512];						// Note
	int									nHSJCResult;			// Nucleic acid test report result, -1: Unknow 0: abnormal, 1: normal, 2: not tested, 3: expired
	NET_VACCINE_INFO					stuVaccineInfo;							// New crown vaccination information
	NET_TRAVEL_INFO					stuTravelInfo;								// Trip code information
	char                        szQRCodeEx[2048];                   // used to upload large QR code content
	NET_HSJC_INFO				stuHSJCInfo;						// Nucleic acid detection information
	NET_ANTIGEN_INFO			stuAntigenInfo;						// Antigen Test Information
	char                        szHealthGreenStatus[20];            // Personal health status Green Code:"Green" Red code:"Red" Yellow code:"Yellow" Orange code:"Orange" unknown:"None"
	int                         nAge;                               // Age
	char						szCheckOutType[32];					// Check Out Type
	char						szCheckOutCause[512];				// Check out Reason
	int 						nTargetCheck;						// When swiping the card to open the door, check whether the background target of access control is the same person
																	// 0:This person has no target data
																	// 1:Card swiping is consistent with target personnel
																	// 2:Card swiping and target personnel are inconsistent
	NET_ACCESS_CTL_OBJECT_PROPERTIES	 stuObjectProperties; 		// Dynamically Recognized Structured Information Objects
	NET_BUTTON_CONTROL_INFO		stuButtonControlInfo;				/// Button control authentication information
	UINT						nSimilarity;						/// Facial target recognition similarity, effective when opening the door, range: 0-100
	int nPassResult; /// Pass result, whether the person is accompanied or not: 0-unknown, 1-person enters, 2-person exits, 3-person fails to pass.
	int nCustomerPWDType; /// Password type reported by the device in different password modes: 0: unknown, 1: wake-up password mode, 2: accompanying password mode, 3: coercion password mode
	char						szOperatorID[36];					// Operator ID, remote open door
	char						szTransmissionUuid[64];				// Transmission Uuid
	TP_U64						nAKID;								/// Bluetooth card number
	char						szBTCardNo[32];						/// Bluetooth card number
	int							nRemoteQRCodeType;					/// The type of QR code reported when opening the door remotely via QR code, 0- default value, 1- visitor QR code, 2- one-card QR code
	char                        szReserved[1212];                   // Reserved    
}ALARM_ACCESS_CTL_EVENT_INFO;
