///@brief picture info
typedef struct  
{
	DWORD                dwOffSet;                      // current picture file's offset in the binary file, byte
	DWORD                dwFileLenth;                   // current picture file's size, byte
	WORD                 wWidth;                        // picture width, pixel
	WORD                 wHeight;                       // picture high, pixel
    char*                pszFilePath;                   // File path
                                                        // User use this field need to apply for space for copy and storage
    BYTE            	 bIsDetected;					// When submit to the server, the algorithm has checked the image or not 
	BYTE				 bReserved[2];					// reserved data
    BYTE                 byQulityScore;                 // Quality score of target capture, range: 0-100
	int					 nFilePathLen;					// File path Len of pszFilePath
	DH_POINT			 stuPoint;						// The upper left corner of the figure is in the big picture. Absolute coordinates are used
	UINT				 nIndexInData;					// The serial number of the picture in the uploaded picture data
}DH_PIC_INFO;

///@brief Image information
typedef struct tagNET_RECOGNITION_PIC_INFO
{
	BOOL            bIsDetected;           /// Whether the image was detected by the algorithm when submitted to the recognition server, 
														/// no need to detect and locate the cutout again, 1: detected, 0: not detected
    UINT            nOffSet;                      /// Offset of the file in the binary data block, unit: bytes
    UINT            nLength;                    /// File size, unit: bytes
    UINT            nWidth;                         /// Image width
    UINT            nHeight;                        /// Image height
    char				szFilePath[256];              /// File path
	char				szPictureID[32];              /// Image ID
	UINT			nFeatureState;					/// The modeling status of this image 0-unknown
																/// 1 - Modeling failed, it may be that the image does not meet the requirements and needs to be replaced with another image
																/// 2 - There are available feature values (only one image needs to be computed for feature values)
																/// 3 - Feature values are being calculated (the actual calculation process usually takes only a few dozen milliseconds, mainly used when reconstructing fce feature values in batches, for fces that are behind in the batch queue. When there are no feature values, it will switch to this state)
																/// 4 - Modeled, but algorithm upgrade caused data to become unusable, need to re-model
	UINT			nFeatureErrCode;				/// Reason for modeling failure, only used when the modeling status is modeling failure
																/// 0 - Unknown
																/// 1 - Image format issue
																/// 2 - No person or not clear enough
																/// 3 - Multiple persons
																/// 4 - Image decoding failed
																/// 5 - Not recommended for database entry
																/// 6 - Database operation failed 
																/// 7 - Failed to get image
																/// 8 - System exception (e.g., License expiration, modeling analyzer not started causing failure)
																/// 9 - Horizontal angle
																/// 10 - Pitch angle
																/// 11 - Maximum proportion of person in the entire image
																/// 12 - Minimum proportion of person in the entire image
																/// 13 - Person distance size
																/// 14 - Person attribute judgment
																/// 15 - Person alignment score
	UINT			nPicOperate;					/// Operation on the image during modification. Absence of this field or a value of 0 indicates modification of the image. 0 - modify, 1 - add, 2 - delete
	UINT			nIndexInData;					/// Index of the image in the uploaded image data
	char                            szReserved[188]; /// Reserved bytes for future expansion.
} NET_RECOGNITION_PIC_INFO;

