///@brief Radar fusion of target information
typedef struct tagNET_VAO_EXTRA_FUSION_INFO
{
	UINT					nRadarDistance;					/// The length of the radar target in polar coordinates, measured in meters, multiplied by 1000 times
	int						nRadarAngle;					/// The angle of the radar target in polar coordinate system, measured in degrees, multiplied by 1000 times
	UINT					nRadarID;						/// Radar target ID
	UINT					nObjectSource;					/// Target fusion type: -1: unknown, 0: video detection; 1: Radar detection; 2: Fusion detection
	double					dbSpeed;						/// Target motion speed, unit: km/h
	int						nRadarObjectType;				/// Mask of radar target type
	float					fCartPosX;						/// The target is located in the X-axis coordinate of the radar coordinate system, in meters. The device's viewing angle is in the positive direction of the X-axis in the right-hand direction and in the positive direction of the Y-axis in the forward direction
	float					fCartPosY;						/// The target is in the Y-axis coordinate of the radar coordinate system, in meters. The device's viewing angle is in the positive X-axis direction in the right-hand direction and in the positive Y-axis direction in the forward direction
	float					fSpeedX;						/// Target lateral movement speed, unit: m/s,  Device perspective: Right hand direction is x positive direction
	float					fSpeedY;						/// Target longitudinal motion speed, unit: m/s,  Equipment perspective: y is in the forward direction from the front
	float					fAccelerationX;					/// Radar target acceleration ax, device viewing angle: right-hand direction is x-positive; Value range: -10~10, unit: m/s2
	float					fAccelerationY;					/// Radar target acceleration ay, device angle of view: forward is y forward; Value range: -10~10, unit: m/s2
	float					fHeadingAngle;					/// Heading angle (clockwise), unit: angle, range [0, 360)
	double					dbLongitude;					/// The longitude value is positive for east longitude and negative for west longitude. Value range -179.9999999~180.0000000
	double					dbLatitude;						/// Latitude values are positive for north latitude and negative for south latitude. Value range -90000000~90.0000000
	char					szReserved[1024];				/// Reserved bytes
}NET_VAO_EXTRA_FUSION_INFO;

///@brief Video analysis object info extension structure, extension version 2. 
typedef struct tagDH_MSG_OBJECT_EX2
{
    DWORD				dwSize;
    UINT                nObjectID;                          // Object ID. Each ID presents one object. 
    char                szObjectType[128];                  // Object type 
    UINT                nConfidence;                        // Confiidence(0-255). The higher the value is, the higher the confidence is. 
    int                 nAction;                            // Object operation. 1:Appear 2:Move 3:Stay 4:Remove 5:Disappear 6:Split 7:Merge 8:Rename
    DH_RECT             BoundingBox;                        // Surrounding rectangle 
    DH_POINT            Center;                             // Object size centre
    int                 nPolygonNum;                        // Top amount of the polygon
    DH_POINT            Contour[DH_MAX_POLYGON_NUM];        // Polygon of generaly accurate frame 
    DWORD               rgbaMainColor;                      // The plate and the vehicle body main color. Use byte to present: red, green, blue and transparent. When RGB value is (0,255,0), transparent is 0, the value is 0x00ff0000.
    char                szText[128];                        // The same as the string of the DH_MSG_OBJECT
    char                szObjectSubType[64];                // Object sub-type. It has the following sub-tyes. 
															// The same as the string of the DH_MSG_OBJECT
    BYTE                byReserved1[3];
    bool                bPicEnble;                          // There is image file info of the corresponding object 
    DH_PIC_INFO         stPicInfo;                          // Image info of the object 
    bool                bShotFrame;                         // Has been snapped or not 
    bool                bColor;                             // Object color (rgbaMainColor) is usable or not. 
    BYTE                bLowerBodyColor;                    // The lower part color (rgbaLowerBodyColor) is usable or not 
    BYTE                byTimeType;                         // Time type. Please refer to EM_TIME_TYPE.
    NET_TIME_EX         stuCurrentTime;                     // For video synopsis. Current time stampl (When snap or recognize the object, use the recognition intelligent frame on one video frame or JPEG.  It is the appearing time of the frame on the original video. )
    NET_TIME_EX         stuStartTime;                       // Start time stamp(When the object first appear )
    NET_TIME_EX         stuEndTime;                         // End time (When the object last appear )
    DH_RECT             stuOriginalBoundingBox;             // Surrounding box(Absolute coordinates)
    DH_RECT             stuSignBoundingBox;                 // Vehicle symbol surrounding box 
    DWORD               dwCurrentSequence;                  // Current frame SN(Frame when snap the object )
    DWORD               dwBeginSequence;                    // Start frame SN (The frame SN when the object start appearing)
    DWORD               dwEndSequence;                      // End frame SN (The frame SN when the object disappering)
    INT64               nBeginFileOffset;                   // The file offset when start. Unit:byte. (When the object appearing, the video frame offset value comparing with the file start positon in the original video)
    INT64               nEndFileOffset;                     // The file offset when stop. Unit: byte. (When the object disappearing, the video frame offset value comparing with the file start position in the original video)
    BYTE                byColorSimilar[NET_COLOR_TYPE_MAX]; // Object color similarity level. The valur ranges from 0 to 100. The underline value of the array represents one color. Plase refer to EM_COLOR_TYPE.
    BYTE                byUpperBodyColorSimilar[NET_COLOR_TYPE_MAX]; // The top body color similarity leve; (When the object is the human)
    BYTE                byLowerBodyColorSimilar[NET_COLOR_TYPE_MAX]; // The lower body color similarity leve; (When the object is the human)
    UINT                nRelativeID;                        // Related object ID
    char				szSubText[20];						// When "ObjectType" is "Vehicle" or "Logo", it represents one car series under the card symbol such as Audio A6L. Since there are too many card series, SDK use the network to realize COM transmission (szSubText) to realize this function. 
    
    UINT				nPersonStature;						// Intrusion person height. Unit is cm. 
    EM_MSG_OBJ_PERSON_DIRECTION	emPersonDirection;			// Intrusion person direction 
    DWORD               rgbaLowerBodyColor;                 // The same usage as the rgbaMainColor, it is valid when the object type is human. 

    /* Video synopsis extra info */
    UINT                nSynopsisSpeed;                             // Synopsis speed threshold. There are ten levels (1 to 10). 5 means only reserve the object of speed higher than 5. It is a relative unit.  
                                                                    // When it is 0, the string is invalid.
    UINT                nSynopsisSize;                              // Synopsis dimension threshold. There are ten levels (1 to 10). 3 means only reserve the object of speed higher than 3. It is a relative unit.  
                                                                    // When it is o, the string is invalid. 
    BOOL                bEnableDirection;                           // When it is True, filter the object moving direction.
                                                                    // When it is False, do not filter the object moving direction. 
    DH_POINT            stuSynopsisStartLocation;                   // Synopsis moving direction, start coordinates. The point coordinates [0,8191], it is valid when bEnableDirection is True. 
    DH_POINT            stuSynopsisEndLocation;                     // Synopsis moving direction, stop coordinates. The point coordinates [0,8191], it is valid when bEnableDirection is True. 
	char						szSerialUUID[22];					 // Intelligent object global unique object identification
																	// Valid data bits are 21 bits, including '\0'
																	// Top 2 bits %d%d: 01-video clip, 02-picture, 03-file, 99-other
																	// Middle 14 bit yyyymmddhhmmss
																	// Last 5 bits %U%U%U%U%U: object ID, such as 00001
	WORD					nCarLogoIndex;								/// Vehicle emblem
	int						nCategoryType;								// Type of object category, 0: unknown, 1: Category, 2: InductiveVehicleType
	char					szInductiveVehicleType[32];					// Summarize the types of vehicles based on the Category type
	char                    szTextDirection[32];                    // Move direction LeftToRight, RightToLeft, TopToBottom, BottomToTop
	char                    szQRCode[64];                                /// QR code recognition result on the vehicle
	NET_MSG_OBJECT_OBJECTUUID_INFO		stuObjectUUID;		/// Intelligent object global unique object identification
	UINT					nTextRegionID;								/// The area number corresponding to the text content
	UINT nCloseDistance;									/// Distance to the adjacent detection target, currently refers to the engineering vehicle, unit: cm
	int nSpeed;									/// Object speed, unit: km/h
	char					szVehicleIDNumber[128];					/// VehicleID Number
	UINT					nCarTripLineDirection;					/// Car Trip LineDirection: 0: unknown, 1: from A to B, 2: from B to A.
    NET_VAO_EXTRA_VEHICLE_INFO      stuVehicleExtra;                /// Vehicle extension information, valid when Object Type is Vehicle
    char                    szTrafficUUID[33];                      /// Traffic violation UUID
	char					szReserved2[3];							/// For align
	double					dbLongitude;							/// Longitude, unit: degrees, positive for east longitude, negative for west longitude, range of values [-180180]
	double					dbLatitude;								/// Latitude, unit: degrees, positive for north latitude, negative for south latitude, range of values [-90,90]
	int						nElevation;								/// Elevation information, unit: meter
    /// License plate extended information ///
    UINT					nPlateEvaluation;                       /// License plate scoring is based on the confidence level, size of the license plate and the position of the snapshot, and is classified as 'A', 'B', 'C' and 'D'.

	NET_VAO_EXTRA_FUSION_INFO*	pstuFusionInfo;						/// Radar fusion of target information
	BYTE 					byReserved[408-POINTERSIZE];			/// Extended bytes
} DH_MSG_OBJECT_EX2;
