///@brief Personnel Information Extension Structure 2
typedef struct tagFACERECOGNITION_PERSON_INFOEX2
{
	char						szComment[100];							// Comment
	char						szReserved1[4];							// Reserved1
	NET_TIME					stuAppointmentStartTime;				// Personnel appointment start time
	NET_TIME					stuAppointmentEndTime;					// Personnel appointment end time
	char						szAllowFloors[32];						// Allow to reach the floor, Obsolete, it is recommended to use szAllowFloorsEx
	char						szNameEX[128];							// Extension field for name
	char						szIDEX[128];							// Extended fields of personnel ID number, job number, or other numbers
	int						bUseModifyTime;					// Whether to use modification time
	int						bUseRegisterStorageTime;		// Whether to use the registration library for storage time
	NET_TIME				stuModifyTime;						// The last time the platform modified the registration database personnel information
	NET_TIME				stuRegisterStorageTime;		// Registration database entry time
	char						szAllowFloorsEx[64];					/// Allow to reach the floor
	char						szUID2[64];								/// Add personnel UID
	UINT						nUIDType;								/// Specify the UID field to use, 0 uses UID field, 1 uses UID2 field
	char						szReserved[548];						// Reserved byte
}FACERECOGNITION_PERSON_INFOEX2;

///@brief expansion of  personnel information
typedef struct tagFACERECOGNITION_PERSON_INFOEX
{
    char                        szPersonName[DH_MAX_PERSON_NAME_LEN];           // person name             
    WORD                        wYear;                                          // birth year, fill 0 is invalid, when is as a query condition
    BYTE                        byMonth;                                        // birth month, fill 0 is invalid, when is as a query condition
    BYTE                        byDay;                                          // birth day, fill 0 is invalid, when is as a query condition
    BYTE                        bImportantRank;                                 // importance level,1~10,the higher value the higher level. fill 0 is invalid, when is as a query condition
    BYTE                        bySex;                                          // sex, 0-man, 1-female. fill 0 is invalid, when is as a query condition
    char                        szID[DH_MAX_PERSON_ID_LEN];                     //  the unicle ID for the person
    WORD                        wFacePicNum;                                    // picture number
    DH_PIC_INFO                 szFacePicInfo[DH_MAX_PERSON_IMAGE_NUM];         // picture info
    BYTE                        byType;                                         // Personnel types, see EM_PERSON_TYPE
    BYTE                        byIDType;                                       // Document types, see EM_CERTIFICATE_TYPE
    BYTE                        byGlasses;                                      // Whether wear glasses or not,0-unknown,1-not wear glasses,2-wear glasses						
    BYTE                        byAge;                                          // Age,0 means unknown 
    char                        szProvince[DH_MAX_PROVINCE_NAME_LEN];           // province
    char                        szCity[DH_MAX_CITY_NAME_LEN];                   // city
    char                        szUID[DH_MAX_PERSON_ID_LEN];                    // person unique ID
    char                        szCountry[NET_COUNTRY_LENGTH];                  // country
    BYTE                        byIsCustomType;                                 // using person type: 0 using byType, 1 using CustomType
    char                        szCustomType[DH_COMMON_STRING_16];              // custom type of person
    char                        szComment[NET_COMMENT_LENGTH];                  // comment info
    char                        szGroupID[NET_GROUPID_LENGTH];                  // group ID
    char                        szGroupName[NET_GROUPNAME_LENGTH];              // group name
    EM_DEV_EVENT_FACEDETECT_FEATURE_TYPE    emEmotion;                          // Emotion
    char                        szHomeAddress[DH_COMMON_STRING_128];            // home address of the person
    EM_GLASSES_TYPE             emGlassesType;                                  // glasses type
    char                		szReserved1[4];                                         
    EM_EYE_STATE_TYPE           emEye;                                          // eye state
    EM_MOUTH_STATE_TYPE         emMouth;                                        // mouth state
    EM_MASK_STATE_TYPE          emMask;                                         // mask state
    EM_BEARD_STATE_TYPE         emBeard;                                        // beard state
    int                         nAttractive;                                    // attractive, -1:invalid, 0:unknown range:1-100
    EM_PERSON_FEATURE_STATE     emFeatureState;                                 // person feature state
    BOOL                        bAgeEnable;                                     // age range is enabled
    int                         nAgeRange[2];                                   // age range
    int                         nEmotionValidNum;                               // invalid number in array emEmotion, 0 means all emotion
    EM_DEV_EVENT_FACEDETECT_FEATURE_TYPE    emEmotions[DH_MAX_FACEDETECT_FEATURE_NUM];  // human emotion  set the query condition
    int                         nCustomPersonInfoNum;                           // extension number of registered personnel information
    CUSTOM_PERSON_INFO          szCustomPersonInfo[DH_MAX_CUSTOM_PERSON_INFO_NUM];  // extension of registered personnel information
    EM_REGISTER_DB_TYPE         emRegisterDbType;                               // type of register target DB
    NET_TIME                    stuEffectiveTime;                               // effective time
    EM_PERSON_FEATURE_ERRCODE   emFeatureErrCode;                               // error code of person feature
    DWORD                       wFacePicNumEx;                                  // Number of target pictures
    NET_FACE_PIC_INFO           szFacePicInfoEx[6];                             // The picture information corresponding to the current person. It is an extension of szFacePicInfo. This field will be used first in the future
	NET_PERSON_FEATURE_VALUE_INFO stuPersonFeatureValue;						// Personnel characteristics information
	BOOL                        bFrozenStatus;                                  // person frozen status
	char                        szReserved[4];									// Reserved bytes
	NET_PERSON_FREQUENCY_INFO	stuFrequencyInfo;								// alarm frequency info
	char						szUUID[64];										// The platform uniquely identifies the target field, which is different from UID. According to the capability of getCaps, IVSS supports UUID when the value of SupportIDFromServer is true.
	FACERECOGNITION_CUSTOM_PASSER_BY_INFO*		pstuCustomPasserbyInfo;			// passer info,the space application by the user,Apply one at a time
	FACERECOGNITION_CUSTOM_EXAMINEE_INFO*		pstuCustomExamineeInfo;			// Candidate exam information is applied for by the user in memory, one at a time
	FACERECOGNITION_CUSTOM_RESIDENTS_INFO*		pstuCustomResidentsInfo;		// Resident information, requested by the user for memory, one at a time
	char						szRecordID[64];									// RecordID
	FACERECOGNITION_PERSON_INFOEX2*				pstuPersonInfoEx2;				// Personnel information extension 2, where users can apply for memory one at a time
	BOOL						bPersonFeatureValue;								//Personnel characteristics information enable
	char				        *pszFeatureValue;								// the target feature , the memory is alloced by user															
	UINT				        nFeatureValueLen;								// len of pszFeatureValue
	BYTE                        byReserved[116-POINTERSIZE*5];					// Reserved bytes
} FACERECOGNITION_PERSON_INFOEX;

///@brief cadidate person info
