///@brief Detection mode
typedef enum tagEM_EVENT_DETECT_TYPE
{
	EM_EVENT_DETECT_TYPE_UNKNOWN = -1,		// unknown
	EM_EVENT_DETECT_TYPE_LESS_OR_EQUAL,		// Less than or equal to the threshold alarm
	EM_EVENT_DETECT_TYPE_GREATER_OR_EQUAL,	// greater than or equal to the threshold alarm
	EM_EVENT_DETECT_TYPE_EQUAL,				// equal to threshold alarm
	EM_EVENT_DETECT_TYPE_NOEQUAL,			// Not equal to threshold alarm
	EM_EVENT_DETECT_TYPE_CHANGE,			// Alarm for changes in the number of people
	EM_EVENT_DETECT_TYPE_GREATER,			// greater than the threshold alarm
	EM_EVENT_DETECT_TYPE_LESS,				// less than threshold alarm
	EM_EVENT_DETECT_TYPE_IN_INTERVAL,		// Alarm in the interval, the number of people detected in the interval is alarmed, including the boundary value.
	EM_EVENT_DETECT_TYPE_OUT_INTERVAL,		// Alarm outside the interval, alarm when the number of people detected is outside the interval, excluding the boundary value.
}EM_EVENT_DETECT_TYPE;

