	UINT				nUpColorConf;									// degree of confidence about UpColor, range is [0,100]
	UINT				nDownColorConf;									// degree of confidence about DownColor, range is [0,100]
	UINT				nGenderConf;									// degree of confidence about Gender, range is [0,100]
	UINT				nAgeConf;										// degree of confidence about Age, range is [0,100]
	UINT				nHatTypeConf;									// degree of confidence about HatType, range is [0,100]
	UINT				nUpTypeConf;									// degree of confidence about UpType, range is [0,100]
	UINT				nDownTypeConf;									// degree of confidence about DownType, range is [0,100]
	UINT				nHairTypeConf;									// degree of confidence about Hair, range is [0,100]
	UINT				nHasHeadConf;									// degree of confidence about HasHead, range is [0,100]
	UINT				nHasDownBodyConf;								// degree of confidence about HasDownBody, range is [0,100]
	UINT				nUniformStyleConf;								// degree of confidence about UniformStyle, range is [0,100]
