///@brief Target attributes info
typedef struct tagNET_FACE_ATTRIBUTE
{
	EM_DEV_EVENT_FACEDETECT_SEX_TYPE 		emSex;						// Sex
	int        								nAge;						// Age,-1 means invaild value
    unsigned int        					nFeatureValidNum;           // Feature valid num,used in combination with emFeature
    EM_DEV_EVENT_FACEDETECT_FEATURE_TYPE    emFeatures[DH_MAX_FACEDETECT_FEATURE_NUM];   // Feature,used in combination with nFeatureValidNum
	char									szReserved[4];
	EM_EYE_STATE_TYPE						emEye;						// Eye state
	EM_MOUTH_STATE_TYPE						emMouth;					// Mouth state
	EM_MASK_STATE_TYPE 						emMask;						// Mask state
	EM_BEARD_STATE_TYPE						emBeard;					// Beard state
	int										nAttractive;				// Attractive, 0 means undistingush,range:1-100
	NET_RECT								stuBoundingBox;				// Bounding box(8192 coordinates)
    NET_EULER_ANGLE				            stuFaceCaptureAngle;		// euler angle of Target in the capture picture, nPitch:pitch of the head, nYaw: yaw of the head, nRoll:roll of the head
                                                                        // range of the angle value is [-90,90], stuFaceCaptureAngle is invalid if the three angles are 999.
    UINT                                    nFaceQuality;               // The quality of Target picture.The range is 0~10000 
    int                                     nFaceAlignScore;            // The score of Target picture align.The range is 0~10000,-1 is invalid
    int                                     nFaceClarity;               // The score of Target picture clarity.The range is 0~10000,-1 is invalid
    NET_POINT                               stuFaceCenter;              // Center of Target(not center of bounding box), 0-8191 relative coordinates, relative to large graph
    EM_FACEDETECT_GLASSES_TYPE              emGlass;                    // Glass type
    UINT									nFaceDetectConf;			// degree of confidence about Target, range is [0,100]
    NET_FACE_ORIGINAL_SIZE                  stuOriginalSize;            // Actual Target image size during algorithm Target analysis. 
	int										arrAngleStatus[3];			// Target capture angle status
    UINT 									nIlluminationScore;			// Target illumination value, range[0,255]
    char 									nLeftEyeCoverConf;			// Left eye occlusion confidence, range[0,100]
    char 									nLeftCheekCoverConf;		// Left cheek occlusion confidence, range[0,100]
    char 									nMouthCoverConf;			// Confidence range of Target occlusion [0,100]
    char 									nRightEyeCoverConf;			// Confidence range of Target right eye occlusion[0,100]
    char 									nRightCheekCoverConf;		// Confidence range of Target right cheek occlusion[0,100]
    char 									nChinCoverConf;				// Confidence range of facial chin occlusion[0,100]
    char 									nIsCompleteFace;			// Target integrity evaluation Target, 0:incomplete, 1:complete
    char 									nSaturationScore;			// Saturation score range of Target image [0,100]
    char 									nBrowCoverConf;				// Confidence range of Target and forehead occlusion[0,100]
    char 									nNoseCoverConf;				// Confidence range of Target nose occlusion [0,100]
	BYTE                					bReserved0[2];				// Reserved
	EM_AGE_SEG								emAgeSeg;					// Age Segmentation
    BYTE                					bReserved[36];				// Reserved
} NET_FACE_ATTRIBUTE;

