///@brief the human trait info be found
typedef struct tagHUMAN_TRAIT_INFO
{
    EM_CLOTHES_COLOR    emCoatColor;            // coat color
    EM_CLOTHES_COLOR    emTrousersColor;        // trousers color
    EM_COAT_TYPE        emCoatType;             // coat type
    EM_TROUSERS_TYPE    emTrousersType;         // trousers type
    EM_HAS_HAT          emHasHat;               // has hat or not
    EM_HAS_BAG          emHasBag;               // has bag or not
    EM_SEX_TYPE			emSex;					// sex
    UINT				nAge;					// age
    EM_HAIR_STYLE		emHairStyle;			// hair style
    EM_HAS_UMBRELLA		emHasUmbrella;			// has umbrella or not
    EM_BAG_TYPE			emBagType;				// bag type
    EM_CAP_TYPE			emCapType;				// cap type
	char				szSourceID[42];			/// The image ID valid data is 41 bits, used for target association.
												// Bits 1-20:
												// 1. For automatically collected objects, the unified identification code of online video/image information collection devices/systems or analysis devices/systems should be used.
												// 2. For manually collected objects, the unified identification code of the corresponding public security video/image information application platform or other public security information systems should be used, including all systems connected to the view database via data service interfaces.
												// Bits 21-22:
												// Indicates the type of the basic video/image information object:
												// 01 - Video clip
												// 02 - Image
												// 03 - File
												// 99 - Other
												// Bits 23-36:
												// The generation time of the basic video/image information object, accurate to the second level: YYYYMMDDhhmmss (year, month, day, hour, minute, second).
												// Bits 37-41:
												// The sequence number of the basic video/image information object.
	char				szAlign[6];				/// Align
    BYTE                byReserved[976];       // reserved
}HUMAN_TRAIT_INFO;

