    UINT                        nLane;                          /// Lane number  
    UINT                        nSpeed;                         /// Vehicle speed
    UINT                        nSpeedLimit;                    /// Speed limit
	int							nGroupID;						/// Event Group ID
	char						szPlateNumber[32];				/// License plate information
	char						szPlateFilePath[256];			/// License plate image path
	char						szRoadName[256];				/// Road name
	char						szVehicleFilePath[256];			/// Vehicle file path
	char                        szSecondFilePath[256];          /// For illegal parking events, this stores the second large composite image
	NET_IMAGE_INDEX             stuImageIndex[4];               /// For invalid illegal parking events, there is no large composite image; instead, individual camera captured images are stored
	UINT                        nImageIndexNum;                 /// Number of composite images
	NET_GPS_STATUS_INFO         stuGPSStatus;                 	/// GPS status information
	EM_PREALARM                 emPreAlarm;                     /// Indicates whether the image is from a violation pre-alarm (warning)
