///@brief The query mode of searching Target database by picture
typedef enum tagEM_FINDPIC_QUERY_MODE
{
    EM_FINDPIC_QUERY_UNKNOWN,               // Unknown
    EM_FINDPIC_QUERY_PASSIVE,               // Passive
    EM_FINDPIC_QUERY_ACTIVE,                // Active
} EM_FINDPIC_QUERY_MODE;

///@brief The sort order of the result about searching Target database by picture
typedef enum tagEM_FINDPIC_QUERY_ORDERED
{
	EM_FINDPIC_QUERY_BY_SIMILARITY,			// From high to low by similarity
	EM_FINDPIC_QUERY_BY_TIME_FORWARD,		// Forward by time
	EM_FINDPIC_QUERY_BY_TIME_REVERSE,		// Reverse by time
} EM_FINDPIC_QUERY_ORDERED;
///@brief Target Matching Options
typedef struct __NET_FACE_MATCH_OPTIONS
{
	DWORD               dwSize;
	unsigned int        nMatchImportant;               // Important level 1 to 10 staff, the higher the number the more important (check important level greater than or equal to this level of staff)
	EM_FACE_COMPARE_MODE emMode;                       // Target comparison mode, see EM_FACE_COMPARE_MODE
	int                 nAreaNum;                      // Target the number of regional
	EM_FACE_AREA_TYPE   szAreas[MAX_FACE_AREA_NUM];    // Regional groupings of people Target is NET_FACE_COMPARE_MODE_AREA effective when emMode
	int                 nAccuracy;                     // Recognition accuracy (ranging from 1 to 10, with the value increases, the detection accuracy is improved, the detection rate of decline. Minimum value of 1 indicates the detection speed priority, the maximum is 10, said detection accuracy preferred. Temporarily valid only for Target detection)
	int                 nSimilarity;                   // Similarity (must be greater than the degree of acquaintance before the report; expressed as a percentage, from 1 to 100)
	int                 nMaxCandidate;                 // Reported the largest number of candidate (based on similarity to sort candidates to take the maximum number of similarity report)
	EM_FINDPIC_QUERY_MODE emQueryMode;                 // The query mode of searching Target database by picture
	EM_FINDPIC_QUERY_ORDERED emOrdered;				   // The sort order of the result about searching Target database by picture
}NET_FACE_MATCH_OPTIONS;
///@brief Query filters
typedef struct __NET_FACE_FILTER_CONDTION
{
	DWORD               dwSize;
	NET_TIME			stStartTime;			       // Start time
    NET_TIME			stEndTime;				       // End Time
	char                szMachineAddress[MAX_PATH];    // Place to support fuzzy matching
	int                 nRangeNum;                     // The actual number of database
	BYTE                szRange[MAX_FACE_DB_NUM];      // To query the database type, see EM_FACE_DB_TYPE
	EM_FACERECOGNITION_FACE_TYPE emFaceType;           // Target to query types, see EM_FACERECOGNITION
    int                 nGroupIdNum;                   // staff group  
    char                szGroupId[MAX_GOURP_NUM][DH_COMMON_STRING_64]; // staff group ID 
    NET_TIME            stBirthdayRangeStart;          // start birthday time
    NET_TIME            stBirthdayRangeEnd;            // end birthday time
	BYTE			    byAge[MAX_AGE_NUM];			   // Age range, When byAge[0] is 0 and byAge[1] is 0, it means query all age
	BYTE				byReserved[2];				   // Reserved
	EM_DEV_EVENT_FACEDETECT_FEATURE_TYPE	emEmotion[MAX_EMOTION_NUM];		// Emotion
	int					nEmotionNum;				   // Emotion num
    int                 nUIDNum;                       // UID num
    char                szUIDs[64][32];                // UID list
	int                 nUUIDNum;                      // UUID num
	char				szUUIDs[64][32];               // A list of the unique identifiers of the personnel on the platform, according to whether the ability obtained by faceRecognitionServer.getCaps has the field SupportIDFromServer and the value is true, it is valid
	BOOL                bIsUsingRealUTCTime;           // Whether to use the start time and end time in UTC format
	NET_TIME            stuStartTimeRealUTC;            // Start time (UTC time format)
	NET_TIME            stuEndTimeRealUTC;              // End Time (UTC time format) Note: This parameter is paired with StartTimeRealUTC
	BOOL					bIsUsingRegisterStorageTime;   // Whether to use the start and end time of the registration database personnel
	NET_TIME				stuStartRegisterStorageTime;	// Starting time for registration of personnel in the repository
	NET_TIME				stuEndRegisterStorageTime;		// End time of registration of personnel in the repository
	BOOL					bIsUsingModifyTime;				// Whether to use the modification start and end time of the registration database personnel
	NET_TIME				stuStartModifyTime;					// Starting time for modifying the registration database personnel
	NET_TIME				stuEndModifyTime;					// End time of modification for registration database personnel
	BOOL					bFindObjRecord;						/// Do you want to query the target time record
}NET_FACE_FILTER_CONDTION;

