///@brief CLIENT_GetDevCaps (NET_FACERECOGNITIONSE_CAPS) output parameter
typedef struct tagNET_OUT_FACERECOGNITIONSERVER_CAPSBILITYQUERY
{
    DWORD                       dwSize;                 // struct size
    BOOL                        bmultiFind;             // support multi channel
    UINT                        nmaxFaceType;           // Maximum number of Target Target types supported
    NET_FACEBOXCOLOR_CAPS       stuFaceBoxColor;        // Target Box color caps
    BOOL                        bAsynPush;              // Whether to support push data which is returned by searching Target database by picture
    UINT                        nMaxGroupNum;           // Max group number, 0 means invalid
    UINT                        nMaxPersonNum;          // Max person number, 0 means invalid
    UINT                        nMultiAppendPicLength;  // The size of each image recevied about milti appen, unit:KB
    EM_SUPPORT_SEARCH_BY_PIC    emSupportSearchByPic;   // Is it supported to search by pictures
    DWORD                       dwSearchTypeMask;       // Object type about search by pictures, it is effective when emSupportSearchByPic is EM_SUPPORT_SEARCH_BY_PIC_SUPPORT
                                                        // bit0:Target, bit1:human, bit2:traffiv,  bit3:nomotor
    UINT                        nSinglePicMaxLength;    // single picture max length, uint:KB
    BOOL                        bPersonWithMultiFace;   // Does the device Target registry support one person multi Target pictures
	BOOL						bSupportIDFromServer;	// Whether to support the use of the Target database GroupID and personnel UUID to manage the Target database and personnel respectively
	UINT						nSupportSMDPicSearchMask;		// Whether to support type masks for SMD attribute features to search for images, bit0: face, bit1: human body, bit2: motor vehicle, bit3: non motor vehicle
	int                         nSupportRealUTC;         // Whether the time in the query conditions and results can support UTC time format 0: No, 1: Yes
	UINT                        nDetectMethod;          // Supports the method of detecting small images from large images, 1-supports detectMultiFace, 0 (or if the field does not exist) - Uncertain, compatible with old devices
	int							nSupportLiftControlTypesCount;		/// Number of supported elevator control method types
	EM_FACE_RECOGNITION_SUPPORT_LIFT_CONTROL_TYPES emSupportLiftControlTypes[8];	/// Supported types of elevator control methods
	BOOL                        bSupportMatchTwoFace;   // Whether to support face 1V1 similarity comparison
	UINT                        nSupportDetectObjectTypeMask;       ///  Target type mask with feature value matting support, filling 0 means no support
} NET_OUT_FACERECOGNITIONSERVER_CAPSBILITYQUERY;  

