#define MAX_BIG_PIC_NUM     50      // max number of large images
#define MAX_TOKEN_NUM       128     // max number of token

///@brief Detect object type
typedef enum tagEM_DETECT_OBJECT_TYPE
{
	EM_DETECT_OBJECT_TYPE_UNKNOWN    = 0,       // Unknown
	EM_DETECT_OBJECT_TYPE_FACE,					// Target
	EM_DETECT_OBJECT_TYPE_VEHICLE,				// Vehicle
	EM_DETECT_OBJECT_TYPE_STRUCTLIZE,			// Struct Lize
} EM_DETECT_OBJECT_TYPE;

///@brief Detect process type
typedef enum tagEM_DETECT_PROCESS_TYPE
{
	EM_DETECT_PROCESS_TYPE_UNKNOWN    = 0,      // Unknwon
	EM_DETECT_PROCESS_TYPE_FEATURE,				// Extract feature
	EM_DETECT_PROCESS_TYPE_ATTRIBUTE,			// Extract attribute
	EM_DETECT_PROCESS_TYPE_DETECT,				// Detection
} EM_DETECT_PROCESS_TYPE;

///@brief Coordinate type
typedef enum tagEM_COORDINATE_TYPE
{
	EM_COORDINATE_TYPE_UNKNOWN    = 0,         // Unknown
	EM_COORDINATE_TYPE_ABSOLUTE,                // Absolute coordinates
	EM_COORDINATE_TYPE_8192,					// 8192 coordinate system
} EM_COORDINATE_TYPE;

///@brief large image info (the function of detect small image from large image)
typedef struct tagNET_DETECT_BIG_PIC_INFO
{
    int             nPicID;                                     // large image ID
    DWORD           dwOffSet;                                   // the offset position of the large image in the binary data, unit:bytes
    DWORD           dwFileLenth;                                // the length of the file, unit:bytes
    DWORD           dwWidth;                                    // the width of this image, unit:pixel
    DWORD           dwHeight;                                   // the height of this image, unit:pixel
    int             nDetectRegionNum;                           // Points number of detect region
    NET_POINT       stuDetectRegion[DH_MAX_DETECT_REGION_NUM];  // Detect region
    BYTE            bReserved[44];                              // Reserved
}NET_DETECT_BIG_PIC_INFO;

///@brief Large image info (the function of detect small image from large image)
typedef struct tagNET_DETECT_BIG_PIC_INFO_EX
{
	int             nPicID;                                     // Large image ID
	DWORD           dwOffSet;                                   // The offset position of the large image in the binary data, unit:bytes
	DWORD           dwFileLenth;                                // The length of the file, unit:bytes
	DWORD           dwWidth;                                    // The width of this image, unit:pixel
	DWORD           dwHeight;                                   // The height of this image, unit:pixel
	int             nDetectRegionNum;                           // Points number of detect region
	NET_POINT       stuDetectRegion[DH_MAX_DETECT_REGION_NUM];  // Detect region
	char			szRequestID[64];							// Request ID
	char			szPath[256];								// URL address about image
	EM_COORDINATE_TYPE emCoordinateType;						// Coordinate type
	EM_DETECT_OBJECT_TYPE emObjectType;							// Detect object type
	UINT			nTargetType;								// By bit combination, all 1 means full detection, 1 means Target, 2 means human body, 4 means motor vehicle, 8 means non motor vehicle, 16 means non motor vehicle
	int				nProcessTypeNum;							// Count of process type
	EM_DETECT_PROCESS_TYPE emProcessType[8];					// Process type	
	char*			szData;										// Scene image data, if the string after Base64 does not have this field or the field is empty, binary image data will be used
	int				nDataLen;									// Scene image length
	BYTE            bReserved[1016];                            // Reserved
}NET_DETECT_BIG_PIC_INFO_EX;

///@brief the input parameter of interface CLIENT_FaceRecognitionDetectMultiFace
typedef struct tagNET_IN_FACE_RECOGNITION_DETECT_MULTI_FACE_INFO
{
    DWORD                       dwSize;                             // the size of this struct
    int                         nBigPicNum;                         // the number of large image
    NET_DETECT_BIG_PIC_INFO     stuBigPicInfo[MAX_BIG_PIC_NUM];     // the info of large image(stuBigPicInfoEx is recommended)

    /* the binary data of image */
    char                        *pBuffer;                           // the buffer of the image
    int                         nBufferLen;                         // the length of th buffer
    EM_OBJECT_TYPE              emDetectObjType;                    // Object type
    BOOL						bBigPicInfoExEnable;				// Whether stuBigPicInfoEx is valid
	int                         nBigPicNumEx;						// Number of big picture
	NET_DETECT_BIG_PIC_INFO_EX  stuBigPicInfoEx[MAX_BIG_PIC_NUM];	// Big picture information (Extended)
	UINT						nToken;								// Token(If no, it is 0)
} NET_IN_FACE_RECOGNITION_DETECT_MULTI_FACE_INFO;

///@brief the output parameter of interface CLIENT_FaceRecognitionDetectMultiFace
typedef struct tagNET_OUT_FACE_RECOGNITION_DETECT_MULTI_FACE_INFO
{
    DWORD                       dwSize;                         // the size of this struct
} NET_OUT_FACE_RECOGNITION_DETECT_MULTI_FACE_INFO;

