	double						dbSensitive;					/// Sensitive,0-3
	double						dbCanalizeLaneWidth[8];			/// Canalize Lane Width,in m,0.0-20.0
	double						dbCanalizeHorizontalOffset;		/// Canalize Horizontal Offset,in m
	double						dbCanalizeUpperBoundary;		/// Canalize Upper Boundary,in m
	double						dbCanalizeLowerBoundary;		/// Canalize Lower Boundary,in m
	double						dbCanalizeDivideIslandWidth;	/// Canalize Divide Island Width
	double						dbDivideIslandWidth;			/// Divide Island Width
	int							nCanalizeLaneWidthNum;			/// Canalize Lane Width Num
	char						szReserved[1020];				/// Reserved
