///@brief Corresponding to data block description of event type EVENT_IVS_HUMANTRAIT(Event of human trait)
typedef struct tagDEV_EVENT_HUMANTRAIT_INFO
{
	int					nChannelID;									  // Channel ID
	char				szName[DH_EVENT_NAME_LEN];					  // Event name
	int                 nEventID;                                     // Event ID
	double              PTS;                                          // Timestamp (in milliseconds)
	NET_TIME_EX         UTC;                                          // Time for the event occurred
	int                 nAction;                                      // 1:Start 2:Stop

	EM_CLASS_TYPE		emClassType;								  // Class type 
	int					nGroupID;									  // Event group ID,A detection of multiple human characteristics at the same nGroupID
	int					nCountInGroup;								  // the captured human number within an event group,A detection of multiple human characteristics at the same nCountInGroup
	int					nIndexInGroup;								  // capture Index of an event group,starting from 1
	HUMAN_IMAGE_INFO	stuHumanImage;								  // Human body image info
	FACE_IMAGE_INFO		stuFaceImage;								  // Human Target image info
	EM_DETECT_OBJECT	emDetectObject;								  // Detect Object
	HUMAN_ATTRIBUTES_INFO  stuHumanAttributes;						  // Human attributes
    SCENE_IMAGE_INFO    stuSceneImage;                                // Scene image info
	NET_FACE_ATTRIBUTE	stuFaceAttributes;							  // Target attribute
	FACE_SCENE_IMAGE	stuFaceSceneImage;							  // Target scene image
	NET_EXTENSION_INFO  stuExtensionInfo;                             // Extension info
 	NET_HUMANTRAIT_EXTENSION_INFO   stuHumanTrait;                    // Extension event code which produce human trait
    NET_HUMAN_FEATURE_VECTOR_INFO   stuHumanFeatureVectorInfo;        // Position info of human feature data in binary data
    EM_FEATURE_VERSION              emHumanFeatureVersion;            // Human feature data version
    NET_FACE_FEATURE_VECTOR_INFO    stuFaceFeatureVectorInfo;         // Position info of Target feature data in binary data
    EM_FEATURE_VERSION              emFaceFeatureVersion;             // Target feature data version
	UINT				nCompliantMark;								  // Compliance flag 0: non-compliant, 1: compliant, compliance check is not turned on, there is no such field.  This field is obsolete
	int					nCompliantDetailsNum;						  // The number of attribute lists that determine whether they are compliant
	EM_COMPLIANTDETAIL_TYPE			emCompliantDetailType[32];		  // A list of attributes to determine compliance, non-compliance detection reports non-compliance attribute fields, compliance detection reports compliant attribute fields, no compliance detection is enabled, no such field

	int						nHumanPostureTypeNum;					  // The number of emHumanPostureType
	EM_HUMAN_POSTURE_TYPE	emHumanPostureType[32];                   // A list of The type of the Human Posture
	HUMAN_IMAGE_INFO		stuAlongWithFaceHumanImage;				  // Human body image info,when emHumanPostureType contains EM_HUMAN_POSTURE_ALONG_WITH_FACE, it is valid
	SCENE_IMAGE_INFO		stuAlongWithFaceHumanSceneImage;	      // Scene image info,emHumanPostureType contains  EM_HUMAN_POSTURE_ALONG_WITH_FACE, it is valid
	HUMAN_ATTRIBUTES_INFO	stuAlongWithFaceHumanAttributes;		  // Human attributes,emHumanPostureType contains EM_HUMAN_POSTURE_ALONG_WITH_FACE, it is valid
	BOOL							bCompliantMarkEnable;             // Is compliance testing enabled
    NET_HUMAN_FEATURE_VECTOR_INFO   stuAlongWithFaceHumanVectorInfo;  // Position info of human feature data in binary data
    EM_FEATURE_VERSION              emAlongWithFaceHumanVersion;      // Human feature data version
	UINT							nCompliantMode;					  // Compliance type: 0-non-compliant, 1-compliant, compliance check is not turned on, there is no such field
	UINT							nAlarmCompliance;				  // 1: non-compliant 2: compliant
	UINT							nStartSequence;					  // The video Sequence  When the target appears  
	UINT							nEndSequence;					  // The video Sequence  When the target disappears  
	EM_IMAGE_LIGHT_TYPE				emImageLightType;				  // Imaging light type
	HUMAN_ATTRIBUTES_INFO_EX		stuHumanAttributesEx;			  // Extension of  stuHumanAttributes
	HUMAN_ATTRIBUTES_INFO_EX		stuAlongWithFaceHumanAttributesEx;// Extension of  stuAlongWithFaceHumanAttributes
	NET_IMAGE_INFO_EX2				stuImageInfo[32];				  // image information array    
	int								nImageInfoNum;					  // Number of image information
	char                            szObjectUUID[48];                 // Global unique object identification of intelligent object

	char							szHumanFeatureVersion[32];		  // Human feature data version-str
	char							szFaceFeatureVersion[32];		  // Target feature data version-str
	char							szAlongWithFaceHumanVersion[32];  // Human feature data version-str
	NET_EVENT_INFO_EXTEND			stuEventInfoEx;					  // Event public extension field structure
	char							szSerialUUID[22];				// Intelligent object global unique object identification
																	// Valid data bits are 21 bits, including '\0'
																	// Top 2 bits %d%d: 01-video clip, 02-picture, 03-file, 99-other
																	// Middle 14 bit yyyymmddhhmmss
																	// Last 5 bits %U%U%U%U%U: object ID, such as 00001
	char				    		szReserved[2];					// For align
	NET_IMAGE_INFO_EX3*				pstuImageInfo;					// Image information array    
	UINT							nDetectMode;					// The specific type of information contained in the detected object: 0: Only contains attributes 1: Only contains feature values 2: Both attributes and feature values contain 3: Neither attributes nor feature values contain
	int								nStaffType;						/// Is it a specific personnel category, algorithm reported, -1 is not in this category, 0 is unknown, 1 is a specific personnel category
	char							szRoomID[8];					/// Room number
    INT64                           nUniqueID;                      // Target Unique ID
    NET_HUMANTRAIT_PORTRAIT_GATHER_INFO*  pstuPortraitGather;		/// Customized use of docking portrait gathering platform
	UINT							nDirectionStatsResult;			/// Structured statistical direction detection result 0: unknown, 1: from left to right, 2: from right to left
	UINT                            nObjectID;                      // Object ID
    char							szEventUUID[40];				/// Event ID, generated by UUID, identifies a unique event
    TP_U64							nEventUUID;						/// Unique identification of an event
	char							szSourceID[32];					/// Event association ID
	char							szGMIDNumber[64];				/// Guoxin Security Module ID
	char							szFaceKeyVersion[16];			/// Portrait authentication key version
	char							szFaceDataHmac[256];			/// Portrait data authentication code
	NET_VIDEOSTAT_SUMMARY*			pstuVideoStatSummary;			/// Current passenger flow statistics of the channel
	char							szCameraType[32];				/// Camera Type,"Entry";"Depart"
	char							byReserved[376-POINTERSIZE*3];	/// Reserved
}DEV_EVENT_HUMANTRAIT_INFO;

