///@brief Precision of the bitmap
typedef enum tagDH_BITMAP_ACCURACY
{
    BA_DAY ,            //day 
    BA_HOUR ,           //day
    BA_5MIN ,           //5 miuntes
}DH_BITMAP_ACCURACY;

#define DH_MAX_BITMAPS        256                        // Bitmap bytes, DH_MAX_BITMAPS*8-bit
#define DH_MAX_CHN_NUM        256                        // The maximum channel number 
///@brief CLIENT_GetBitmap Interface input parameters 
typedef struct tagDH_IN_BITMAP
{
    DWORD               dwSize;
    NET_TIME            stuStartTime;                   // start time, accurate to seconds 
    NET_TIME            stuEndTime;                     // Over time, accurate to seconds 
    int                 nChnList[DH_MAX_CHN_NUM];       // [1, ..., 10]	Channel number list ,-1 means all channels ,0 means channels end
    DH_BITMAP_ACCURACY  emAccuracy;                     // Precision of the bitmap
	BOOL				bOnlySupportRealUTC;			// TRUE means only deliver stuStartTimeRealUTC and stuEndTimeRealUTC (do not deliver stuStartTime, stuEndTime), FALSE means deliver only stuStartTime, stuEndTime (do not deliver stuStartTimeRealUTC and stuEndTimeRealUTC)
	NET_TIME			stuStartTimeRealUTC;			// UTC start time (standard UTC time), paired with stuEndTimeRealUTC, mutually exclusive with (stuStartTime, stuEndTime)
	NET_TIME			stuEndTimeRealUTC;				// UTC end time (standard UTC time), paired with stuStartTimeRealUTC, mutually exclusive with (stuStartTime, stuEndTime)
}DH_IN_BITMAP;
