///@brief filter protocol
typedef enum tagEM_SNIFFER_FILTER_PROTOCOL
{
    EM_SNIFFER_FILTER_PROTOCOL_UNKNOWN,       // unknown
    EM_SNIFFER_FILTER_PROTOCOL_TCP,           // TCP
    EM_SNIFFER_FILTER_PROTOCOL_UDP,           // UDP
}EM_SNIFFER_FILTER_PROTOCOL;

///@brief filter element
typedef struct tagNET_SNIFFER_FILTER_ELEMENT
{
    char            szSrcIP[64];              // source ip
    char            szDstIP[64];              // destination ip
    int             nSrcPort;                 // source port
    int             nDstPort;                 // destination port
    EM_SNIFFER_FILTER_PROTOCOL emProtocol;    // 0-tcp, 1-udp
    BYTE            byReserved[60];           // reserved
}NET_SNIFFER_FILTER_ELEMENT;

///@brief filter rules
typedef struct tagNET_SNIFFER_FILTER
{
    int                 nMaxElemet;          // the valid num of stuElemets
    NET_SNIFFER_FILTER_ELEMENT stuElemets[8];// filter elements 
    int                 nFilterType;         // 0: use all the section of NET_SNIFFER_FILTER_ELEMENT ; 1: use part of of NET_SNIFFER_FILTER_ELEMENT
    BYTE                byReserved[256];     // reserved 
}NET_SNIFFER_FILTER;

///@brief CLIENT_StartSniffer's interface input param
typedef struct tagDH_IN_START_SNIFFER 
{
	DWORD		dwSize;
	const char*	pszNetInterface;				// name of network card
	const char*	pszPath;						// path of caught file, it is means the default path when pszPath = NULL
	int			nSaveType;						// type of file, 0-Wireshark/Tcpdump, 1-Remotecap, use CLIENT_AttachSniffer
    const char* pszFilter;                  	// Filter Conditions ,Such as "host 172.9.88.200 and port 8080 and tcp"
    int             nCaptureTime;               // capture time unit:s, 0-no timeout.
    unsigned int    nCurrentFileSize;           // current capture file size, unit:kb
    BOOL            bFilterEx;                  // enable high level filter, if true the pszFilter useless.
    NET_SNIFFER_FILTER stuFilterEx;             // high level filter
} DH_IN_START_SNIFFER;

///@brief CLIENT_StartSniffer's interface output param
typedef struct tagDH_OUT_START_SNIFFER 
{
	DWORD		dwSize;
} DH_OUT_START_SNIFFER;

///@brief grasp the package information
typedef struct tagDH_SNIFFER_INFO
{
	DWORD		dwSize;
	DWORD		nSnifferID;					// Sniffer ID
    char        szPath[256];                // Capture file name
    char        szPathEx[10][256];          // Default file path. and the start path
    int         nRetPathEx;                 // The szPathEx valid num.
    UINT        nFileSize[10];              // The file size of szPathEx's element, unit: kb
} DH_SNIFFER_INFO;

