///@brief The type of data packet that was successfully delivered at the end
typedef enum tagENUM_RECORDBACKUP_FILE_PROGRESS_TYPE
{
	ENUM_RECORDBACKUP_FILE_PROGRESS_UNKNOWN,                 // unknown
	ENUM_RECORDBACKUP_FILE_PROGRESS_HEADER_PACKAGE,          // file header package
	ENUM_RECORDBACKUP_FILE_PROGRESS_INDEX_PACKAGE,           // index package
	ENUM_RECORDBACKUP_FILE_PROGRESS_STREAM_PACKET,           // stream package
	ENUM_RECORDBACKUP_FILE_PROGRESS_EMPTY_PACKET,            // empty package at the end of the file
}ENUM_RECORDBACKUP_FILE_PROGRESS_TYPE;

///@brief Recording backup progress
typedef struct tagNET_RECORD_BACKUP_PROGRESS
{
	char									szFilePath[256];				// current backup file name
	ENUM_RECORDBACKUP_FILE_PROGRESS_TYPE	emType;							// The type of the last successful packet
	int										nPosition;						// The position of the last successful data packet
	UINT									nPercent;						// Task progress percentage, 0-100
	int										nRemainingTime;					// The estimated remaining time of the task, in seconds. -1-unknown; 0-completed
	char              						szReserved[512];				// reserved byte
} NET_RECORD_BACKUP_PROGRESS;

///@brief The reason for the failure
typedef enum tagEM_RECORD_BACKUP_FAIL_REASON
{
	EM_RECORD_BACKUP_FAIL_REASON_UNKNOW,					// Unknown
	EM_RECORD_BACKUP_FAIL_REASON_LOGIN_FAIL,				// Login Fail
	EM_RECORD_BACKUP_FAIL_REASON_NO_FILES,					// No recording found
	EM_RECORD_BACKUP_FAIL_REASON_DOWNLOAD_NET_ERROR,		// The network is disconnected during the download process
	EM_RECORD_BACKUP_FAIL_REASON_UNKNOW_ERROR,				// Unknown Error
	EM_RECORD_BACKUP_FAIL_REASON_USER_NAME_NOT_VALID,		// User Name Not Valid 
	EM_RECORD_BACKUP_FAIL_REASON_PASSWORD_NOT_VALID,		// Password Not Valid 
	EM_RECORD_BACKUP_FAIL_REASON_PEER_HAS_BEEN_BLOCKED,		// Peer Has Been Blocked
	EM_RECORD_BACKUP_FAIL_REASON_PEER_IN_BLOCK_LIST,		// Peer In Block List
	EM_RECORD_BACKUP_FAIL_REASON_TOO_MANY_CONNECTIONS,		// Too Many Connections 
	EM_RECORD_BACKUP_FAIL_REASON_ACCOUNT_HAS_BEEN_BLOCKED,	// Account Has Been Blocked 
	EM_RECORD_BACKUP_FAIL_REASON_LOGIN_CONNECT_FAILED,		// Login Connect Failed
	EM_RECORD_BACKUP_FAIL_REASON_USER_OR_PWD_NOT_VALID,		// User Or Pwd Not Valid
	EM_RECORD_BACKUP_FAIL_REASON_LOGIN_CONNECT_TIMEOUT,		// Login Connect Timeout
} EM_RECORD_BACKUP_FAIL_REASON;

///@brief task of record backup to restore
typedef struct tagDH_RECORD_BACKUP_RESTORE_TASK
{
    DWORD				dwSize;
    unsigned int		nTaskID;                        // task ID
    char				szDeviceID[DH_DEV_ID_LEN_EX];   // device ID
    int			        nChannelID;                     // channek ID
    NET_TIME			stuStartTime;                   // record start time
    NET_TIME			stuEndTime;                     // record end time
    int			        nState;                         // state of backup, 0-wait, 1-working, 2-finish, 3-failed, 4-pause
	NET_RECORD_BACKUP_PROGRESS	stuProgress;			// current backup progress
	EM_RECORD_BACKUP_FAIL_REASON	emFailReason;		// The reason for the failure, valid when the emState field is 3
    NET_TIME					stuTaskStartTime;       // execute task start time, valid when nState equal 1(working) or 2(finish) or 3(failed)
    NET_TIME					stuTaskEndTime;         // execute task end time, valid when nState equal 2(finish) or 3(failed)
	int							nRemoteChannel;		  	// backup channel
	double						dbLength;				/// The total length of the task, in bytes, where -1 indicates unknown
} DH_REC_BAK_RST_TASK;

///@brief CLIENT_AddRecordBackupRestoreTask's interface input param
typedef struct tagDH_IN_ADD_RECORD_BACKUP_RESTORE_TASK
{
    DWORD				dwSize;
    const char*			pszDeviceID;					// device ID
    int*		        pnChannels;						// array of channel,the space application by the user,apply to sizeof(int)*nChannelCount
	int					nChannelCount;					// size of array
    NET_TIME			stuStartTime;					// start time
    NET_TIME			stuEndTime;						// end time
	char                szUrl[256];                     // RTSP URL
    BOOL                bIsOffline;                     // Is it a front-end network interruption and continuous transmission task
	int					nStreamTypeNum;					/// Number of stream types
	int					nStreamType[16];					/// Stream type array 0: default (main stream) 1: Jpg image stream; 2: Main stream 3: Extra1 auxiliary stream 1 4: Extra2 stream 2
	char                szRecordSource[32];                     /// Recording source "ChannelIDDirect" indicates retrieval from ChannelID itself; "ChannelIDSubordinate" indicates retrieval from the subordinate of ChannelID
	char                (*pszChannelIDs)[64];                     /// Channel ID list, user-allocated memory, size of 64*nChannelIDNum
	int					nChannelIDNum;                  /// Size of Channel ID list array
} DH_IN_ADD_REC_BAK_RST_TASK, NET_IN_ADD_REC_BAK_RST_TASK;

