///@brief Continuous control PTZ corresponding structure 
typedef struct tagPTZ_Control_Continuously
{
    PTZ_SPEED_UNIT         stuSpeed;              //PTZ speed 
    int                    nTimeOut;              //Continuous motion timeout, the unit is in seconds 
    char                   szReserve[64];         //Reserved
}PTZ_CONTROL_CONTINUOUSLY;

///@brief Absolute control PTZ corresponding structure 
typedef struct tagPTZ_Control_Absolutely
{
    PTZ_SPACE_UNIT         stuPosition;           //PTZ Absolute Speed 
    PTZ_SPEED_UNIT         stuSpeed;              //PTZ Operation Speed
    char                   szReserve[64];         //Reserved
}PTZ_CONTROL_ABSOLUTELY;

///@brief PTZ control coordinate unit,track move
typedef struct tagPTZ_LOCATION_SPACE_UNIT
{
    int                    nPositionX;           //PTZ horizontal motion position, effective range:[0,3600]
    int                    nPositionY;           //PTZ vertical motion position, effective range:[-1800,1800]
    int                    nZoom;                //PTZ zoom position
    char                   szReserve[32];        //Reserved
}PTZ_LOCATION_SPACE_UNIT;

///@brief PTZ control coordinate unit,speed
typedef struct tagPTZ_LOCATION_SPEED_UNIT
{
    int                    nSpeedX;				//PTZ horizontal real Speed ,Left is negative,Right is positive,1000 means 10 degree per second,expanded 100 times
    int                    nSpeedY;				//PTZ vertical real Speed ,Left is negative,Right is positive,1000 means 10 degree per second,expanded 100 times
    char                   szReserve[32];       //Reserved
}PTZ_LOCATION_SPEED_UNIT;

///@brief Tracking object information
typedef struct tagPTZ_LOCATION_TRACK_OBJECT
{
	UINT							nCommand;					/// Instruction, 0: Invalid, 1: Detection on, Autonomous tracking on, 2: Detection on, Autonomous tracking off, 3: Detection off, Tracking off, 4: Detection off, Normal capture report
	UINT							nLinkObjectID;				/// Linked object ID
	UINT							nLinkEventID;				/// Linkage Event ID
	UINT							nAlarmType;					/// Alarm type, the 0th bit indicates whether there is overspeed (1: overspeed, 0: no overspeed), the 1st bit indicates whether AIS matches, the 2nd bit indicates whether driving is prohibited, and the 3rd bit indicates whether driving is in reverse
	UINT							nSpeedValue;				/// Speed, in meters/second, expanded by 100 times
	UINT							nLongitude;					/// Longitude, in millionths of a degree
	UINT							nLatitude;					/// Latitude, in millionths of a degree
	UINT							nDistance;					/// Target distance, in meters, multiplied by 100 times
	char							szObjectType[16];			/// Tracking object type
	NET_TIME						stuLinkRealUTC;				/// The time when external devices (such as radar) recognize the target and report an alarm
	int								nAzimuth;					/// Heading: 0 due north, clockwise as positive, range 0-360, expanded by 100 times to indicate
	char							szLinkTargetUUID[32];		/// Unique ID of the target point
	char							szReserved[1028];			/// Reserved Bytes
}PTZ_LOCATION_TRACK_OBJECT;

///@brief ptz Continuous movement,command DH_EXTPTZ_INTELLI_TRACKMOVE 
typedef struct tagPTZ_CONTROL_INTELLI_TRACKMOVE
{
	DWORD						dwSize;				   // Structure Size
	int							nChannelID;            // channel id
	int							nFlag;				   // move flag
													   // 0:location,speed  is invalid,position Zoom is valid
													   // 1:Continuous movement,speed is invalid,position Zoom is invalid
													   // 2:Continuous movement,speed is valid,position Zoom is invalid
	
	PTZ_LOCATION_SPACE_UNIT     stuPosition;           // PTZ Absolute move position 
    PTZ_LOCATION_SPEED_UNIT		stuSpeed;              // PTZ Operation Speed
	BOOL						bTrackObject;			/// Is tracking object information issued
	PTZ_LOCATION_TRACK_OBJECT	stuTrackObject;			/// Tracking object information
}PTZ_CONTROL_INTELLI_TRACKMOVE;

///@brief Set focus mode. command: DH_EXTPTZ_INTELLI_SETLENSWISDOMSTATE
