///@brief Lane flow statistics
typedef struct tagNET_TRAFFIC_FLOW_STAT
{
    UINT                    nLane;                              // Physical lane number
    UINT                    nRoadwayNumber;                     // Custom lane number
    EM_TRAFFIC_FLOW_STATUS  emStatus;                           // Flow status
    EM_VIRTUAL_COIL_OCCUPANCY_STATUS emHeadCoil;                // The virtual coil state of the front of the car, that is, the car enters the coil
    EM_VIRTUAL_COIL_OCCUPANCY_STATUS emTailCoil;                // The state of the virtual coil at the rear of the car
    UINT                    nSpeed;                             // Average lane speed (unit: km/h)
    UINT                    nQueueLen;                          // Queue length (unit: cm)
    UINT                    nCarsInQueue;                       // Number of queued vehicles
    EM_DETECT_SENSOR_TYPE   emSensorType;                       // Sensor type for detecting objects
	double                  dbSpaceHeadway;                     // Headway, distance between adjacent vehicles, unit: M / vehicle
	double                  dbTimeHeadWay;                      // Headway, unit: S / vehicle
	double					dbSpaceOccRatio;					// Space occupancy, which is the sum of vehicle lengths as a percentage divided by the average distance traveled by the vehicle during the time interval
	UINT					nCarVehicles;						// The number of all vehicles in the lane, i.e. traffic flow
	float					fQueueStartingPoint;				// Vehicle queue start position
	float					fQueueFinishingPoint;				// Vehicle queue end position
	UINT                    nQueueCount;                        // Number of vehicles within the queue range
	float					fDistributionCoefficient;			// Distribution coefficient, variance of vehicle spacing, parameter range for judging the density of vehicle distribution:>=0, with 2 decimal places retained
	int						nDisplaceSpeed[8];					// The percentage of vehicle speed, 85% of all vehicles traveling in the lane have a speed below this speed. For example:% 10,% 15,% 85
	int						nDisplaceSpeedCount;				// The percentage of vehicle speed count
	int						nDisplaceSpeedValueCount;			// Bit speed values count
	float					fDisplaceSpeedValue[8];				// Bit speed values, such as 10.5, 20.0, 100.0, default value is 0, unit: km/h
	UINT					nStaticVehicles;					/// Number of static vehicles in the lane
	UINT					nMovingVehicles;					/// Number of moving vehicles in the lane
    char                	szReserved1[4];                     /// Reserved align bytes
    NET_TRAFFIC_FLOW_STAT_EX* pstuTrafficFlowStatEx;            /// Lane traffic statistics field extension structure, memory released by NetSDK application
    BYTE                    byReserverd[128 - POINTERSIZE];     /// Reserved bytes
}NET_TRAFFIC_FLOW_STAT;

