///@brief device self-check info
typedef struct __NET_SELFCHECK_INFO
{
    DWORD             dwSize;
    int               nAlarmIn;                 // alarm input channel number
    int               nAlarmOut;                // alarm output channel number  
    NET_TIME          stuTime;                  // report time
    char              szPlateNo[DH_MAX_PLATE_NUMBER_LEN]; // plate
    char              szICCID[DH_MAX_SIM_LEN];  // SIM card no.
    BYTE              byOrientation;            // position status, 0-not position, 1-position 
    BYTE              byACCState;               // ACC status, 0-close, 1-open
    BYTE              byConstantElecState;      // power on, 0-normal, 1-disconnect, 2-less pressure, 3-over pressure
    BYTE              byAntennaState;           // channel signal status, 0-normal, 1-unknown failure, 2-disaonnect, 3-short circuit
    
    /* external device status */
    BYTE              byReportStation;          // station announcer status, 0-disconnect, 1-normal, 2-abnormal
    BYTE              byControlScreen;          // dispatch status, 0-disconnect, 1-normal, 2-abnormal
    BYTE              byPOS;                    // POS status, 0-disconnect, 1-normal, 2-abnormal
    BYTE              byCoinBox;                // box status, 0-disconnect, 1-normal, 2-abnormal
    
    /* capacity set */
    BOOL              bTimerSnap;               // schedule snapshot, TRUE-support, FALSE-not support
    BOOL              bElectronEnclosure;       // e-fence, TRUE-support, FALSE-not support
    BOOL              bTeleUpgrade;             // remote upgrade, TRUE-support, FALSE-not support   
    
    NET_HDD_STATE     stuHddStates[DH_MAX_DISKNUM]; //HDD status
    int               nHddNum;                  // HDD quantity
    
    NET_CHANNLE_STATE* pChannleState;           // CLIENT_AttachMission interface,channel status, is a group,  memoryis applied by sdk internally, released by sdk intenally
												// CLIENT_GetSelfCheckInfo interface,output param,memory is applied by the user,apply to sizeof(NET_CHANNLE_STATE)*nChannelMax
	int               nChannleNum;              // channel quantity
    int               nChannelMax;              // pChannleState max counts mallcoed by caller
    NET_PAD_CONNECT_STATE         emConnState;  // PAD/DVR connection state
    NET_HOME_STATE                emHomeState;  // Home key state
	char              szICCIDExInfo[DH_COMMON_STRING_256];  // Extend SIM card no.
	BYTE              by3GState;                // 3G/4G State, 0-disconnect, 1-connect, 2-module not find
	BYTE              byWifiState;              // Wifi State, 0-disconnect, 1-connect, 2-module not find
	BYTE              byGpsState;               // Gps State, 0-disconnect, 1-connect, 2-module not find
	BYTE              byBlackBoxState;          // BlackBox State, 0-disconnect, 1-normal
	int               nCpuUsage;                // CPU Usage, percent
	int               nTemperature;             // Device inner temperature, Celsius
	char			  szVendor[32];				// Manufacturer
	char			  szFirmwareVersion[128];	// Device program version, is an array of characters
	char			  szSecurityBaseLineVersion[8];  // Security baseline version
	NET_GPS_STATUS_INFO	  stuGPSStatusInfo;			// GPS status information
	char			  szNetworkOperName[32];			// 4G operators need to obtain network information from SIM card provider
	EM_EMERGENCYSTATUS_TYPE		emEmergencyStatus;		// Emergency alarm status
	EM_TAMPERALTERSTATUS_TYPE	emTamperAletStatus;		// Device lock status
	char			  szImei[16];						// International mobile device identification code 15 digit digital identification
	UINT			  nGSMsignalStrength;				// 3G signal strength 0 - 31
	UINT			  nMcc;							// Mobile signal country code
	UINT			  nMnc;							// Mobile network number, which is used to identify the mobile network of mobile customers, is composed of 2-3 digits
	UINT			  nLAC;							// Location area code (in mobile communication system) is an area set up for paging, covering a geographical area. At the beginning, it was generally divided into administrative regions (a county or a district). Now it is very flexible, and it is divided by paging volume
	UINT			  nCi;							// Cell identification code, one of the three main location-based service (LBS) technologies. The cell identification code determines the location of the user by identifying which cell in the network transmits the user call and translating the information into latitude and longitude
	int				  nAlarmInStatusNum;			// Number of IO alarm input states
	int				  nAlarmInStatus[32];			// IO alarm input status number IO alarm input status list one dimensional array, each member represents the corresponding channel alarm input status (0 = off; 1 = on)
	int				  nAlarmOutStatusNum;			// Number of IO alarm output states
	int				  nAlarmOutStatus[32];			// IO alarm output status list one dimensional array, each member represents the corresponding channel alarm output status (0 = off; 1 = on)
	char			  szMasterSvrAddr[128];			// IO primary server address, IPv4 format is dotted decimal, IPv6 format is X: X: X: X: X: X: X: X, where x is a 16 bit hexadecimal value
	char			  szSlaveSvrAddr[128];			// From the server address, IPv4 format is dotted decimal, IPv6 format is X: X: X: X: X: X: X: X, where x is a 16 bit hexadecimal value
	char			  szSerialNo[48];				// Equipment serial number
	EM_GPS_SIGNAL_STRENGTH_TYPE emSignalStrength;   // GPS module signal strength
	EM_SELFCHECK_DATA_TYPE      emDataType;         // Event data type
}NET_SELFCHECK_INFO;
