{
	DWORD                           dwSize;
	char                            szRegisterID[MAX_REGISTER_ID_LEN];         // Register ID
	char                            szAppID[MAX_APP_ID_LEN];                   // AppID
} NET_MOBILE_PUSH_NOTIFY_CFG_DEL;

