///@brief  event type EVENT_IVS_HEAT_IMAGING_TEMPER corresponding to data block description info
typedef struct tagDEV_EVENT_HEAT_IMAGING_TEMPER_INFO
{
	char                szName[64];                         // temperature abnormal spot name, select from the Temperature Monitoring rule config
	int                 nAlarmId;                           // alarm number    
	NET_RADIOMETRY_RESULT emResult;                         // alarm result value nValue type
	NET_RADIOMETRY_ALARMCONTION  emAlarmContion;            // alarm condition
	float					fTemperatureValue;              // alarm temperature value 
	NET_TEMPERATURE_UNIT    emTemperatureUnit;              // temperature unit (currently configured temperature unit) 
	DH_POINT            stCoordinate;                       // alarm spot coordinate, relative coordinate system, value is range: [0,8191] 
	UINT                 nPresetID;                          // preset
	UINT                 nChannel;                           // channel number
	int                 nAction;                            // Event action, 1: Start, 2: Stop
	DH_POLY_POINTS      stuAlarmCoordinates;				// alarm coordinates, the type is spot or line or polygon. replace stCoordinate field  
	BOOL				bUseNameEx;							// Whether szNameEx is valid. If TRUE, the szNameEx field is used
	char                reserved1[4];						// Byte alignment
	char				szNameEx[128];						// temperature abnormal spot name extensions
	NET_EVENT_INFO_EXTEND	stuEventInfoEx;					// Event public extension field structure
	float               fThreshold;                         // alarm threshold temperature/temperature slope
	int                 nSlopePeriod;                       // temperature slope period
	float               fSlopeMutation;                     // abrupt change in temperature slope
	int					nChannelID;							// Local channelId
	char				szPresetName[64];					/// Name of preset point
	int                 nSequenceNum;						/// Temperature alarm number, added from 1
	char				szResvered1[4];						/// byte alignment
	float				fMaxValue;							/// Alarm maximum temperature value
	float				fMinValue;							///	Alarm minimum temperature value
	NET_POINT_EX2		stHotPoint;							///	Maximum temperature coordinate point, relative coordinate system, range [0,8191]
	NET_POINT_EX2		stColdPoint;						///	Lowest temperature coordinate point, relative coordinate system, range [0,8191]
	NET_TIME			stuLocaleTime;					    /// Device local time
	int						nIndex;										// ruleId
	char                reserved[744];
} DEV_EVENT_HEAT_IMAGING_TEMPER_INFO;

