	bool							bProhelmet;									// Has the Prohelmet attribute been reported
	bool							bGlasses;									// Has the Glasses attribute been reported
	bool							bFireProofClothes;							// Has the FireProofClothes attribute been reported
	bool							bProtectiveSuit;							// Has the ProtectiveSuit attribute been reported
	bool							bUniform;									// Has the Uniform attribute been reported
