///@brief Corresponding to data block description of event type EVENT_IVS_SECURITYGATE_PERSONALARM (security gate person alarm)
typedef struct tagDEV_EVENT_SECURITYGATE_PERSONALARM_INFO
{
    int                                         nChannelID;                         // Channel id
    int                                         nAction;                            // Event action, 0: Pulse, 1: Start, 2: Stop
    char                                        szName[DH_EVENT_NAME_LEN];          // Event name
    double                                      PTS;                                // Timestamp (in milliseconds)
    NET_TIME_EX                                 UTC;                                // Time for the event occurred   
    UINT                                        nEventID;                           // Event ID
    EM_SECURITYGATE_PERSON_PASS_DIRECTION       emDirection;                        // Direction
    EM_SECURITYGATE_ALARM_LEVEL                 emAlarmLevel;                       // Alarm level
    int                                         nChannelIn;                         // In channel
    int                                         nChannelOut;                        // Out channel
    NET_INTELLIGENCE_IMAGE_INFO                 stuImageInfo;                       // Image info
    UINT                                        nAlarmPositionNum;                  // Count of alarm position
    EM_SECURITYGATE_ALARM_POSITION              emAlarmPosition[18];                // Position of alarm   It is recommended to use emAlarmPositionEx
	NET_SECURITYGATE_ALARM_FACEIMAGE_INFO		stuFaceImageInfo;					// Small picture
	NET_SECURITYGATE_ALARM_FACE_INFO			stuSecurityGateFaceInfo;			// target info
    BYTE                                        byReserved[4];                      // Reserved
    int                                         nCandidateNum;                      // Number of candidates, maximum support 50
    NET_SECURITYGATE_CANDIDATE                  stuCandidates[50];                  // Candidate information
	UINT										nDoorRegion;						// Door partition 0 means 6 partitions 1 means 12 partitions 2 means 18 partitions 3:means 10 partitions;4:means 33 partitions;
	                                                                                // 5:means 1 partitions;6:means 2 partitions;7:means 3 partitions;8:means 4 partitions;9:means 8 partitions;10:means 9 partitions;
	                                                                                // 11:means 16 partitions;12:means 20 partitions;13:means 24 partitions;14:means 36 partitions;15:means 40 partitions;16:means 45 partitions;17:means 48 partitions;18:means 60 partitions
	int											nAlaramPositionNum;					// Number of alarm positions
	UINT										nAlaramPosition[18];				// Alarm position array  It is recommended to use nAlaramPositionEx  When nDoorRegion is 0, the number of arrays is at most 6. 0 means zone 1, 1 means zone 2...5 means zone 6
																					// When nDoorRegion is 1, the number of arrays is up to 12, 0 means left 1, 1 means right 1, 2 means left 2, 3 means right 2...10 means left 6, 11 means right 6
																					// When nDoorRegion is 2, the number of arrays is at most 18. 0 means left 1, 1 means middle 1, 2 means right 2, 3 means left 1, 4 means middle 1, 5 means right 2...15 means left 6, 16 Means 6 in the middle, 17 means 6 from the right
	UINT                                        nPositionNumEx;                     // Number of alarm positions
    EM_SECURITYGATE_ALARM_POSITION              emAlarmPositionEx[128];             // Alarm location expansion
	int											nAlaramPositionNumEx;				// Expansion of alarm position array number
	UINT										nAlaramPositionEx[128];				// Expansion of alarm position array Door partition correlation
	int											nAlarmInfoNum;						// Number of classified alarm messages
	NET_SECURITYGATE_ALARM_INFO					stuAlarmInfo[32];					// Classification alarm information
	NET_EVENT_INFO_EXTEND						stuEventInfoEx;						// Event public extension field structure
	int                                         nPartitionRow;                      // DoorRegion partition row
    int                                         nPartitionColumn;                   // DoorRegion partition column
	NET_SECURITYGATE_ALARM_CANDIDATE_IMAGES_INFO	stuCandidateImages[16];			// Registration database personnel image
	int											nCandidateImagesNum;				// Number of images of registered database personnel
	int											nAlarmInfoExNum;					/// Number of classified alarm messages
	NET_SECURITYGATE_ALARM_INFO					stuAlarmInfoEx[128];				/// Classification alarm information
	char										szResvered[500];					// Reserved bytes
}DEV_EVENT_SECURITYGATE_PERSONALARM_INFO;

///@brief human info
typedef struct tagNET_HUMAN
{
    NET_RECT            stuBoundingBox;						// bounding box(8192 coordinate system)
    UINT                nObjectID;                          // Object ID
    char                szSerialUUID[22];                   // Intelligent object global unique object identification
														    // Valid data bits are 21 bits, including '\0'
														    // Top 2 bits %d%d: 01-video clip, 02-picture, 03-file, 99-other
														    // Middle 14 bit yyyymmddhhmmss
														    // Last 5 bits %U%U%U%U%U: object ID, such as 00001
    BYTE                bReserved[230];                     // reserved
}NET_HUMAN;

