///@brief  Corresponding to data block description of event type EVENT_IVS_RADAR_REGION_DETECTION
typedef struct tagDEV_EVENT_RADAR_REGION_DETECTION_INFO
{
    int                         nChannelID;									// Channel ID
    int                         nAction;									// Event action, 0: Pulse, 1: Start, 2: Stop
    char                        szName[128];								// Event name
    double                      PTS;										// Timestamp (in milliseconds)
    NET_TIME_EX                 UTC;										// Time for the event occurred 
    int                         nEventID;									// Event ID

    UINT                        nRuleID;									// Rule ID,used to indicate which rule triggers
	EM_CLASS_TYPE               emClassType;								// Event class
	DH_EVENT_FILE_INFO          stuFileInfo;                                // Event file info 
	int							nObjectNum;									// The number of object
	NET_RADAR_DETECT_OBJECT		stuObjects[100];							// The list of objects which was detected
	int							nPresetID;									// PresetID
	int							nDetectRegionNum;							// The number of stuDetectRegion
	NET_POINT					stuDetectRegion[DH_MAX_DETECT_REGION_NUM];	// The region of alarm occur, [0,8191]    
	SCENE_IMAGE_INFO_EX			stuSceneImage;								// Scene image(UsestuSceneImageEx when there is more than one image)
	EM_RADAR_ALARM_TYPE			emAlarmType;								// AlarmType
	char                        szAlarmLevel[16];                           // Alarm level
	int                         nAlarmChannel;                              // Alarm input channel number
	int                         nRFIDCardIdNum;                             // RFID Number of card information
	NET_RFID_CARD_INFO          stuRFIDCardId[256];                         // RFID Card information, Up to 256 card information is supported
	SCENE_IMAGE_INFO_EX			stuSceneImageEx[10];						// Panoramic wide-angle view (expanded to 10)
	int							nstuSceneImageExNum;						// Number of panoramic wide-angle images
	int							nSpeed;										// The speed of the trigger event target, transmitted by integer, expanded by 100 times, unit m/s							
	int							nTrackID;									// id of trigger event target, range [0,63]
	int							nObjectType;								// Mask of the type of trigger event target: 0x00 unidentified target, 0x01 target is human, 0x02 target is vehicle, 0x03 target is tree, 0x04 target is building, 0x05 target is screen, 0x06 target is animal, 0x07 targets large ships, 0x08 targets medium ships, and 0x09 targets small ships
	int							nAlarmFlag;									// Alarm flag bit, the 0th bit indicates whether it is overspeeding, and the 1st bit indicates whether the AIS matches The 2nd bit indicates whether the line is prohibited, and the 3rd bit indicates whether it is retrograde
	int                         nLongitude;                                 // longitude,Use integer transmission, 1000000 times, valid for 6 digits after the decimal point, and make up for less than 6 digits with 0
	int                         nLatitude;                                  // Latitude Use integer transmission, 1000000 times, valid for 6 digits after the decimal point, and make up for less than 6 digits with 0
	int                         nUpDownGoing;                               // Lane / channel direction - 1: unknown 0: invalid 1: up 2: down
	NET_EVENT_INFO_EXTEND		stuEventInfoEx;								// Event public extension field structure	
	int							nDistance;									// Pixel polar coordinate value of current trigger event target -- distance, result of 100 times expansion, unit: meter
	int							nAngle;										// Polar coordinate value of current trigger event target -- angle, result of 100 times expansion, unit:degree
	char						szTargetUUID[32];							// Alarm target unique ID
	int							nLinkAlarmID;								// Link alarm ID
	BYTE						byReserved[952];							// Reserved
} DEV_EVENT_RADAR_REGION_DETECTION_INFO;


