	UINT						nEventID;				        // Event ID
	char						szName[128];			        // Event name
    char						szClass[16];                    // Intelligent events belong to a category
    double						dbPTS;					        // Relative event timestamp, in milliseconds

	UINT						nForwardCollideFlag;			// Forward collision warning flag, 0: no warning 1: warning
	UINT						nForwardCollideReportFlag;		// Forward collision report flag, 0: no warning 1: warning
	float						fForwardCollideTime;			// Time consumption of forward collision, unit: second, valid when the value of nForwardCollideFlag or nForwardCollideReportFlag is 1
	UINT						nTooCloseFlag;					// Warning flag of too close distance: 0: no warning 1: warning
	UINT						nTooCloseReportFlag;			// Too close report flag, 0: no alert 1: alert
