///@brief Consumption event
typedef struct tagDEV_EVENT_CONSUMPTION_EVENT_INFO
{
	int                         nChannelID;						// Channel number
	int                         nAction;						// 0: pulse
	char                        szName[128];					// event name
	double                      dbPTS;							// Timestamp (unit is milliseconds)
	NET_TIME_EX                 stuUTC;							// Time when the event occurred
	int							nEventID;						// Event ID
	
	BOOL						bRealUTC;						// whether RealUTC is valid. when bRealUTC is TRUE, use RealUTC, otherwise use stuUTC
	NET_TIME_EX         		RealUTC;            			// Event occur time
	UINT						nRecNo; 						// Record No
	UINT						nBlockId;						// serial number
	NET_ACCESS_CTL_EVENT_TYPE	emType;							// Type
	EM_CONSUMPTION_STATUS		emStatus;						// Status
	NET_ACCESSCTLCARD_TYPE		emCardType; 					// Card Type
    EM_USER_TYPE		        emUserType;                     // User Type
	NET_ACCESSCTLCARD_STATE		emCardStatus;					// Card Status
	NET_ACCESS_DOOROPEN_METHOD	emMethod;						// Method
	char						szCardNo[16];					// Card No	
	char						szReaderID[32]; 				// Reader ID
	char						szUserID[12];					// UserID
	UINT						nErrorCode; 					// Reason of unlock failure, only because it is valid when bStatus is fail
                                                                // 0x00 no error
                                                                // 0x10 unauthorized
                                                                // 0x11 card lost or cancelled
                                                                // 0x12 no door right
                                                                // 0x13 unlock mode error
                                                                // 0x14 valid period error
                                                                // 0x15 anti sneak into mode
                                                                // 0x16 forced alarm not unlocked
                                                                // 0x17 door NC status
                                                                // 0x18 AB lock status
                                                                // 0x19 patrol card
                                                                // 0x1A device is under intrusion alarm status
                                                                // 0x20 period error
                                                                // 0x21 unlock period error in holiday period
                                                                // 0x30 first card right check required
                                                                // 0x40 card correct, input password error
                                                                // 0x41 card correct, input password timed out
                                                                // 0x42 card correct, input information error
                                                                // 0x43 card correct, input information timed out
                                                                // 0x44 information correct, input password error
                                                                // 0x45 information correct, input password timed out
                                                                // 0x50 group unlock sequence error
                                                                // 0x51 test required for group unlock
                                                                // 0x60 test passed, control unauthorized
                                                                // 0x61 card correct, infomation error
                                                                // 0x62 card correct, infomation timed out
                                                                // 0x63 repeat enter
                                                                // 0x64 unauthorized, requiring back-end platform identification
                                                                // 0x65 Abnormal temperature
																// 0x66	no mask
																// 0x67 get health code fail
																// 0x68 No Entry because of yellow code
																// 0x69 No Entry because of red code
																// 0x6a health code is invalid
																// 0x6b entry because of green code
																// 0x70 get health code info

	char						szSnapURL[128]; 				// Snap Path
	UINT						nSimilarity;					// Similarity
	EM_CONSUMPTION_EVENT_TYPE	emEventType;					// Event Type
	UINT						nConsumptionAmount; 			// ConsumptionAmount, unit is cent
	UINT						nRechargeAmount;				// Recharge Amount, unit is cent
	char						szTransactionSerialNumber[128]; // Transaction Serial Number	
	int							nImageCount;					// count of the image
	DEV_ACCESS_CTL_IMAGE_INFO	stuImageInfos[6];				// image info
	
	char						szLastTransactionSerialNumber[128]; // Last transaction serial number
	char                		szReserved[896];       		//  Reserved bytes, reserved for expansion
}DEV_EVENT_CONSUMPTION_EVENT_INFO;

