///@brief Faulty traffic light information
typedef struct tagNET_FAULTLIGHT_INFO
{
	BOOL                				bState;					// true means fault occurred, false means fault cleared
	UINT								nDirection;				// Bitwise representation: 1 means "yes", 0 means "no".
                                                                // Bit 0: U-turn;
                                                                // Bit 1: Left turn;
                                                                // Bit 2: Straight;
                                                                // Bit 3: Right turn
	UINT								nColor;				    // Bitwise representation: 1 means "yes", 0 means "no". 
                                                                // Bit 0: Red light;
                                                                // Bit 1: Green light;
                                                                // Bit 2: Yellow light;
	int            						nLightID;				// Light group ID
	EM_TRAVELING_DIRECTION				emLightDirection;		// Vehicle travel direction indicated by the light group
	char						        szReserved[60];		    // Reserved bytes
}NET_FAULTLIGHT_INFO;

