///@brief OpenSSL library information configuration
typedef struct tagNET_CONFIG_OPENSSL_INFO
{
	char		szSsleay[MAX_PATH];		//openssl Protocol library 
										//Under windows, it is the full path of ssleay32.dll library. When the path is empty, it will start from the current library by default NetSDK.dll Search and load under path
										//Linux  for libssl.so	Library full trouser legs, when the path is empty, the default is to search and load from the system path
	char		szLibeay[MAX_PATH];		//openssl Encryption library
										//Under windows, it is the full path of libeay32.dll library. When the path is empty, it will start from the current library by default NetSDK.dll Search and load under path
										//Linux  for libcrypto.so Library full trouser legs, when the path is empty, the default is to search and load from the system path
	BYTE		bReserved[504];			//Reserved
}NET_CONFIG_OPENSSL_INFO;

///@brief StreamConvertor transcoding library information configuration
typedef struct tagNET_CONFIG_STREAMCONVERTOR_INFO 
{
	char		szStreamConvertor[MAX_PATH];		//StreamConvertor  transcoding library
													//Windows: It is the full path of the StreamConvertor.dll library. When the path is empty, it will search and load from the current dhnetsdk.dll path by default.
													//Linux:   It is the full path of the libStreamConvertor.so library. When the path is empty, the default is to find and load from the current libdhnetsdk.so path.
													//Mac OS:  It is the full path of libStreamConvertor.so/libStreamConvertor.dylib. When the path is empty, the default is to find and load from the current libdhnetsdk.so path.
													//		   In Mac OS, the default transcoding library is libStreamConvertor.so. When the loading fails, the transcoding library is considered libStreamConvertor.dylib
	BYTE		bReserved[764];						//Reserved

}NET_CONFIG_STREAMCONVERTOR_INFO;

///@brief avnetsdk library information configuration
typedef struct tagNET_CONFIG_AVNETSDK_INFO
{
	char		szAvnetsdk[MAX_PATH];		//avnetsdk library
											//Windows:  It is the full path of the avnetsdk.dll	library,When the path is empty, it will search and load from the current dhnetsdk.dll path by default.
											//Linux:	It is the full path of the avnetsdk.so	library,When the path is empty, the default is to find and load from the current libdhnetsdk.so path.
											//Mac OS:   It is the full path of the avnetsdk.so  library,When the path is empty, the default is to find and load from the current libdhnetsdk.so path.
	BYTE		bReserved[764];				//Reserved
}NET_CONFIG_AVNETSDK_INFO;


