///@brief Specifies the conversion type
typedef enum tagNET_EM_DEC_AND_HEX_CONVERT
{
	NET_EM_DEC_AND_HEX_CONVERT_UNKNOWN = -1, /// The type is unknown
	NET_EM_DEC_AND_HEX_CONVERT_NOT_CONVERT, /// No conversion is required
	NET_EM_DEC_AND_HEX_CONVERT_TYPE_ONE, /// decimal to hexadecimal 8-bit card number (Conversion rule: Convert the original decimal card number 04315437 to hexadecimal 8-bit card number 0041D92D)
	NET_EM_DEC_AND_HEX_CONVERT_TYPE_TWO, /// Hexadecimal to decimal 10-bit card number (conversion rule: original hexadecimal card number 1A2B3C4D, then converted to decimal 10-bit card number 0439041101)
	NET_EM_DEC_AND_HEX_CONVERT_TYPE_THREE, /// Hexadecimal to decimal card number (decimal transparent transmission, no limit on the number of bits) (conversion rule: Original hexadecimal card printing number 1A2B3C4D, converted to decimal card number 439041101)
	NET_EM_DEC_AND_HEX_CONVERT_TYPE_FOUR, /// Hexadecimal to decimal 8-bit card number (Conversion rule: The original hexadecimal card printing number 0000DC5D, then converted to the decimal 8-bit card number 00056413, less than 8-bit zeros)
}NET_EM_DEC_AND_HEX_CONVERT;

///@brief Special conversion rule
typedef enum tagNET_EM_SPECIAL_CONVERT
{
	NET_EM_SPECIAL_CONVERT_UNKNOWN = -1, /// Unknown type
	NET_EM_SPECIAL_CONVERT_NOT_CONVERT, /// No conversion is required
}NET_EM_SPECIAL_CONVERT;

///@brief conversion rule
typedef struct tagNET_CARD_NO_CONVERT_RULE
{
	BOOL                                    bReverse;                /// Card number inversion (conversion rule: reverse by byte, the original card number 1A2B3C4D, converted to 4D3C2B1A)
	BOOL                                    bHighestByteZero;        /// The maximum byte is set to zero (conversion rule: the maximum byte is set to 00, the original card number 1A2B3C4D, converted to 002B3C4D)
	BOOL                                    bHIDPro;                 /// HIDPro conversion (conversion rule: original card number 1A2B3C4D, 2B to decimal 043,3 C4D to decimal 15437, consisting of 04315437)
	NET_EM_DEC_AND_HEX_CONVERT              emDecAndHexConvert;      /// Decimal conversion type
	NET_EM_SPECIAL_CONVERT                  emSpecial;               /// Special conversion rules
	char                                    szReserved[1004];        /// Reserved bytes
}NET_CARD_NO_CONVERT_RULE;

///@brief Indicates the configuration information of the card number conversion rule
typedef struct tagNET_CARD_NO_CONVERT_CONFIG_INFO
{
	NET_CARD_NO_CONVERT_RULE                stuLocalConvert;         /// Native conversion rule
	NET_CARD_NO_CONVERT_RULE                stuWiegandOut;           /// Wiegand output conversion
	NET_CARD_NO_CONVERT_RULE                stuWiegandIn;            /// Wiegand input conversion
	NET_CARD_NO_CONVERT_RULE                stuSerialOut;            /// Serial port output conversion
	NET_CARD_NO_CONVERT_RULE                stuSerialIn;             /// Serial port input conversion
	char                                    szReserved[1024];        /// Reserved bytes
}NET_CARD_NO_CONVERT_CONFIG_INFO;

///@brief NET_EM_CFG_CARD_NO_CONVERT_CONFIG Configure the card number conversion rule
typedef struct tagNET_EM_CFG_CARD_NO_CONVERT_CONFIG_INFO
{
	DWORD									dwSize;					             /// Structure size
	int                                     nCardNoConvertConfigNum;             /// Card number conversion rule Configuration information array Number of arrays
	NET_CARD_NO_CONVERT_CONFIG_INFO*        pCardNoConvertConfig;                /// Card number conversion rule configuration information array, the user needs to apply for memory, the application size is sizeof(NET_CARD_NO_CONVERT_CONFIG_INFO)*nCardNoConvertConfigNum
	int                                     nCardNoConvertConfigRetNum;          /// Actual returned card number conversion rule configuration information array Number of arrays
}NET_EM_CFG_CARD_NO_CONVERT_CONFIG_INFO;

///@brief NET_EM_CFG_CARD_SET Configure the card set conversion rule
typedef struct tagNET_CFG_CARD_SET_INFO
{
	DWORD									dwSize;					            /// Structure size
	BOOL									bICEncryptEnable;					/// IC card encryption enable
	BOOL									bCPUPhysicalEnable;					/// Is reading CPU physical card number enabled
	BOOL									bICCardEnable;						/// Control the opening and closing of IC card reading. True: IC card reading enabled; False: IC card read. Default enabled
	BOOL									bReadICEncryptEnable;				/// Control the opening and closing of the IC encryption card reading, which can only be set based on the enabling of the IC card. True: IC encryption card reading enabled; False: IC encryption card read
	BOOL									bCPUCardEnable;						/// Control the opening and closing of CPU card reading. True: CPU card reading is enabled, and only the physical card number of the CPU card can be read; False: CPU card read turned off
	BOOL									bPSAMEnable;						/// Control the opening and closing of CPU card reading content, and only the basic settings that enable CPU card reading can be set. True: CPU card reading content enabled; False: CPU card read content turned off. Must match PASM small card
	BOOL									bDesfireCardEnable;					/// Control whether the Desfire card can be swiped. True: indicates that the Desfire card can be swiped; False: indicates that it is not possible to swipe the Desfire card
	BOOL									bReadDesfireCardEncryptEnable;		/// Control whether it is possible to swipe the encrypted content of the Desire card. True: indicates that it is possible to swipe the encrypted content of the Desire card; False: indicates that it is not possible to encrypt content by flashing the Desfire card
	BOOL									bNFCAntiCopyEnable;					/// Whether to enable flashing NFC anti copy cards on mobile phones. True: indicates that NFC anti copy is enabled, and cards copied on mobile phones cannot be swiped; False: indicates that NFC anti copying is turned off, and the copied cards on the phone can be swiped. The default value is false
}NET_CFG_CARD_SET_INFO;

