typedef enum tagEM_NET_ACCESS_TYPE
{
    EM_NET_ACCESS_TYPE_UNKNOWN    = -1,     // Unknown
    EM_NET_ACCESS_TYPE_OFF,                 // Off
    EM_NET_ACCESS_TYPE_ALLOW,               // Allow list
    EM_NET_ACCESS_TYPE_BLOCK,               //  Block list  
} EM_NET_ACCESS_TYPE;

///@brief Information of allow list
typedef struct tagNET_ALLOW_ADDR_INFO
{
    int         nEnableState;           // The enable state of subitems, 0: enabled (default) 1: not enabled
    char        szBeginIP[64];          // The starting IP is the IPv4 / IPv6 address; the internal address is distinguished according to the separator, '.', which means IPv4, and ':', which means IPv6
    char        szEndIP[64];            // End IP: if szBeginIP = = szEndIP, only the address is allowed; if both are "0.0.0.0" (IPv4) / "::" (IPv6), the field will be ignored;
                                        //Note: it must be of the same type as beginip, that is, both are IPv4 or IPv6
    UINT        nBeginPort;             // Starting port number, 0 indicates invalid port, do not need to care about this value
    UINT        nEndPort;               // End port number. If nBeginPort = = nEndPort, only the port is allowed; if both are 0, the field is ignored
    char        szMac[20];              // MAC address, regardless of case, must be separated by ":", where "0:0:0:0:0:0:0" indicates that the field is ignored
    BYTE        bReserverd[1024];       // Reserverd
} NET_ALLOW_ADDR_INFO;

///@brief Information of block list
typedef struct tagNET_BLOCK_ADDR_INFO
{
    int         nEnableState;           // The enable state of subitems, 0: enabled (default) 1: not enabled
    char        szBeginIP[64];          // The starting IP is the IPv4 / IPv6 address; the internal address is distinguished according to the separator, '.', which means IPv4, and ':', which means IPv6
    char        szEndIP[64];            // End IP: if szBeginIP = = szEndIP, only the address is unable; if both are "0.0.0.0" (IPv4) / "::" (IPv6), the field will be ignored;
                                        // Note: it must be of the same type as beginip, that is, both are IPv4 or IPv6
    UINT        nBeginPort;             //  Starting port number, 0 indicates invalid port, do not need to care about this value
    UINT        nEndPort;               // End port number. If nBeginPort = = nEndPort, only the port is unable; if both are 0, the field is ignored
    char        szMac[20];              // MAC address, regardless of case, must be separated by ":", where "0:0:0:0:0:0:0" indicates that the field is ignored
    BYTE        bReserverd[1024];       // Reserverd
} NET_BLOCK_ADDR_INFO;

///@brief Information of NTP  address
typedef struct tagNET_NTP_ADDR_INFO
{
    int         nEnableState;           // The enable state of subitems, 0: enabled (default) 1: not enabled
    char        szBeginIP[64];          // The starting IP is the same as the field meaning of network access when IP is used; when domain name is used, DNS resolution will be performed internally and all IP addresses that can be resolved will be allowed.
    char        szEndIP[64];            // The end IP has the same meaning as szBeginIP
    BYTE        bReserverd[1020];       // Reserverd        
} NET_NTP_ADDR_INFO;

///@brief Allow access info of NTP
