///@brief Async realplay state
typedef enum tagEM_ASYNC_REALPLAY_STATE
{
    EM_ASYNC_REALPLAY_NORMAL,                   // Normal state of intermediate process
    EM_ASYNC_REALPLAY_SUCCESS,                  // Async realplay succeeded, and the task is end.
    EM_ASYNC_REALPLAY_CHECK_ERROR,				// Asynchronous pull check error.
    EM_ASYNC_REALPLAY_SPECIAL_CHANNEL_ERROR,    // Failed to get special channel info.
    EM_ASYNC_REALPLAY_INVALID_CHANNEL,          // The channel is invalid.
    EM_ASYNC_REALPLAY_SETUPSESSION_ERROR,       // Failed to setup session.
    EM_ASYNC_REALPLAY_RENDER_ERROR,             // Failed to prepare render resource.
    EM_ASYNC_REALPLAY_OPENCHANNEL_ERROR,        // Failed to open media channel.
    EM_ASYNC_REALPLAY_GDPR_ERROR,               // GDPR error
} EM_ASYNC_REALPLAY_STATE;

