typedef struct tagNET_IN_PTZBASE_MOVEABSOLUTELY_INFO
{
	DWORD								dwSize;				// struct size
	int									nZoomFlag;			// 1 according to ratio, 2 Reserved, 3 Mapping radio; 0 default Mapping radio
	NET_PTZSPACE_UNNORMALIZED			stuPosition;        // Ptz absolutely position
															// Horizontal angle(0~3600)
															// Vertical angle(-1800~1800)
															// Zoom(0~16384)
	NET_PTZSPACE_UNNORMALIZED			stuSpeed;			// If there is no speed, it means the default speed movement P, T, with 0.01 degree/second as the unit, enlarged by 100 times, the range is consistent with the range in PtzSpeedLevel [0, 100000], the maximum horizontal and vertical respectively will not exceed the maximum in PtzSpeedLevel The maximum value of the horizontal and vertical gears, the zoom speed is 0~100.
	int														nRegionCode;	// RegionCode
	BYTE								byReserved[444];    // Reserved
}NET_IN_PTZBASE_MOVEABSOLUTELY_INFO;

