	NET_TIME					stuStartTimeRealUTC;	// Recording start UTC time (standard UTC time)
	NET_TIME					stuEndTimeRealUTC;		// end UTC time of recording (standard UTC time)
	fTimeDownLoadPosCallBackEx  cbDownLoadPosEx;        // Extension of progress callback (if using standard UTC time to download, use this callback)
	fVKInfoCallBack				pVKInfoCallBack;		// VK information callback
	LDWORD						dwVKInfoUser;			// VK information callback user information
	BOOL							bWait;						// Whether to synchronize and return error codes
