///@brief CLIENT_GetDevCaps interface NET_SUPPORT_UTC_CAPS output parameter
typedef struct tagNET_OUT_UTC_CAPS
{
	DWORD						dwSize;										// struct size
	int 						nSupportUTCTimingCaps;						// Whether the device supports UTC timing capability, including setting and obtaining, 0: not supported, 1: supported
	int 						nSupportMediaFileFindGeneralUTCCaps;		// Whether the device supports the UTC capability of general recording query (this capability includes recording calendar), 0: not supported, 1: supported (the related interfaces are: CLIENT_StartQueryRecordFile, CLIENT_QueryRecordFileEx, CLIENT_FindFileEx, CLIENT_FindNextFileEx, CLIENT_QueryRecordStatus (video calendar query) )
	int 						nSupportPlayBackUTCCaps;					// Whether the device supports the UTC capability of video playback, including setting and obtaining, 0: not supported, 1: supported (the related interfaces are: interface for playback by time (CLIENT_PlayBackByTimeProxy, CLIENT_PlayBackByTimeEx2), interface for playback by file ( CLIENT_PlayBackByRecordFileEx2) )
	int 						nSupportDownloadUTCCaps;					// Whether the device supports the UTC capability of video download, 0: not supported, 1: supported (the related interface is: CLIENT_AdaptiveDownloadByTime)
	int 						nSupportDownloadByAllSpeedUTCCaps;			// Whether the device supports the UTC capability of full-speed playback without frame extraction (recording by time), 0: not supported, 1: supported (the related interface is: CLIENT_SupplementByTime)
	int 						nSupportMediaFileFindMobileEnforceUTCCaps;	// Whether the device supports the UTC capability of the acquisition station and handheld terminal file information video query, 0: not supported, 1: supported (the related interfaces are: CLIENT_FindFileEx+DH_FILE_QUERY_MOBILE_ENFORCE+MEDIAFILE_MOBILE_ENFORCE_PARAM , CLIENT_FindNextFileEx+MEDIAFILE_MOBILE_ENFORCE_INFO)
	int							nSupportAccessCardRecUTC;					// Whether the device supports query based on real UTC time
	int							nSupportAnnouncementRecUTC;					 // Whether the device supports the query of building information release records based on the real UTC time. 0: No, 1: Yes
	int							nSupportVideoTalkLogRecUTC;					 // Whether the device supports the query of intercom records based on the real UTC time. 0: The UTC time is not supported. 1: The UTC time is supported
	int							nSupportFileStreamRecUTC;		             // Whether the device supports SMD video query The query is based on the real UTC time. 0: Not supported, 1: supported
	int							nSupportLogRecUTC;					         // Whether the device supports log query The query is based on the actual UTC time. 0: No, 1: Yes
	int							nSupportAccessControlAlarmRecordRecUTC;		 // Whether the device supports access control alarm records. Query the real UTC time. 0: not supported, 1: supported
	int							nSupportFaceDBServerRecUTC;		             // Whether the device supports the real UTC search of the face database, 0: not supported, 1: supported
	int							nSupportPOSUTC;		                         // POS record query Whether the device supports POS record query based on the real UTC time. 0: Not supported, 1: supported
    int							nSupportInteliPicSearchRealUTC;		         // Whether the device supports intelligent image search mediaFileFind component image search. 0: not supported, 1: supported
}NET_OUT_UTC_CAPS;

