///@brief Interface CLIENT_StartFind  command NET_FIND_POS_EXCHANGE in param       
typedef struct tagNET_IN_POSEXCHANGE_STARTFIND       
{       
    DWORD							dwSize;														//struct size       
    int								nChannel;													//channel number, 0 - first channel, -1 - all channel       
    NET_TIME_EX						stuStartTime;												//start time       
    NET_TIME_EX				        stuEndTime;													//end time       
    char							szGoods[DH_POS_EXCHANGE_GOODS_MAX][DH_COMMON_STRING_32];    //goods       
    EM_NET_POS_EXCHANGE_FUSSY_KEY   szFuzzyPattern[DH_POS_EXCHANGE_FUSSY_KEY_MAX];			    //Fuzzy pattern       
    int                             nPosId;                                                     //Pos id, -1 means all pos
	int								 nChannelsCount;											//Number of channel number arrays
	int*							 pChannels;													//Channel number array, this part of the memory needs to be requested by the user, with a request size of (number of channel number arrays * sizeof (int)). Starting from 0, there must be at least one Channel and Channels field, and they should not both exist. If both exist, the Channels field should prevail
	char						     szGoodsEx[4][128];			                                //Product name extension, optional, string
    UINT                             nGoodsExNum;                                               //Number of valid extension product names
    BOOL                             bUseGoodsEx;                                               //Do you want to use an extended product name
	int								nPosIDsNum;													// Number of PosID arrays
	int								nPosIDs[64];												// PosID array
	int								nPOSActionTypeNum;											// POS ActionType Num
	char							szPOSActionType[64][64];									// POS Action Type
	NET_STARTFIND_STORE_INFO		stuStoreInfo;												// Store Info
	char							szKeyWord[256];												// Key Word
	char							szFuzzyPatternEx[8][32];									// Fuzzy Pattern
	int								nFuzzyPatternExNum;											// Fuzzy PatternEx Num
	BOOL							bUseFuzzyPatternEx;											// Use Fuzzy PatternEx
	NET_TIME						stuStartTimeRealUTC;										// Start Time RealUTC,TZ Format
	NET_TIME						stuEndTimeRealUTC;											// End Time RealUTC,TZ Format
	BOOL							bUseTimeRealUTC;											// Use Time RealUTC
	BOOL							bUseStoreInfo;												// Use Store Info
	char							szOrder[8];													// Order:"Ascent","Descent"
	int								nID[2];														// ID
	BOOL							bUseID;														// Use ID
	BOOL							bUseProductInfo;											// Use Product Info
	NET_STARTFIND_PRODUCT_INFO		stuProductInfo;												// Product Info
} NET_IN_POSEXCHANGE_STARTFIND;       
        
