///@brief Reported image key information of fAnalyzerDataCallBackSec
typedef struct tagNET_REAL_LOAD_ENCRYPT_INFO
{
    EM_ALGORITHM_LIST                   emAlgorithm;            // encryption algorithm
    char                                szKey[128];             // encryption key
    char                                szIV[128];              // Initialize Vector IV
    BYTE                                bReserved[512];         // Reserved
}NET_REAL_LOAD_ENCRYPT_INFO;

///@brief fAnalyzerDataCallBackSec Callback information
typedef struct tagNET_REAL_LOAD_PIC_INFO
{
    DWORD                               dwAlarmType;            // Alarm type
    BYTE                                bReserved[4];           // byte alignment
    void*                               pAlarmInfo;             // Intelligent event information, taking the corresponding structure pointer based on the value of dwAlarm Type
    BYTE*                               pOriBuffer;                // Encrypted image pointer
    DWORD                               dwOriBufSize;              // Encrypted Image Size
    DWORD                               dwBufSize;              // Decrypt Image Size
	BYTE*                               pBuffer;                // Decrypting image pointer
    NET_REAL_LOAD_ENCRYPT_INFO*         pEncryptInfo;           // Image decryption information
	int                                 nSequence;              // Indicates the same image situation uploaded, 0 indicates the first occurrence, 2 indicates the last occurrence or only one occurrence, and 1 indicates there will be more after this time
    BYTE                                bReserved1[64];         // Reserved
}NET_REAL_LOAD_PIC_INFO;

