///@brief Return code stream type
typedef enum tagEM_RECORD_BACKUP_STREAM_TYPE
{
	EM_RECORD_BACKUP_STREAM_TYPE_UNKNOWN,			// unknown
	EM_RECORD_BACKUP_STREAM_TYPE_JPG,				// Picture stream 
	EM_RECORD_BACKUP_STREAM_TYPE_MAIN,				// main video stream
}EM_RECORD_BACKUP_STREAM_TYPE;

///@brief Current backup status
typedef enum tagEM_RECORD_BACKUP_STATE
{
	EM_RECORD_BACKUP_STATE_UNKNOWN,				// unknown
	EM_RECORD_BACKUP_STATE_NORMAL,				// Not yet started 
	EM_RECORD_BACKUP_STATE_RUNNING,				// In progress
	EM_RECORD_BACKUP_STATE_FINISHED,			// Completed 
	EM_RECORD_BACKUP_STATE_FAILED,				// Failed
	EM_RECORD_BACKUP_STATE_PAUSE,				// Pause 
}EM_RECORD_BACKUP_STATE;

///@brief Record backup task information table
typedef struct tagNET_RECORD_BACKUP_RESTORE_TASK_INFO
{
	UINT							nTaskID;                        // Task ID
	char							byReserved[4];					// Byte alignment
	char							szDevice[128];					// Backup source device
	int								nChannelID;                     // Channel number
	int								nRemoteChannel;                 // Backup source channel
	NET_TIME						stuStartTime;                   // Start time
	NET_TIME						stuEndTime;                     // End time
	double							dbLength;						// The total length of the task, in bytes, -1 means unknown
	EM_RECORD_BACKUP_STREAM_TYPE	emStreamType[32];				// Return stream type
	int								nStreamTypeNums;				// Number of stream types returned
	EM_RECORD_BACKUP_STATE			emState;                        // Current backup state, 0- not yet started, 1- in progress, 2- completed, 3- failed, 4- suspended
	NET_RECORD_BACKUP_PROGRESS		stuProgress;					// Current backup progress
	EM_RECORD_BACKUP_FAIL_REASON	emFailReason;					// The reason for the failure, valid when the emState field is 3
	float							fExternInfoSpeed;				/// Download speed, in Mbps
	NET_TIME 						stuExecuteTaskStartTime; 		/// Start time of executing the task; valid when the task state is "in progress", "completed", or "failed"
	NET_TIME 						stuExecuteTaskEndTime; 			/// End time of executing the task; valid when the task state is "completed" or "failed"
	char							szExternInfoAP[32];				/// AP's MAC address
	char							szReserved[168];				/// Reserved byte
} NET_RECORD_BACKUP_RESTORE_TASK_INFO;

///@brief CLIENT_GetRecordBackupRestoreTaskInfoOffline interface input parameters
typedef struct tagNET_IN_GET_RECORD_BACKUP_RESTORE_TASK_INFO_OFFLINE
{
	DWORD               dwSize;
} NET_IN_GET_RECORD_BACKUP_RESTORE_TASK_INFO_OFFLINE;

///@brief CLIENT_GetRecordBackupRestoreTaskInfoOffline interface output parameters
typedef struct tagNET_OUT_GET_RECORD_BACKUP_RESTORE_TASK_INFO_OFFLINE
{
	DWORD								   dwSize;
	int									   nMaxCount;                  // Array size, the maximum is 2048
	int									   nReturnCount;               // The number of returned task information tables, the maximum is 2048
	char								   byReserved[4];			   // Byte alignment
	NET_RECORD_BACKUP_RESTORE_TASK_INFO*   pTasks;                     // Record backup task information table, the user applies for memory, the size is sizeof(DH_RECORD_BACKUP_RESTORE_TASK_INFO)*nMaxCount
} NET_OUT_GET_RECORD_BACKUP_RESTORE_TASK_INFO_OFFLINE;

///@brief Get the task information of the video backup when the network is disconnected, lRestoreID is obtained by CLIENT_StartRecordBackupRestore, and the memory of pInParam and pOutParam will be released by the user
