///@brief local optimization modes
typedef enum __EM_LOCAL_MODE
{
	EM_LOCAL_GDPR_SET_MODE = 100,		//Set whether gdpr queries configuration: 0-default process; 1-gdpr1. X device, bitstream encryption is enabled, do not get configuration;
									    // 2-gdpr1. X device, bitstream encryption is not enabled, and configuration is not obtained; 3-Non gdpr device, configuration is not obtained, attachvk and getvk are filtered
	EM_LOCAL_PLAY_FLAG_MODE = 101,      // Real time preview policy flag bit0 = = 1 does not support picture in picture Bit1 = = 1 does not support channel information verification
	EM_LOCAL_PLAYBACK_FLAG_MODE = 102,  // Video playback and video query policy flag bit0 = = 1 picture in picture not supported
	EM_LOCAL_DISCONNECT_SIGNAL = 103, /// Set the mode for triggering a disconnection signal 0 - Not enabled; 1 - Enabled
} EM_LOCAL_MODE;

///@brief Set up some special local optimization modes
