///@brief ACS Caps
typedef struct tagNET_AC_CAPS
{
    int                     nChannels;                                  // max channel number
    BOOL					bSupAccessControlAlarmRecord;               // support alarm record in accesscontrolrec
    int                     nCustomPasswordEncryption;		            // password encryption mode of AccessControlCustomPassword,0:Plaintext, 1:MD5
    int                 	nSupportFingerPrint;			            // Whether to support information,0:unknown,1:unsupport, 2:support
    BOOL                    bHasCardAuth;                               // Whether to support card auth
    BOOL                    bHasFaceAuth;                               // Whether to support target auth
    BOOL                    bOnlySingleDoorAuth;	                    // Only Single Door authorize
    BOOL					bAsynAuth;                                  // asynchronous return of authorize  
    BOOL                    bUserlsoLate;                               // is support to user isolate
    int                     nMaxInsertRate;                             // max insert rate
    NET_SPECIAL_DAYS_SCHEDULE_CAPS  stuSpecialDaysSchedule;			    // specail day caps 
    int                     nUnlockModes;                               // unlock mode number
    EM_AC_UNLOCK_MODE		emUnlockModes[128];							// unlock modes
	EM_SUPPORT_HELMET_TYPE	emSupportHelmetType;						// Support safety helmet function
	UINT					nUserNameMaxLen;							// Support for name length limits
	BOOL					bSupportASGManager;							// Support the gate service component (the gate was hung on the access control device as a sub-device, and the related configuration of the gate is written in the access control. Now the gate business is divided from the access control business.)
	BOOL					bHasIrisAuth;								// Whether it supports target recognition authentication
	BOOL					bSupportDoorMultiSection;			// Whether it supports door multisection
	BOOL					bSupportCollectUserInfo;					// Whether it support collecting user information
	BOOL					bSupportTimeScheduleDB;						/// Does it support time planning database solutions
	BOOL					bSupportOutDoorMethodSetting;				/// Does it support configuration of the exit method (if supported, it can be configured separately from the entry method)
	BOOL					bHasHandPrintAuth;							/// Does it support palm print (vein) target recognition and authentication
	BYTE					byReserved[220];				            // reserved
}NET_AC_CAPS;

