///@brief RTMP Streaming operation type
typedef enum tagNET_EM_RTMP_MANAGER_OPER_TYPE
{
	NET_EM_RTMP_MANAGER_OPER_TYPE_GETCAPS,                 // Obtain RTMP streaming capability of the device, Corresponding structure pstInParam = NET_IN_RTMP_MANAGER_GETCAPS, pstOutParam = NET_OUT_RTMP_MANAGER_GETCAPS
	NET_EM_RTMP_MANAGER_OPER_TYPE_ADD,                     // Add streaming address, Corresponding structure pstInParam = NET_IN_RTMP_MANAGER_ADD, pstOutParam = NET_OUT_RTMP_MANAGER_ADD
	NET_EM_RTMP_MANAGER_OPER_TYPE_REMOVE,                  // Remove streaming address, Corresponding structure pstInParam = NET_IN_RTMP_MANAGER_REMOVE, pstOutParam = NET_OUT_RTMP_MANAGER_REMOVE
	NET_EM_RTMP_MANAGER_OPER_TYPE_START,                   // Start streaming, Corresponding structure pstInParam = NET_IN_RTMP_MANAGER_START, pstOutParam = NET_OUT_RTMP_MANAGER_START
	NET_EM_RTMP_MANAGER_OPER_TYPE_STOP,                    // Stop streaming, Corresponding structure pstInParam = NET_IN_RTMP_MANAGER_STOP, pstOutParam = NET_OUT_RTMP_MANAGER_STOP
	NET_EM_RTMP_MANAGER_OPER_TYPE_PAUSE,                   // Pause streaming, which is only valid for playback streams, Corresponding structure pstInparam = NET_IN_RTMP_MANAGER_PAUSE, pstOutParam = NET_OUT_RTMP_MANAGER_PAUSE
	NET_EM_RTMP_MANAGER_OPER_TYPE_RESUME,                  // Resume streaming, which is only valid for playback streams, Corresponding structure pstInparam = NET_IN_RTMP_MANAGER_RESUME, pstOutParam = NET_OUT_RTMP_MANAGER_RESUME
	NET_EM_RTMP_MANAGER_OPER_TYPE_SET_SPEED,               // Set the double speed push stream, which is only valid for playback stream, Corresponding structure pstInparam = NET_IN_RTMP_MANAGER_SET_SPEED, pstOutParam = NET_OUT_RTMP_MANAGER_SET_SPEED
}NET_EM_RTMP_MANAGER_OPER_TYPE;

