///@brief User Info extension 
typedef struct tagNET_ACCESS_USER_INFO_EX
{
	char						szConsumptionTimeSections[42][34];	// Consumption TimeSections
																	// every day has six TimeSections
																	// the TimeSection format is: "DayNo hour:minute:second-hour:minute:second type times amount"
																	// DayNo starts with 0, 0 means Sunday, the DayNo of the the first six TimeSections is 0
																	// type is the Consumption type, 0 means quota, 1 means nonquota
																	// times is the Consumable times, the max is 200
																	// amount is the Consumable amount, the max is 999900 cents
	BYTE                        byReserved[1024];					// Reserved
}NET_ACCESS_USER_INFO_EX;

///@brief Multi timesection information
typedef struct tagNET_MULTI_TIMESECTION_INFO
{
	int										nDoor;													// Door
	int										nTimeSectionNum;								// Number of indexes in the corresponding time period of door permissions
	UINT										nTimeSectionList[128];							// Index of corresponding time period of door authority
	UINT										nSpecialDaysScheduleList[128];				// Special days schedule list
	int										nSpecialDaysScheduleNum;					// Number of Special days schedule
	char									    szReserved[508];		// Reserved
}NET_MULTI_TIMESECTION_INFO;

