///@brief error code
typedef enum tagNET_EM_FAILCODE
{
    NET_EM_FAILCODE_NOERROR,                                                // no error
    NET_EM_FAILCODE_UNKNOWN,                                                // unknown
    NET_EM_FAILCODE_INVALID_PARAM,                                          // invalid param
    NET_EM_FAILCODE_INVALID_PASSWORD,                                       // invalid password
    NET_EM_FAILCODE_INVALID_FP,                                             // invalid fingprint
    NET_EM_FAILCODE_INVALID_FACE,                                           // invalid date
    NET_EM_FAILCODE_INVALID_CARD,                                           // invalid card date
    NET_EM_FAILCODE_INVALID_USER,                                           // invalid user date
    NET_EM_FAILCODE_FAILED_GET_SUBSERVICE,                                  // get sub services failed
    NET_EM_FAILCODE_FAILED_GET_METHOD,                                      // get method failed
    NET_EM_FAILCODE_FAILED_GET_SUBCAPS,                                     // get subcaps failed
	NET_EM_FAILCODE_ERROR_INSERT_LIMIT,                                     // insert limit 
    NET_EM_FAILCODE_ERROR_MAX_INSERT_RATE,                                  // max insert rate
	NET_EM_FAILCODE_FAILED_ERASE_FP,										// erase fingprint date failed
	NET_EM_FAILCODE_FAILED_ERASE_FACE,										// erase datefailed
	NET_EM_FAILCODE_FAILED_ERASE_CARD,										// erase card date failed
	NET_EM_FAILCODE_NO_RECORD,												// no record 
	NET_EM_FAILCODE_NOMORE_RECORD,											// no more record
	NET_EM_FAILCODE_RECORD_ALREADY_EXISTS,									// record already
	NET_EM_FAILCODE_MAX_FP_PERUSER,											// max fingprint per user
	NET_EM_FAILCODE_MAX_CARD_PERUSER,										// max card per user
	NET_EM_FAILCODE_EXCEED_MAX_PHOTOSIZE,									// exceed max picture size
	NET_EM_FAILCODE_INVALID_USERID,											// invalid user id(not found user)
	NET_EM_FAILCODE_EXTRACTFEATURE_FAIL,									// extract feature fail
	NET_EM_FAILCODE_PHOTO_EXIST,											// photo already exist
	NET_EM_FAILCODE_PHOTO_OVERFLOW,											// exceed max photos
	NET_EM_FAILCODE_INVALID_PHOTO_FORMAT,									// invalid photo format
	NET_EM_FAILCODE_EXCEED_ADMINISTRATOR_LIMIT,								// exceed administrator limit
	NET_EM_FAILECODE_FACE_FEATURE_ALREADY_EXIST,							// Facial features already exist
	NET_EM_FAILECODE_FINGERPRINT_EXIST,										// Fingprint already exist
	NET_EM_FAILECODE_CITIZENID_EXIST,										// card ID already exist
	NET_EM_FAILECODE_NORMAL_USER_NOTSUPPORT,								// Ordinary users do not support delivery
	NET_EM_FAILCODE_NO_FACE_DETECTED,										// 0 targets detected in the picture
	NET_EM_FAILCODE_MULTI_FACE_DETECTED,									// Multiple are detected in the picture, and features cannot be returned
	NET_EM_FAILCODE_PICTURE_DECODING_ERROR,									// Picture decoding error
	NET_EM_FAILCODE_LOW_PICTURE_QUALITY,									// Picture quality is too low
	NET_EM_FAILCODE_NOT_RECOMMENDED,										// The result is not recommended, for example: for foreigners, the feature extraction is successful, but the algorithm support is not good, and it is easy to cause misidentification
	NET_EM_FAILCODE_FACE_ANGLE_OVER_THRESHOLDS,								// The angle exceeds the configured threshold
	NET_EM_FAILCODE_FACE_RADIO_EXCEEDS_RANGE,								// The proportion of the target is out of range, the algorithm recommends the proportion: no more than 2/3; no less than 1/3
	NET_EM_FAILCODE_FACE_OVER_EXPOSED,										// Overburdened
	NET_EM_FAILCODE_FACE_UNDER_EXPOSED,										// undershot
	NET_EM_FAILCODE_BRIGHTNESS_IMBALANCE,									// Unbalanced brightness, used to judge yin and yang faces
	NET_EM_FAILCODE_FACE_LOWER_CONFIDENCE,									// Facial confidence is low
	NET_EM_FAILCODE_FACE_LOW_ALIGN,											// Low alignment score
	NET_EM_FAILCODE_FRAGMENTARY_FACE_DETECTED,								// The target is blocked or incomplete
	NET_EM_FAILCODE_PUPIL_DISTANCE_NOT_ENOUGH,								// target pupil distance is less than the threshold
	NET_EM_FAILCODE_FACE_DATA_DOWNLOAD_FAILED,								// target data download failed
	NET_EM_FAILCODE_FACE_FFE_FAILED,										// The can be detected, but the feature value extraction fails (algorithm scene)
	NET_EM_FAILCODE_PHOTO_FEATURE_FAILED_FOR_FA,							// The feature value extracted from the photo is incorrect due to the inconsistency of attributes such as masks, hats, sunglasses, etc.
	NET_EM_FAILCODE_FACE_DATA_PHOTO_INCOMPLETE,								// Incomplete photo
	NET_EM_FAILCODE_DATABASE_ERROR_INSERT_OVERFLOW,							// Database error insert overflow
	NET_EM_CARD_NOT_EXIST,													// Card not exist
	NET_EM_FAILCODE_USER_EXIST,												// User Already Exist
	NET_EM_FAILCODE_CARD_NUM_EXIST,											// Card Already Exist
	NET_EM_FAILCODE_FINGERPRINT_DOWNLOAD_FAIL,								// Information Download Fail
	NET_EM_FAILCODE_ACCOUNT_IN_USE,											// Account In Use
	NET_EM_FAILCODE_IRIS_INFO_NOT_EXISTED,									// Eyes Info Not Existed
	NET_EM_FAILCODE_INVALID_IRIS_DATA,										// Invalid Eyes Data
	NET_EM_FAILCODE_IRIS_ALREADY_EXIST,										// Eyes Info Already Exist
	NET_EM_FAILCODE_ERASE_IRIS_FAILED,										// Erase Eyes Info Failed
	NET_EM_FAILCODE_EXCEED_MAX_IRIS_GROUP_COUNT_PER_USER,					// Exceed Max Eyes Info Group Count Per User
	NET_EM_FAILCODE_EXCEED_MAX_IRIS_COUNT_PER_GROUP,						// Exceed Max Eyes Info Count Per Group
	NET_EM_FAILCODE_FEATURE_SIZE_ERROR,                                     // Eigenvalue length error
    NET_EM_FAILCODE_DOOR_IN_NORMALLY_OPEN_STATUS,                           // The door is in a normally open state
    NET_EM_FAILCODE_DOOR_IN_NORMALLY_CLOSED_STATUS,                         // The door is in a normally closed state
    NET_EM_FAILCODE_DOOR_IN_INTERLOCK_STATUS,                               // The door is in an interlocking state
    NET_EM_FAILCODE_DO_NOT_EDIT,                                      		// Data not allowed for editing
    NET_EM_FAILCODE_BINDING,                                          		// Data bound
}NET_EM_FAILCODE;

