///@brief single radar alarm point info
typedef struct tagNET_RADAR_ALARMPOINT_INFO
{
	EM_RADAR_POINTTYPE          emPointType;             // point type,the field is abandoned.please do not use, use nPointType
	int                         nPointType;              // point type
	//bit0:invalid
	//bit1:disappear track point
	//bit2:points being monitored by linkage
	//bit3:alarm point of alarm area
	int                         nRegionNumber;           // region number, range[0,10]([1,10] is defense area number,0 indicates that it does not belong to any defense area)
	EM_RADAR_OBJECTTYPE         emObjectType;            // radar object type
	int                         nTrackID;                // track ID, range[0,63]
	int                         nDistance;               // distance, the result of expand 100 times, unit:m
	int                         nAngle;                  // angle, the result of expand 100 times, unit:degree
	int                         nSpeed;                  // point speed, the result of expand 100 times, unit:s
	int                         nLongitude;              // Longitude, transmitted by integer, magnified by 1000000 times, 6 digits after the decimal point are valid, and less than 6 digits are filled with 0, for example, 120125400 represents 120.1254
	int                         nLatitude;               // Latitude, transmitted by integer, magnified by 1000000 times, 6 digits after the decimal point are valid, if less than 6 digits are filled with 0, for example, 120125400 represents 120.1254
    char                        szTrackerIP[16];         // The dome camera is tracking the target, 0 is an invalid value
	char						szTargetUUID[32];		// Alarm target unique ID
	int							nAlarmLevel;			// Alarm Level,0-6, -1:non-exist
	int							nSNR;					// SNR value (signal-to-noise ratio) of the target, in decibels (dB), magnified by a factor of 1000
	BYTE                        byReserved[448];         // Reserved
}NET_RADAR_ALARMPOINT_INFO;

