{
	int             nRuleID;                // Rule ID
	int             nPointNumber;           // Number of tracks in the rule
	UINT            nTrackerIP;             // The dome camera is tracking the target, 0 is an invalid value
	char            byReserved[60];         // Reserved
} NET_RADAR_RULE_INFO;

