///@brief CLIENT_RadarManualTrack input param
typedef struct tagNET_IN_RADAR_MANUAL_TRACK
{
	DWORD							dwSize;					// Structure size
	char							szSDIP[32];				// SD IP
	int								nTrackID;				// TrackID
	int								nTime;					// Time,unit:s
	int								nAction;				// Action, 0:stop, 1:start,2: Stop all tracking (including radar autonomous tracking, manual tracking and ball machine relay tracking)
	int                             arrCoordinate[2];       // Longitude and latitude coordinates,Integer transfer,1000000 times expansion,
	int								nAlarmType;				// The reason for manual tracking, bit0 indicates overspeed bit1 indicates whether AIS matches or not bit2 indicates whether it is prohibited or not bit3 indicates whether it is retrograde (bit bit 1 indicates manual tracking is required, all 0 indicates normal tracking command)	
	int 							nSpeed;					// Speed: the speed of the target to be tracked, and the unit km/h is increased by 10000 times and issued (accuracy 0.0001)
	int								nAzimuth;				// Azimuth: 0  in due north direction, 0-360  in clockwise direction, 100 times larger
	int                             nChannel;               /// Channel ID
} NET_IN_RADAR_MANUAL_TRACK;

///@brief CLIENT_RadarManualTrack output param
typedef struct tagNET_OUT_RADAR_MANUAL_TRACK
{
	DWORD							dwSize;					// Structure size
	char							szSDIP[32];				// Returns the dome camera ip corresponding to the tracked track
	int								nEventID;				// A globally unique id of the tracking target
	int                             szReserved[4];           /// byte alignment
	char                            szTargetUUID[32];        /// Unique id of linkage target; (also unique in multi-radar case) Bits 1-12 of the char array: is the MAC address of the device; Digits 13-23: Time; 23-28 bits: random number; Bits 29-32: indicates the target id, that is, the TrackID field
}NET_OUT_RADAR_MANUAL_TRACK;


