#define RADAR_TARGET_FILTER_CAR		0x02				 // Car
#define RADAR_TARGET_FILTER_ANIMAL	0x04				 // Animal

///@brief guard line
typedef struct tagNET_RADAR_RULELINE
{
	char                        szName[DH_COMMON_STRING_128];// guard name
	int                         nRegionNumber;               // region number,range[1,10]
	BOOL                        bEnable;                     // rule enable
	EM_RADAR_RULETYPE           emRuleType;                  // radar rule type
	DH_POINT		            stuPolygon[DH_MAX_POLYGON_NUM];	// polygon,Each of the points represents the guard line vertex coordinate
	int					        nPolygonPointNum;	         // return polygon point num,range[3, 24]
	int							nTargetFilter;				 // Target filtering bit1:Human, bit2:Car, bit3:Animal Config with|,Check with&
	int							nAlarmOutNumber;			 // Alarm output configuration association, correspond to nAlarmOutNumber in NET_RADAR_ANALYSERULE configuration 
	int                         nLongitudeNum;               // The number of longitudes, that is, the number of valid elements in the nLongitude array	
	int                         nLongitude[21];              // The longitude of the regular point, transmitted by integer, magnified by 1000000 times, 6 digits after the decimal point are valid, for example, 120125400 represents 120.1254
	int                         nLatitudeNum;                // The number of dimensions, that is, the number of valid elements in the nLatitude array
	int                         nLatitude[21];               // The dimension of the regular point, transmitted by integer, magnified by 1000000 times, 6 digits after the decimal point are valid, for example, 120125400 represents 120.1254
    int                         nRadarPolygonNum;            // Actual valid number of sector rule array in radar coordinate system
	int                         nRadarPolygon[20][2];        // Area rules in radar coordinate system. Radar normal is the polar axis, counterclockwise is the positive direction. Int [][0u] : distance unit: meter, 100 times larger; Int [][1u] : Unit of Angle: degree enlarged by 100 times
	BYTE                        byReserved[164];             // Reserved
}NET_RADAR_RULELINE;

