///@brief License plate matching mode
typedef struct tagNET_TRUST_PLATE_MATCH_PATTERN
{
	BOOL								bEnable;					         /// Whether to enable it
	int                                 nCareWordNum;                        /// Cares about the effective length of the character set array
	char                                szCareWord[32][32];                  /// Concerned character set. The length of the array indicates the length of the visible character of the license plate. The * element in the array indicates the concerned character in the allowlist query
																				/// Note: This field only identifies the location of concern, not the specific content of the location of concern, so the way to use this field is to set the concern field to "*", pay attention to the distinction with MatchingRules
	char                                szMatchingRules[8][128];             ///The array length indicates the character length of the license plate that supports detection. The specific elements and positions in the array indicate the rules that need to be met. The detected license plate matches the recognized license plate in the sequence from left to right.
																				/// Example: If the first digit is set to "Zhe" and the third digit is set to "DK147", the license plate with the first digit being "Zhe" and the third digit being "DK147" is identified as a allowlisted license plate
	int                                 nMatchingRulesNum;                   /// The valid length of the matched rule array
	char 								szReserved[1020];					 /// Reserve bytes
}NET_TRUST_PLATE_MATCH_PATTERN;

///@brief Indicates the equivalent character group of 
typedef struct tagNET_EQUAL_WORD_ARRAY
{
	char                                szEqualSrcWord[4];                   /// Equivalent source character, example :"D"->D is equivalent to XXX
	char                                szEqualDstWord[4];                   /// Equivalent destination character, for example, "O"->XXX is equivalent to O
	char 								szReserved[128];					 /// Reserve bytes
}NET_EQUAL_WORD_ARRAY;

///@brief License plate fuzzy matching
typedef struct tagNET_PLATE_VAGUE_MATCH
{
	BOOL								bEnable;					         /// Whether to enable it
	int                                 nReduceAtHead;                       /// The number of characters in the head of the license plate is reduced, and the reported head license plate is reduced by N characters for matching
	int                                 nReduceAtTail;                       /// The number of characters at the end of the license plate is reduced, and the reported tail license plate is reduced by N characters for matching
	int                                 nAddAtHead;                          /// The number of characters in the head of the license plate is increased, and N characters are added to the reported head license plate for matching
	int                                 nAddAtTail;                          /// The number of characters at the end of the license plate is reduced, and the reported tail license plate is increased by N characters for matching
	int                                 nErrorWordMode;                      /// The default value is 0, and the value is the allowed number of error characters. The reported license plate permit allows N visible character errors for database matching
	BOOL                                bProvErrorEnable;                    /// Whether to allow a province word error
	int                                 nEqualWordArryNum;                   /// Indicates the valid number of equivalent character groups
	NET_EQUAL_WORD_ARRAY                stuEqualWordArry[32];                /// Indicates the equivalent character group
	char 								szReserved[1020];					 /// Reserve bytes
}NET_PLATE_VAGUE_MATCH;

