///@brief Face beautification configuration
typedef struct tagNET_CFG_FACE_BEAUTIFICATION
{
	BOOL bEnable; /// Enable
	UINT nBeautyLevel; /// Noise reduction level, ranging from 0 to 100, default value is 50. Higher levels result in more noise reduction and better face beautification effects.
	UINT nModelType; /// 0: Manual, 1: Automatic, default is manual.
	UINT nEeLevel; /// Face edge sharpness parameter [0, 100], default value is 50.
	UINT nBlackEdge; /// Black edge suppression, ranging from 0 to 100, default value is 50. Higher values result in more visible black edges.
	UINT nWhiteEdge; /// White edge suppression, ranging from 0 to 100, default value is 50. Higher values result in more visible white edges.
	UINT nBrightness; /// Brightness level, ranging from 0 to 100, default value is 50. Higher values result in higher brightness.
	UINT nSaturation; /// Color level, ranging from 0 to 100, default value is 50. Higher values result in more vibrant colors.
	char							szReserved[128];							// Reserved
} NET_CFG_FACE_BEAUTIFICATION;

