///@brief  NET_FACE_QUALITY_CAPINFO of NET_FEATURE_ABSTRACT_RULE_INFO
typedef struct tagNET_FACE_QUALITY_CAPINFO
{
	int 					nFgeType;    	// 0:  Invalid.
											// 1:  Switch for filtering non-faces based on quality score, range 0 for off, 1 for on
											// 2:  Face quality score threshold, valid range [15, 100], recommended range [15, 60] 
											// 3:  Minimum face clarity threshold, valid range [0, 100], recommended range [50, 80] 
											// 4:  Minimum interpupillary distance threshold, valid range [>=0], recommended range [>20] 
											// 5:  unglasses detection switch, range 0 for off, 1 for on
											// 6:  Mask detection switch, range 0 for masks not allowed, 1 for masks allowed
											// 7:  Maximum face pitch angle threshold, valid range [0, 90], recommended range [20, 40]
											// 8:  Maximum face yaw angle threshold, valid range [0, 90], recommended range [20, 40]
											// 9:  Maximum face roll angle threshold, valid range [0, 90], recommended range [20, 40]
											// 10: Eye occlusion switch, range 0 for off, 1 for on
											// 11: Mouth  occlusion switch, range 0 for off, 1 for on
											// 12: Hat detection switch, range 0 for off, 1 for on
											// 13: Forehead occlusion switch, range 0 for off, 1 for on
											// 14: Minimum face width to image width ratio threshold, valid range [0, 50]%, recommended range [30, 50]%
											// 15: Maximum face width to image width ratio threshold, valid range [51, 100]%, recommended range [60, 80]%
											// 16: Minimum face height to image height ratio threshold, valid range [0, 50]%, recommended range [30, 50]%
											// 17: Maximum face height to image height ratio threshold, valid range [51, 100]%, recommended range [60, 80]%
											// 18: Face completeness switch, range 0 for off, 1 for on
											// 19: Face illumination score threshold, valid range [0, 100], recommended range [30, 40]
											// 20: Face alignment score threshold, valid range [0, 100], recommended range [35, 100]
	int 					nValue;			// the value of nFgeType
	char  					szReserved[128];// reserved
}NET_FACE_QUALITY_CAPINFO;

