///@brief info of analyse task
typedef struct tagNET_ANALYSE_TASKS_INFO
{
    UINT                            nTaskID;                                // task ID
    EM_ANALYSE_STATE                emAnalyseState;                         // analyse state
    EM_ANALYSE_TASK_ERROR           emErrorCode;                            // error code
    BYTE                            byReserved1[4];                        	// byte alignment
    char                            szTaskUserData[256];                    // task user date
    int								nVideoAnalysisProcess;					// Video analysis progress, is is valid when task add interface CLIENT_AddAnalyseTask's parameter emDataSourceType is "EM_DATA_SOURCE_REMOTE_PICTURE_FILE", the valid range is 1 ~ 100100, indicating that the analysis is completed
	char							szUrl[256];								// RTSP address of intelligent stream, which can be filled in only when real-time flow
	EM_SCENE_CLASS_TYPE				emClassType;							// Class type
	EM_DATA_SOURCE_TYPE				emSourceType;							// Source type
	int								nChipId;								// The analysis sub card ID used by the task. - 1 represents the invalid sub card, and a value greater than or equal to 0 represents the sub card ID number
																			// This field is valid when the emErrorCode is EM_ANALYSE_TASK_ERROR_ANALYZER_OFF_LINE or EM_ANALYSE_TASK_ERROR_ANALYZER_ON_LINE
	UINT                            nFilesNum;                              // Number of valid uploaded file lists. The maximum value is 32
    NET_EMERGENCY_FILE_INFO*        pstuFiles;                              // List of uploaded files, memory to be released by SDK application
	BYTE                            byReserved[424 - POINTERSIZE];          // reserved bytes
} NET_ANALYSE_TASKS_INFO;

