typedef enum tagEM_FAILED_CODE
{
    EM_FAILED_CODE_UNKNOWN=-1,                                 // unknown
    EM_FAILED_CODE_NO_ERROR,                                   // error-free
    EM_FAILED_CODE_FAILED_TO_DOWNLOAD_THE_MODEL,               // Model download failure
    EM_FAILED_CODE_STORAGE_SPACE_IS_INSUFFICIENT,              // Insufficient storage space
    EM_FAILED_CODE_FILE_IS_TOO_LARGE,                          // File too large
    EM_FAILED_CODE_MODEL_PACKET_HEADER_ANALYSIS_FAILS,         // Model header resolution failed
    EM_FAILED_CODE_MODEL_FORMAT_VERIFICATION_ERROR,            // Model format validation error
    EM_FAILED_CODE_HARDWARE_PLATFORM_VERIFICATION_FAILS,       // The hardware platform verification fails
    EM_FAILED_CODE_DEVICE_DOES_NOT_SUPPORT_MODEL_DELIVERY,     // The device does not support model delivery
    EM_FAILED_CODE_CURRENT_DEVICE_MODE_IS_NOT_SUPPORTED,       // The current device mode is not supported
    EM_FAILED_CODE_MODEL_NAME_ALREADY_EXISTS,                  // The model name already exists
    EM_FAILED_CODE_EXCEEDS_THE_UPPER_LIMIT,                    // The number of algorithms exceeds the upper limit. Procedure
    EM_FAILED_CODE_OTHER_ERRORS,                               // Other errors
}EM_FAILED_CODE;

