///@brief Input param of CLIENT_SearchFeatureDB
typedef struct tagNET_IN_SEARCH_FEATUREDB
{
	DWORD 									dwSize;                     // Struct size 
	NET_SEARCH_FEATUREDB_RETRIEVAL_MESSAGES	stuRetrievalMessages[32];	// Feature retrieval information
	int										nRetrievalMessagesNum;		// Number of stuRetrievalMessages
	int										nThreshold;					// Threshold, [0,100], default value is 80
	char									szRepositoryID[2048][64];	// Repository ID
	int										nRepositoryIDNum;			// NUmber of repository ID
	BYTE									bReserved1[4];				// Byte alignment
	UINT									nStartTime;					// Only when the eigenvalue corresponds to the snapshot start time of the image, can the snapshot library be valid. (if the eigenvalue is not written and the value is - 1, it means that it is empty.)
	UINT									nEndTime;					// The capture library is valid only when the characteristic value corresponds to the capture end time of the image. (if it is not written and the value is - 1, it means it is empty)
	int										nTopN;						// Totoal numbet of resluts(max 1000), deault value is 500
	int										nObjectSubType;				// Sub type of object, 1:target 2:human 4:vehicle 8:Nonmotor
	EM_SEARCH_FEATUREDB_MULTIMERGE_RESULT	emMultiMergeResult;			// Type of search by picture
}NET_IN_SEARCH_FEATUREDB;

