typedef struct tagNET_SEARCH_FEATUREDB_RETRIEVAL_SINGLE_RESULT
{
	char									szFeatureID[64];				// Feature ID
	char									szRepositoryID[64];				// Repository ID
	int										nSimilarity;					// Similarity, [0,100]
	int										nCapTime;						// Only when the eigenvalue corresponds to the capture time of the image, can the capture library be valid. (if it is not written and the value is - 1, it means it is empty)
	BYTE									bReserved[512];					// Reserved
}NET_SEARCH_FEATUREDB_RETRIEVAL_SINGLE_RESULT;

