///@brief Rule information expansion
typedef struct tagNET_RULE_TYPES_EXTEND
{
	int								nSubTypeNum;						/// Number of rule subtypes
	char							szSubType[32][32];					/// Subtype of Rules
    int                             nAnalysisTypeNum;                   /// Analysis Type Num
    int                             nAnalysisType[32];                  /// Analysis Type, 0: General AI Analysis,1: Second Evaluation (Standard Mode), 2: Second Evaluation (Fine-Tuning Mode)
	char							szReserved[120];					/// Reserved
}NET_RULE_TYPES_EXTEND;

///@brief Capability-supported intelligence analysis rule information
typedef struct tagNET_ANALYSE_RULE_CAPS_EX
{
	int								nRuleMaxNumCount;					/// Number of RuleMaxNum valid
	int								nSupportISDCount;					/// Number of SupportISD valid
	int								nRuleMaxNum[32];					/// Corresponding to the Type subscript, indicates the maximum number of sends corresponding to the same rule, and -1 indicates no restriction
	BOOL							bSupportISD[32];					/// Corresponding to the Type subscript, it indicates whether the corresponding rule supports ISD configuration resolution
	char							szAlgorithmLibVersion[128];			/// Analyze the algorithm version number corresponding to the major class
	int								nTotalRuleMaxNum;					/// An analysis of the maximum number of rules supporting send in a large class, where -1 means no restriction
	int								nMaxRuleTypesExtendNum;				/// Number of rule information extensions
	NET_RULE_TYPES_EXTEND*			pstuRuleTypesExtend;				/// Rule information expansion, memory is released by user request, The size is sizeof(NET_RULE_TYPES_EXTEND)*nMaxRuleTypesExtendNum
	int								nRetRuleTypesExtendNum;				/// Number of actual returns from rule information expansion
    char							szReserved[1004];					/// Reserved
} NET_ANALYSE_RULE_CAPS_EX;

