///@brief Input param of CLIENT_SetDevWifiInfo
typedef struct tagNET_IN_SET_DEV_WIFI
{
    DWORD               dwSize;                     // Struct size
    UINT                nPort;                      // Dev port
    char                szDevIP[64];                // Dev IP
    int                 nEnable;                    // Is enable, 0: yes, 1: not
    char                szSSID[36];                 // SSID
    int                 nLinkMode;                  // Link mode:0:auto,1:adhoc,2:Infrastructure
    int                 nEncryption;                // Encryption,0:off,2:WEP64bit,3:WEP128bit, 4:WPA-PSK-TKIP, 5: WPA-PSK-CCMP(AES), 6:WPA2-PSK-TKIP 7:WPA2-PSK-AES 8:WPA-TKIP 9:WPA-AES 
                                                    // 10:WPA2-TKIP 11:WPA2-AES 12:AUTO 13:WEP-OPEN 14:WEP-SHARED  15:WPA3-SAE-CCMP; 16:WPA3-SAE/PSK-CCMP
    int                 nKeyType;                   // 0:Hex,1:ASCII
    int                 nKeyID;                     // Key ID
    char                szKeys[4][32];              // Keys, it is effect when nEncryption is not about WPA
    char                szWPAKeys[128];             // WPA key, it is effect when nEncryption is about WPA; The length is 128, and it is not need '\0'
    int                 nKeyFlag;                  // Key flag
    int                 nConnectedFlag;            // Connect flag 0: no connect, 1: connect
	char                szMacAddr[18];              // Device MAC address
} NET_IN_SET_DEV_WIFI;

