///@brief Query conditions for input parameters of CLIENT_GetWorkDirectoryBitmapEx interface
typedef struct tagNET_WORK_DIRECTORY_BITMAPEX_CONDITION
{
	int									nYear;							 // year
	int									nMonth;							 // month
	int									nChannel;						 // channel number, the channel starts from 0, -1 means all channels
	int									nFileTypeNums;					 // The number of file type lists, the maximum value is 32, and the minimum value is 0. If the value is 0: the field value of the file type list to be delivered is null (null means query any type)
	EM_WORK_DIRECTORY_FILE_TYPE			emFileTypes[32];				 // File type list, which is an array, multiple file types can be queried at one time, currently only "dav", "jpg" are supported
	BOOL								bIsSupportEventTypes;			 // Enable the event type list field delivery, TRUE: means the event type list emEventTypes is valid and delivered, FALSE: means the event type list emEventTypes is invalid and not delivered (the event type list field does not exist, means query all events) 
	int									nEventTypeNums;				     // The number of event type lists, the maximum value is 256, and the minimum value is 0. If the value is 0: the field value of the issued event type list is null (null means query all events)
	EM_WORK_DIRECTORY_EVENT_TYPE        emEventTypes[256];				 // Event type list, currently only supports implementation: "AlarmLocal","VideoMotion","FaceDetection"
	char					            szReserved[256];			     // reserved bytes
} NET_WORK_DIRECTORY_BITMAPEX_CONDITION;

