	NET_BACKUP_SOURCE*			pstuSource;		//  Backup source, user allocated memory, sizeof(NET_BACKUP_SOURCE)*nSourceNum	
	NET_BACKUP_TARGET*			pstuTarget;		//  For backup purposes, the user allocates memory, the size is sizeof(NET_BACKUP_TARGET)*nTargetNum
	int							nTargetNum;		//  Number of backup destinations
	EM_BACKUP_FORMAT			emFormat;		//	The format type that the backup is expected to become
	unsigned int				nGroupID;		//  task group ID
