///@brief  Main board configuration of turnstile
typedef struct tagNET_MAIN_BOARD_CONFIG
{
	UINT					nVoiceListNum;							// Number of common voice lists
	NET_VOICE_LIST			stuVoiceList[16];						// voice lists
	EM_NET_PASS_MODE		emPassMode;								// Traffic mode
	UINT                    nOpenDoorSpeed;                     	// Opening speed gear, range :0-11, corresponding to 1-12 gear
	UINT                    nPassTimeOut;                       	// Pass timeout time, range: 2-60, unit: second
	UINT                    nCloseDelayTime;                    	// Delayed door-closing time, unit: second, range (0-60), that is, after pedestrians pass, the door will be closed after a specified time delay.
	UINT                    nSecurityLevel;                     	// Gate security level, range: 0-4, corresponding to level 1-5
	BOOL                    bSecondOpenEnable;                  	// Turn on the function switch twice; False: off, True: on
	UINT					nSecondOpenTimeSec;						// The second opening time period value, that is, the array index of AccessTimeSchedule
	BOOL                    bMemoryModeEnable;                  	// Memory function switch; False: off, True: on
	UINT                    nVolumeLevel;                       	// There are 8 levels of device volume level, range: 0-7, level 0 means mute
	EM_NET_DIRECTION_AFTER_POWER_OFF    emDirectionAfterPowerOff;	// After the gate is powered off, the door swings and moves towards
	EM_NET_ASG_WORK_MODE    emWorkMode;                         	//  Work Mode
	UINT					nWorkModeTimeSec;						// Working mode time period value, that is, the array index of AccessTimeSchedule
	EM_NET_STARTUP_MODE     emStartUpMode;                      	// StartUp Mode
	int                     nMasterWingAngleAdjust;             	// The zero position fine adjustment angle of the side door wing of the main engine, the value range is -100 ~ 100, unit: 0.1 degree, which can be adjusted from -10 degree to 10 degree
	int                     nSlaveWingAngleAdjust;              	// From the machine side door wing zero position fine-tuning angle, the value range, -100 ~ 100, unit: 0.1 degree, you can adjust -10 degrees ~ 10 degrees
	EM_NET_GATE_TYPE        emGateType;                         	// Gate type
	EM_NET_CHANNEL_WIDTH    emChannelWidth;                     	// Channel width
	UINT					nGateMaterial;							// Material of gate wing 0: Stainless steel 1: Acrylic 2: Glass
	UINT					nMemoryModeTimeSec;						// Memory mode time period value
	UINT					nChannelHeight;						     /// Gate height, the value ranges from 0 to 3, corresponding to 725,900,1200, and 1800 height channels respectively
	UINT                    nMaxDoorSpeed;                     	     /// Maximum gear of brake execution speed, range :0-11, corresponding to 1-12 gear
	UINT                    nCloseDoorSpeed;                     	 /// Door speed gear, range :0-11, corresponding to 1-12
	UINT                    nFreeOpenIrLogic;                     	 /// Open door mode Infrared logic, 0: logic or,1: logic and
	UINT                    nMaxConfigSafeLv;                     	 /// Maximum safety level of the brake. The value ranges from 0 to 4, corresponding to 1-5 safety levels respectively
    UINT                    nWaitInTime;                            // WaitIn Time, range:3~10 s
    UINT                    nInfraRedDetectDelay;                   // Infra RedDetect Delay:0,3,5
    UINT                    nOpenRetractAngle;                      // Open Retract Angle,range 1~6
    UINT                    nCollisionLevel;                        // Collision Level, 0:low 1:Medium 2:high
    UINT                    nMechanicalLevel;                       // Mechanical Level, 0:low 1:Medium 2:high
    UINT                    nVoiceSwitch;                           // Voice Switch, 0:close 1:open
    UINT                    nColumnLightEnable;                     // ColumnLight Enable, 0:close 1:open
    UINT                    nMovementLightEnable;                   // Movement Light Enable, 0:close 1:open
    UINT                    nDoorLightEnable;                       // Door Light Enable, 0:close 1:open
    UINT                    nFlowLightEnable;                       // Flow Light Enable, 0:close 1:open
	char					szReserved[956];						/// reserved
}NET_MAIN_BOARD_CONFIG;

