///@brief Tailbox access result
typedef struct tagNET_TRUNK_ACCESS_INFO
{
	int									nType;						// operation type, 0-box, 1-box
	int									nCabinIndex;				// cabin number
	char								szAccessorID[64];			// Accessor ID
	char								szAccessorName[64];			// Accessor Name
	char								szReviewerID[64];			// Reviewer ID
	char								szReviewerName[64];			// Reviewer Name
	char								szApproverID[64];			// Approver ID
	char								szApproverName[64];			// Approver Name
	int									nResult;					// access result, 0-access process is completed, 1-access process is not completed confirmation, 2-approval timeout, 3-approval rejected
	char								byResvered[4];				// only for bytes, meaningless
	char								szTime[32];					// record time, the format is: "YYYY-MM-DD hh:mm:ss"
	char								szAccessorSnap[128];		// Accessor authentication passes the snapshot storage path, which can be used for image download
	char								szReviewerSnap[128];		// The reviewer authenticates through the snapshot storage path, which can be used for image download
	char								szConfirmSnap[128];			// The snapshot storage path when the information is confirmed after access, which can be used for image download
	char								szRFIDNo[128];				// Accessed tail box RFID number
	char								szResvered[1024];			// reserved
}NET_TRUNK_ACCESS_INFO;

