	UINT	nSecurityLevel;		// Security level value

	UINT	nSensitivity[32];	// Sensitivity value of each zone
								// In 6 partitions: the effective data length is 6, and the array subscript 0~5 indicates the sensitivity of zone 1~6
								// In 12 partitions or 18 partitions 33partitions: the effective data length is 12, the array subscript 0~5 indicates the sensitivity of the left 1~left 6 zone, and the array subscript 6~11 indicates the sensitivity of the right 1~right 6 zone
	
	int		nSensitivityNum;	// The number of sensitivity values that are valid for each partition

	EM_RATE_TYPE				emRateType;				// Ratio
	EM_EXCLUDE_SMALL_METAL		emExcludeSmallMetal;	// Exclude small metal locations
	char						byReserved[256];		// reserved
