typedef struct tagNET_EAS_ENV_MONITOR_DATA_INFO
{
	int                     nDataNum;                    // The size of the returned environment array containing the following fields: nSignal, nNoise, nSnr, nAmp, nRms, nStd. The actual size values of the above field arrays are always the same
	UINT                    nSignal[256];                // Tag signal real time value, element size 0~4096
	UINT                    nNoise[256];                 // Ambient noise real time value, element size 0~4096
	UINT                    nSnr[256];                   // The SNR is a real-time value with an element size ranging from 0 to 65535
	UINT                    nAmp[256];                   // Amplitude Real time value. The element size ranges from 0 to 65535
	UINT                    nRms[256];                   // Validity is a real time value with an element size ranging from 0 to 65535
	UINT                    nStd[256];                   // Real time value of dispersion. The element size ranges from 0 to 65535
	UINT					nChannelSignal[256];		/// Real time value of channel phase signal, element size 0~65535
	UINT					nChannelWindowsSignal;		/// Channel signal window strength
	UINT					nChannelWindowsNoise;		/// Channel signal noise window intensity
	UINT					nChannelCount;				/// Channel alarm frequency, 0~10000
	char 					szResvered[256];	         // Keep the bytes
}NET_EAS_ENV_MONITOR_DATA_INFO;

