///@brief Terminal information for participating in the conference
typedef struct tagNET_VIDEO_MCU_MEMBER_INFO
{
	char                                    szTerminalId[16];                       // Terminal ID
	char                                    szName[128];                            // Terminal name
	BOOL                                    bAppeared;                              // Whether to attend the meeting
	BOOL                                    bCreator;                               // Is the meeting creator
	BOOL                                    bChairman;                              // Chairman of the meeting
	BOOL                                    bPresented;                             // Open demo
	BOOL                                    bMicOpen;                               // Whether to open wheat
	char                                    szReserved[1020];                       // Reserved byte
}NET_VIDEO_MCU_MEMBER_INFO;

///@brief Conference information
typedef struct tagNET_VIDEO_MCU_CONFERENCE_INFO
{
	char                                    szId[16];                               // Conference ID, unique identifier of the conference, randomly generated, cannot be modified
	char                                    szName[128];                            // Conference name
	char                                    szPassword[128];                        // Conference plaintext password
	char                                    szType[32];                             // Meeting type, "Instant": instant meeting, "Bespeak": appointment meeting
	char                                    szState[32];                            // Conference status, "Unstart": not started, "Meeting": in the conference, "Finished": ended
	NET_TIME_EX                             stuStartTime;                           // Meeting start time
	NET_TIME_EX                             stuEndTime;                             // Meeting end time
	NET_VIDEO_MCU_MEMBER_INFO               stuMember[32];                          // Terminal information for participating in the conference
	int                                     nMemberNum;                             // Number of terminal information participating in the conference
	UINT                                    nTime;                                  // Actual duration of the meeting, in seconds
	char                                    szCreatorId[16];                        // Conference creator ID, terminal ID will be transferred when the terminal is created, and "MCU" will be transferred when MCU is created
	char                                    szCreatorName[128];                     // The name of the meeting creator, the name of the terminal will be transmitted when the terminal is created, and the "MCU" will be transmitted when the MCU is created
	char                                    szReserved[1024];                       // Reserved byte
}NET_VIDEO_MCU_CONFERENCE_INFO;

