///@brief Query criteria
typedef struct tagNET_CLUSTER_DETAIL_CONDITION
{
	int                                 nClusterDate;                    // Clustering period Key: Only data within one clustering period can be queried at a time. This parameter is mandatory. Take the intersection with the start and end time
	BOOL                                bIsNeedProfileID;                // Whether to filter ProfileID
	int                                 nProfileID;                      // Clustering result ID. If this field is not contained or is empty, ProfileID is not filtered by default
    int                                 nBatchID;                     // Batch result ID, if this field is -1, the BatchID is not filtered by default
	int								 nStaffType;					//  Staff filtering criteria, -1: return all 0: only return non staff 1: only return staff
	int								 nAreadID;					//  The region filter condition -1 is considered as fully returned. When greater than or equal to 0, filter data reporting based on the current regional configuration. There is overlap in records within the region, so a single query is only supported for a single region.
	int									nChannel;						/// Video channel number, -1 represents querying all channels
	int									nPtzPresetId;					/// Pre set point number
	int									nAreaIDExCount;					/// Number of Area IDs
	int									nAreaIDEx[20];					/// Area ID
	BOOL								bRealUTC;						/// Is standard UTC time used
	NET_TIME							stuStartRealUTC;				/// Query start time, standard UTC time
	NET_TIME							stuEndRealUTC;					/// Query end time, standard UTC time
	BOOL								bUTC;							/// Whether to use UTC events with time zone deviation
	NET_TIME							stuStartUTC;					/// Query start time, UTC time with time zone deviation
	NET_TIME							stuEndUTC;						/// Query end time, UTC time with time zone deviation
	char								szReserved[48];					// Reserve bytes
}NET_CLUSTER_DETAIL_CONDITION;

