typedef struct tagNET_IN_GET_CLUSTER_STATE_INFO
{
	DWORD								dwSize;								 // The size of this structure must be assigned
	int									nClusterDate;						 // This parameter is optional. If this field is included, the cluster status of the corresponding date is queried. Otherwise, the latest cluster status is returned
}NET_IN_GET_CLUSTER_STATE_INFO;

///@brief Indicates the output parameters of the CLIENT_GetClusterState interface
typedef struct tagNET_OUT_GET_CLUSTER_STATE_INFO
{
	DWORD								dwSize;								 // The size of this structure must be assigned
	int                                 nClusterState;                       // Current clustering status 1. Completed. 2. In progress. 3. Clustering failed
	NET_TIME_EX                         stuDealTime;                         // Record the update time. The local time prevails
	int                                 nClusterData;                        // The cluster trigger time is recorded according to the year, month and day. As the unique key of the cluster, a single device has only one cluster record per day. For example, 20220530 indicates that the file has been collected on the day of 20220530
	int                                 nClusterType;                        // Last file gathering type: 1. Automatic daily file gathering 2. Manual file gathering 3 delivered by the platform. Manual test is triggered. 4. Clustering fails and try again
	int                             	nClusterMessage;                 	 // Gathering information, mainly used to display the cause of failure. For normal events, this field is blank or 0
    int                             	nRecordID;                       	 // Returns the record ID, which is theoretically unique for a single device and represents the same archive task
}NET_OUT_GET_CLUSTER_STATE_INFO;

