///@brief Traffic light scheme/variable lane scheme:
typedef enum tagEM_CTRL_SCHEME
{
	EM_CTRL_SCHEME_UNKNOWN,								// Unknown
	EM_CTRL_SCHEME_REDYELLOW_BACKUP = 150,				// Enter backup mode (traffic light)
	EM_CTRL_SCHEME_REDYELLOW_BACKUP_NORMAL_QUIT,		// Exit the backup mode normally (traffic light)
	EM_CTRL_SCHEME_REDYELLOW_BACKUP_ABNORMAL_QUIT,		// Abnormally exit the backup mode (traffic light)
	EM_CTRL_SCHEME_VARLANE_BACKUP,						// Enter backup mode (variable lanes)
	EM_CTRL_SCHEME_VARLANE_BACKUP_NORMAL_QUIT,			// Normally exit the backup mode (variable lanes)
	EM_CTRL_SCHEME_VARLANE_BACKUP_ABNORMAL_QUIT,		// Abnormal exit from backup mode (variable lanes)
}EM_CTRL_SCHEME;

///@brief CLIENT_SetRtscBackupMode Interface input parameters
typedef struct tagNET_IN_SET_BACKUP_MODE
{
	DWORD                       dwSize;                         // Structure size
	EM_CTRL_SCHEME				emCtrlScheme;					// Traffic light/variable lane plan: 150-152 represents traffic light and 153-155 represents variable lane plan:
} NET_IN_SET_BACKUP_MODE;

///@brief Backup mode setting error code
typedef enum tagEM_BACKUP_ERROR_CODE
{
	EM_BACKUP_ERROR_CODE_UNKNOWN = -1,							// UNKNOWN
	EM_BACKUP_ERROR_CODE_SUCCESS,								// Backup mode set success
	EM_BACKUP_ERROR_CODE_CYCLE_PLAN,							// The periodic schedule is wrong
	EM_BACKUP_ERROR_CODE_GREEN_LETTER,							// Green letter ratio table is wrong
	EM_BACKUP_ERROR_CODE_TIME_BASE_PLAN,						// The time base plan table is wrong
	EM_BACKUP_ERROR_CODE_DAY_PLAN,								// Incorrect daily schedule
	EM_BACKUP_ERROR_CODE_ACTION_PLAN,							// The action plan table is wrong
	EM_BACKUP_ERROR_CODE_PHASE_SEQUENCE,						// Incorrect phase sequence table
	EM_BACKUP_ERROR_CODE_CHANNEL_TABLE,							// The channel table is wrong
	EM_BACKUP_ERROR_CODE_FOLLOW_PHASE_TABLE,					// The following phase table is wrong
	EM_BACKUP_ERROR_CODE_PHASE_CONFLCT,							// Phase conflict
	EM_BACKUP_ERROR_CODE_DELIVERY_PLAN,							// Delivery plan timed out
	EM_BACKUP_ERROR_CODE_LANE_TABLE_SETTING,					// Lane table setting is wrong
	EM_BACKUP_ERROR_CODE_NOT_SUPPORT_SHORT_JUNCTIONS,			// Used for signal lights, indicating that the signal lights do not support short connection junctions
	EM_BACKUP_ERROR_CODE_CHANNEL_CONFIGURATION,					// Incorrect channel configuration. Used for signal lights. No U-turn arrow lights, straight non-motorized vehicle lights, left-turn non-motorized vehicle lights, bus lights-variable lanes
	EM_BACKUP_ERROR_CODE_VARIABLEE_LANE_TABLE,					// The variable lane plan table is incorrect
	EM_BACKUP_ERROR_CODE_WEEKLY_PLAN,							// The weekly plan is wrong
}EM_BACKUP_ERROR_CODE;

///@brief CLIENT_SetRtscBackupMode Interface output parameters
typedef struct tagNET_OUT_SET_BACKUP_MODE
{
	DWORD                       dwSize;                         // Structure size
	EM_BACKUP_ERROR_CODE		emBackUpErrCode;				// Backup mode setting error code
} NET_OUT_SET_BACKUP_MODE;

