///@brief Global parameter information
typedef struct tagGLOBAL_INFO
{
	EM_LIGHTGROUP_FAULT_LEVEL	emLightGroupFault;				// Lamp group failure level
	EM_COUNTDOWN_TYPE			emCountDownType;				// Countdown mode
	int							nPulseWidth;					// Pulse countdown pulse width (unit: ms)
	int							nPulseTime;						// Pulse countdown countdown time (unit: s)
	int							nBaudRault;						// 485 countdown baud rate INTEGER (2400 4800 9600 19200 38400)
	int							nGatType;						// 485 countdown usage protocol (0: GAT208-2004 1: GAT208-2014)
	int							nHalfTime;						// 485 halfway countdown time (in seconds)
	int							nDefaultRunModel;				// Unconfigured phase operation mode 1: All red 2: Turn off the light 3: Yellow flashing 4: Red flashing -1 not set
	int							nVarLaneCommunicationType;		// Variable lane communication mode selection 0: power supply type 1: communication type -1 not set
	int							nAutoProtectEnable;				// Automatic maintenance enable: 0-not enabled, 1-enabled -1 not set
	EM_AUTO_PROTECT_WEEK		emAutoProtectWeek;				// Automatic maintenance week
	int							nAutoProtectHour;				// Automatic maintenance hours
	int							nAutoProtectMinute;				// Automatic maintenance minutes
	int							nControlUnlockTime;				// Channel automatic unlocking time (0-65535)
	int							nFaultReport;					// Whether the fault is pushed (indicated by bit, set to 0 to turn on reporting, set to 1 to turn off reporting. bit0: lamp group failure bit1: detector failure bit2: green conflict failure bit3: peripheral board failure bit4:
	int							nRatedVoltage;					// Rated voltage value
	int							nPercentageValNum;				// Number of percentage values
	int							nPercentageVal[4];				// Percentage value; array[0]: Percentage 1 (shutdown voltage ratio) / array[1]: Percentage 2 (flashing start voltage ratio) / array[2]: Percentage 3
	int							nStartUpLampNum;				// Number of start-up lights
	int							nStartUpLamp[3];				// Start-up light color 1: red light 2: yellow light 4: red flash 5: yellow flash; array[n]: stage n light color, n <3
	int							nStartUpTimeNum;				// Number of boot time
	int							nStartUpTime[3];				// Start-up time array[n]: phase n time, n <3
	int                         nPlatformCtrl;                  // Temporary control issued by the platform: 1-Phase switching 2-phase dwell 3-phase lock 4-channel lock 5-restore  
	int                         nPlatformCtrlValNum;            // Number of control detailed values distributed by the platform
	int                         nPlatformCtrlVal[16];           // Detailed control values issued by the platform 
																// When Ctrl is equal to 3-phase phase locking, the array represents the set of phases to be locked, and each phase occupies two bytes. The low byte represents the phase number and the high byte represents the number of repetitions. For example, if the locked phases are A1 and B2, the content value is [1,1,2,2]
																// When Ctrl equals 4-channel locking, the array represents the set of channels to be locked, and the rest is 0
	BYTE						byReserved[952];				// Reserved byte
}GLOBAL_INFO;

