typedef struct tagNET_IN_GET_RUNNING_INFO
{
	DWORD                       dwSize;                         // Structure size
	UINT						nType;							// Query type, expressed in bits: bit0: running status bit1: control mode bit2: lane function status bit3: lane/ramp control status information bit4: current signal scheme color step information bit5: next cycle signal scheme color step information
}NET_IN_GET_RUNNING_INFO;

///@brief CLIENT_GetRtscRunningInfo Interface output parameters
typedef struct tagNET_OUT_GET_RUNNING_INFO
{
	DWORD                       dwSize;                      // Structure size
	DWORD						dwReportState;				 // bit0: running status
															 // bit1: way to control
															 // bit2: Lane function status
															 // bit3: Lane/ramp control status information
															 // bit4: Current signal scheme color step information
															 // bit5: Color step information for the next cycle signal scheme
	int							nLongitudeNum;				 // Number of longitudes
	double						dbLongitude[3];				 // Longitude, format: degrees, minutes, seconds (seconds are floating point numbers)
	int							nLatitudeNum;				 // Number of latitudes
	double						dbLatitude[3];				 // Latitude, format: degrees, minutes, seconds (seconds are floating point numbers)
	double						dbAltitude;					 // Height in meters
	NET_TIME_EX					UTC;						 //	Event occurrence time, UTC time with time zone offset, in seconds
	EM_STATUS					emStatus;					 // device status
	EM_CONTROL_MODE				emControlMode;				 // Control mode
	LANE_STATE					stuLaneStateInfo;			 // Lane function status
	LANE_CTRL_STATE				stuLaneCtrlStateInfo;		 // Lane/ramp control status
	CUR_STEP_INFO				stuCurStepInfo;				 // Current signal scheme color step information
	NEXT_STEP_INFO				stuNextStepInfo;			 // Color step information for the next cycle signal scheme
}NET_OUT_GET_RUNNING_INFO;

