///@brief Cron information
typedef struct tagNET_THINGS_TRIGGER_TIMER_CORN
{
	char				szSeconds[8];			// Seconds: 0 ~ 59 integers and special 4 characters(, - * /)
	char				szMinutes[8];			// Minutes: 0 ~ 59 integers and special 4 characters(, - * /)
	char				szHours[8];				// Hours: 0 ~ 23 integers and special 4 characters(, - * /)
	char				szDayofMonth[8];		// Day of Month: Integer from 1 to 31 (but you need to consider the number of days in your month) and special 8 characters(, - * ? / L W C)
	char				szMonth[8];				// Month: 1 ~ 12 integers or Jan-Dec and special 4 characters(, - * /)
	char				szDayofWeek[8];			// Day of Week: 1 ~ 7 integer or sun-sat and special 8 characters(, - * ? / L W C)
	char				szYear[8];				// Year: 1970 ~ 2099 integers and special 4 characters(, - * /)
	char				szReserve[256];			// reserve
}NET_THINGS_TRIGGER_TIMER_CORN;

