///@brief Collect File Data Details
typedef struct tagNET_COLLOCT_FILE_INFO
{
	UINT								nFileTotal;				// File Total Count
	UINT								nFileOkCounts;			// The number of successfully collected files
	UINT								nFileFailCounts;		// The number of failed files to be collected
	UINT								nFileTotalLength;		// The total length of the file, unit: bytes
	UINT								nFileOkTotalLength;		// The total size of the successfully collected file, unit: bytes
	UINT								nFileFailTotalLength;	// The total size of the failed collection files, unit: bytes
	char								szResvered[128];		// Reserved Byte
}NET_COLLOCT_FILE_INFO;

///@brief Collect device slot information
typedef struct tagNET_COLLECT_DEVICE_SLOT_INFO
{
	NET_COLLECT_DEVICE_SLOT_ID_INFO		stuSlotID;					// Slot ID
	int									nState;						// Slot status
																	// 0:No device is connected to the slot
																	// 1:The slot is connected to the device, and the slot door is not locked
																	// 2:The slot is connected to the device, and the slot door is unlocked
																	// 3:The slot is connected to the device, and the login status is unsuccessful.
																	// 4:The slot is connected to the device, and the login is locked.
																	// 5:The slot is connected to the device and successfully logged in, but the device is not bound to a law enforcement officer
																	// 6:The slot is connected to the device and successfully logged in, and the data is being collected.
																	// 7:The slot is connected to the device and successfully logged in, but the data collection is abnormal
																	// 8:The slot is connected to the device and successfully logged in, and the upgrade is in progress
																	// 9:The slot is connected to the device and successfully logged in, but the device upgrade fails
																	// 10:The slot is connected to the device and successfully logged in, and the device collection ends.
	BOOL								bPriorityCollectEnable;		// Whether the slot is enabled for data priority collection
	UINT								nCollectBindwith;			// Slot data collection bandwidth, unit byte
	UINT								nLock;						// Slot locked status, 0: Slot door locked, 1: Slot door unlocked
	char								szSerial[32];				// Serial number of the device being collected
	char								szName[64];					// The name of the device to be collected, valid for the logged-in state
	int									nBattery;					// 0~100: Indicates the current battery percentage of the collected device, -1: Indicates that the battery information has not been obtained
	UINT								nLoginTryCount;				// Indicates the number of consecutive failed logins to the collected device, valid when nState is 3 and 4
	UINT								nLoginLockLeftSeconds;		// The remaining time of the login lock, the unit is seconds, and it is valid when nState is 4
	UINT								nProcess;					// Upgrade progress percentage, range 0-100
	NET_COLLOCT_FILE_INFO				stuVideoFileInfo;			// Collected video file information
	NET_COLLOCT_FILE_INFO				stuAudioFileInfo;			// Collected audio file information
	NET_COLLOCT_FILE_INFO				stuPicFileInfo;				// Collected image file information
	char								szResvered[256];			// Reserved Byte
}NET_COLLECT_DEVICE_SLOT_INFO;

