typedef struct tagNET_OUT_GET_FILE_INFO_BY_PATH_INFO
{
	DWORD       				dwSize;         			            // The size of this structure must be assigned
	EM_FILE_UPDATE_STATE        emState;                                // The file upload status
	NET_TIME_EX                 stuStartTime;                           // File start time
	NET_TIME_EX                 stuEndTime;                             // File end time
	UINT                        nProgress;                              // File uploading progress
	UINT                        nCurrentSlice;                          // Current fragment (data required for slicing upload mode)
	TP_U64                      nFileLength;                            // Size of the file
	int                         nReason;                                // The cause of the error
																		// 0: The cause is unknown
																		// 1: The number of files exceeds the limit
																		// 2: The file storage space is full
																		// 3: The file is too large
																		// 4: invalid file type
																		// 5: No upload permission
																		// 6: The file name is abnormal
																		// 7: The file name is too long
																		// 8: The file name already exists
																		// 9: Visa inspection fails
	char                        szReserved[4];                          // Byte alignment
}NET_OUT_GET_FILE_INFO_BY_PATH_INFO;

