///@brief CLIENT_IVSEventFind Interface input parameter
typedef struct tagNET_IN_IVSEVENT_FIND_INFO
{
	DWORD       				dwSize;         			    // This structure size must be assigned
    int                         nVaild;                         // Diagonostic alarm type
                                                                // 0:All
                                                                // 1:Untreated
                                                                // 2:Correct alarm
                                                                // 3:Error alarm
                                                                // 4:Repeat correct alarm
                                                                // 5:Repeat error alarm

    NET_TIME                    stStartTime;                    // Start time
    NET_TIME                    stEndTime;                      // End time
    int                         nChannelList[128];              // Channel list
    DWORD                       dwChannelCnt;                   // nChannelList Indicates the number of valid channel ids. 0 indicates that all channel ids are queried
    DWORD                       dwEventCodeCnt;                 // Number of valid event types in dwEventCodeList
    DWORD                       dwEventCodeList[128];           // List of event types,refer to the event macro definition below this macro EVENT_IVS_ALL 
                                                                // Note Not all events can be queried. You need to enter the corresponding intelligent event type based on the IVS device

}NET_IN_IVSEVENT_FIND_INFO;

///@brief CLIENT_IVSEventFind Interface output parameter
