///@brief facial feature value related data
typedef struct tagNET_ACCESS_FACE_FRATURE_DATA
{
	char                                        szUserID[32];                        // User ID
	int                                         nFaceDataMD5Num;                     // Number of valid values of the first dimension length of the MD5 value array corresponding to the image
	int                                         nAlgorithmEigenMD5Num;               // The valid number of the first dimension length of the MD5 value array corresponding to the algorithm eigenvalue
	int                                         nEigenValueNum;                      // The number of significances in the first dimension of the eigenvalue data array
	int                                         nFeatureCompareResultNum;            // Apply eigenvalues and system eigenvalues to compare the number of significant first dimension length of the result array
	char                                        szFaceDataMD5[5][200];               // The image corresponds to the MD5 value
	char                                        szAlgorithmEigenMD5[5][200];         // MD5 value corresponding to the algorithm feature value
	char                                        szEigenValue[5][2048];               // Eigenvalue data, Max. 2k
	UINT                                        nFeatureCompareResult[5];            // The result of comparing the feature value with the system feature value is 0: the feature exists,1: the feature does not exist,2: the feature exists but the value is inconsistent,3: the feature exists and matches
																					 // When used together with nFeatureCompareResultNum, nFeatureCompareResultNum is used only when the result value is within the number of significant numbers
	char										szResvered[256];			         // Reserve bytes
}NET_ACCESS_FACE_FRATURE_DATA;

