	char									szChannelControlName[128];				// Channel Control Point Name
	double									dbChannelControlValue;					// Value of channel control points
	NET_IOTBOX_CHANNEL_DEVICE_INFO			stuDevices[128];						// Information of all sensors under the channel
	int										nDevicesNum;							// The number of information from all sensors in the channel
