///@brief CLIENT_CreateCert Input parameter
typedef struct tagNET_IN_CREATE_CERT_INFO
{
	DWORD						 dwSize;							/// Structure size
	EM_DIGITAL_CERTIFICATE_TYPE	 emDigitalCertificateType;			/// Certificate Management Type
	char						 szAlias[64];						/// Custom name
	EM_CERT_TYPE				 emType;					        /// Certificate Type 
	int							 nUsefulLife;						/// Certificate validity period, in days, with a range of [0-9999] days
	char						 szCountry[4];						/// Certificate holder's country code
	char						 szProvince[64];					/// Province where the certificate holder is located
	char						 szCity[64];						/// City where the certificate holder is located
	char						 szArea[64];						/// Code of the region where the certificate holder is located
	char						 szCommonName[160];					/// CN field, the same as the domain name, the array length supports a maximum of 63 characters. Please note that if you pass more than 63 characters, the function will fail
	char						 szOrganization[64];				/// The organization name of the certificate holder
	char						 szOrganizationUnit[64];			/// organization unit
	char						 szPubKeyAlg[64];					/// Certificate Public Key Algorithm
	UINT						 nCreationType;						/// Creation method: 0 represents automatic creation, 1 represents manual creation
}NET_IN_CREATE_CERT_INFO;

///@brief CLIENT_CreateCert Output parameters
typedef struct tagNET_OUT_CREATE_CERT_INFO
{
	DWORD						dwSize;						/// Structure size
	EM_CERT_TYPE				emType;					    /// Certificate Type 
	NET_TIME					stuEffectiveDate;			/// The effective date of the certificate, in the format of "YYYY-MM-DD hh: mm: ss"
	NET_TIME					stuExpirationDate;			/// Certificate expiration date
	char						szCertSN[40];			    /// Certificate sequence logical serial number
	char						szRealCertSN[80];			/// Certificate real serial number
	char						szDeviceIdentifier[160];	/// device identification
	int 						nFrom;    					/// Certificate source: 0: Private internal certificate (both certificate and private key are device generated), 1: Semi private internal certificate (private key is device generated, certificate is external imported), 2: External certificate (both certificate and private key are external imported)
}NET_OUT_CREATE_CERT_INFO;

///@brief Create certificate through internal non root level CA by device
///@param[in] lLoginID Login handle
