                                                            // AuthMaintenance ": Device Maintenance" Monitor_ $(Channel Number) ": Preview" Replay_ $(Channel Number) ": Playback" AuthTaskMag ": Task Management" AuthTraining ": Training Management" AuthRadar ": Radar Management
