typedef struct tagNET_ANALYZE_DATA_CALLBACK_INFO
{ 
	int 					nAlarmType; 		/// alarm type
	DWORD					dwBufSize;			/// pBuf lenth
	BYTE					*pBuffer;			/// Data cache area (SDK application release), users convert it into the corresponding structure based on nAlarmType
	void					*pAlarmInfo;		/// json information
	void					*reserved;			/// int nState = (int*) reserved Indicates the status of the current callback data. A value of 0 indicates that the current data is real-time, a value of 1 indicates that the current callback data is offline, and a value of 2 indicates that the offline data transfer has ended
	TP_U64					nEventUUID; 		/// Unique identification of an event
	int 					nSequence;			/// nSequenceIndicates the situation of uploading the same image. A value of 0 indicates the first occurrence, a value of 2 indicates the last or only occurrence, and a value of 1 indicates that there will be more occurrences after this time
	BOOL					bRealUTC;			/// Do you use RealTUTC time
	NET_TIME_EX             stuRealUTC;         /// Time of occurrence of the event (standard UTC time (without time zone daylight saving time deviation))
	char					szEventUUIDStr[32];	/// EventUUID String
	char					szReserved[948];	/// Reserved
}NET_ANALYZE_DATA_CALLBACK_INFO;

