///@brief Task status information
typedef struct tagNET_NOTIFY_SECURITY_IM_EXPORT_STATUS
{
    char                            szTaskType[16];         /// Current task type, "Import": Import task, "Export": Export task
    char                            szStatus[16];           /// Current task status, "Running": task execution in progress, "Succeeded": task execution successful, "Failed": task execution failed
    char                            szErrorCode[128];       /// error message
    UINT                            nProgress;              /// Current task execution progress percentage
	int                             nChannel;               /// channel
	int                             nErrorType;             /// error of import and export
		    												/// 10001 No exportable preset points
															/// 10002 Failed to generate environment during export
															/// 10003 Failed to package files during export
															/// 10004 Failed to generate environment during import
															/// 10005 Predefined point correction comparison failed during import
															/// 10006 The preset point matching pass rate is too low during import
															/// 10007 Failed to parse image data during import
															/// 10008 Failed to open file during import
															/// 10009 Failed to write file during import
	char							szResvered[1012];		/// Reserved bytes
}NET_NOTIFY_SECURITY_IM_EXPORT_STATUS;

