	double 								dbTotalSize;				/// Total length of task data, Double type, in bytes
	double 								dbWritedSize;				/// The length of the written data, Double type, in bytes
	char								szStartTime[32];			/// Start time, format: "2015-1-21 15:00:00"
	UINT								nTotalFileNum;				/// The total number of files that need to be backed up
	UINT								nFinishedFileNum;			/// Number of backed up files
