/// @brief CLIENT_GetPowerStatistics interface input parameters
typedef struct tagNET_IN_GET_POWER_STATISTICS_INFO
{
    DWORD                       dwSize;                     /// Structure size
    char                        szType[32];                 /// "Voltage": Query voltage data
                                                        /// "Power": Query power consumption data
                                                        /// "PowerMaintenanceInfo": Query power consumption statistics and maintenance information (e.g., daily power generation, consumption, and remaining power)
    char                        szDate[32];                 /// Query date, date format is "YYYY-MM-DD" (Year-Month-Day)
    char                        szReportType[32];           /// Report type "Day": Query daily report "Week": Query weekly report
} NET_IN_GET_POWER_STATISTICS_INFO;

/// @brief Power consumption statistics and maintenance information
typedef struct tagNET_POWER_MAINTENANCE_INFO
{
    UINT                        nPowerGeneration[24];       /// Power generation for each hour of the day (24h), unit Wh, range 0~7,200,000, 0 indicates invalid data
    UINT                        nPowerConsumption[24];      /// Power consumption for each hour of the day (24h), unit Wh, range 0~7,200,000, 0 indicates invalid data
    UINT                        nRemainingPower[24];        /// Real-time remaining power for each hour of the day (0%~100%)
    char                        szReserved[128];            /// Reserved bytes
} NET_POWER_MAINTENANCE_INFO;

/// @brief Collection of statistical data
typedef struct tagNET_POWER_STATISTICS_INFO
{
    char                        szTime[32];                         /// Time point of power consumption statistics, formatted according to the query range
                                                                /// For daily data, format is "HH:MM:SS" (Hour:Minute:Second)
                                                                /// For weekly data, format is "YYYY-MM-DD" (Year-Month-Day)
                                                                /// If the query data type is "PowerMaintenanceInfo", use RealUTC for the time point
    float                       fValue;                             /// Data for power consumption statistics, filled according to the inquiry type
                                                                /// Unit for voltage queries is volts; unit for power consumption queries is kilowatt-hours (kWh)
    NET_POWER_MAINTENANCE_INFO stuPowerMaintenanceInfo;           /// If the query data type is "PowerMaintenanceInfo", use this field to return electricity information statistics
    char                        szReserved[124];                    /// Reserved bytes
} NET_POWER_STATISTICS_INFO;

/// @brief CLIENT_GetPowerStatistics interface output parameters
typedef struct tagNET_OUT_GET_POWER_STATISTICS_INFO
{
    DWORD                       dwSize;                             /// Structure size
    int                         nStatisticInfoNum;                 /// Number of statistical data items
    NET_POWER_STATISTICS_INFO   stuStatisticInfo[1024];            /// Collection of statistical data
} NET_OUT_GET_POWER_STATISTICS_INFO;

